	\section{Proof of Theorem \ref{th:c5-stability}}
	\label{append:c5}
	\renewcommand{\theequation}{A\arabic{equation}}
	\renewcommand{\thetheorem}{A\arabic{theorem}}
	%	We first show in the following Lemma that the summation of local storage functions, as well as their derivatives, can be bounded by certain class $\mathcal{K}$ functions.

	\begin{lemma}\label{th:c5-couple}
		Consider the interconnected DAEs system \eqref{eq:c5-dae}. Assume that each dynamic subsystem \eqref{eq:c5-dbus} satisfies $delta$-D($X_i,\mathcal{D}_i$), with the corresponding storage function $S_i(x_i,u_i)$, each static subsystem \eqref{eq:c5-sbus} satisfies $delta$-D($X_i,\mathcal{D}_i$). Consider $\mathcal{D}_y$ defined as in equations \eqref{eq:c5-Dy}. If there exist $p_i>0$  $i=1,\dots,N$ such that for any $y\in\mathcal{D}_y$
		\begin{equation*}
			\begin{bmatrix}
				-\frac{\partial h_{net}}{\partial y}\\
			\end{bmatrix}^\text{T}P_\pi^\text{T}\text{blkdiag}(p_1X_1,\dots,p_{N}X_{N})P_\pi\begin{bmatrix}
				-\frac{\partial h_{net}}{\partial y}\\
			\end{bmatrix}
			\preceq0,
		\end{equation*}
		where $P_\pi$ is the permutation matrix such that $P_\pi\col(u,y)=\col(u_1,y_1\dots,u_N,y_N)$, then for the function $S(x,u):=\sum_{i=1}^{N_d}p_iS_i(x_i,u_i)$, there exist three class $\mathcal{K}$ functions $\alpha$, $\beta$, and $\gamma$ such that
		\begin{equation*}
			\alpha(\|f(x,u)\|)\leq S(x,u)\leq\beta(\|f(x,u)\|),\forall (x,u)\in\mathcal{D}_G 
		\end{equation*}
		\begin{equation*}
			\dot{S}(x,u)\leq-\gamma(\|f(x,u)\|),\;\forall (x,u)\in\mathcal{D}_G 
		\end{equation*}
	\end{lemma}
	\begin{proof}
		1) By Definition \ref{de:IODP}, there exist class $\mathcal{K}$ functions $\alpha_i$ and  $\beta_i$, $i=1,\dots,N_d$ such that for any $(x,u)\in\mathcal{D}_G$ we have
		\begin{equation*}
			\sum_{i=1}^{N_d}p_i\alpha_i(\|f_i\|)\leq S(x,u)\leq\sum_{i=1}^{N_d}p_i\beta_i(\|f_i\|)
		\end{equation*}
		For $r\in[0,\infty)$, define the set of $N_d$-dimensional positive quadrant with radius $r$ as $$D(r):=\left\{(r_1,\dots,r_{N_d})\in[0,\infty)^{N_d}\big|\|(r_1,\dots,r_{N_d})\|=r\right\}$$
		Define the functions
		\begin{equation*}
			\alpha(r):=\min_{(r_1,\dots,r_{N_d})\in D(r)}\left(p_1\alpha_1(r_1)+\dots+p_{N_d}\alpha_n(r_{N_d})\right)
		\end{equation*}
		and
		\begin{equation*}
			\beta(r):=p_1\beta_1(r)+\dots+p_{N_d}\beta_{N_d}(r)
		\end{equation*}
		Since $p_i>0$, one can verify that $\alpha(r)$ and $\beta(r)$ are both class $\mathcal{K}$ functions on $[0,\infty)$. Noting $f=\col(f_1,\dots,f_{N_d})$, we have
		\begin{equation*}
			\alpha(\|f\|)\leq\sum_{i=1}^{N_d}p_i\alpha_i(\|f_i\|)
		\end{equation*}
		\begin{equation*}
			\sum_{i=1}^{N_d}p_i\beta_i(\|f_i\|)\leq\sum_{i=1}^{N_d}p_i\beta_i(\|f\|)=\beta(\|f\|)
		\end{equation*}
		Hence, for any $(x,u)\in\mathcal{D}_G$, we have $\alpha(\|f(x,u)\|)\leq S(x,u)\leq\beta(\|f(x,u)\|)$.

		2) By Definition \ref{de:IODP} and \ref{de:IODPs}, there exists class $\mathcal{K}$ functions $\gamma_i$, $i=1,\dots,N_d$ such that for any $(x,u)\in\mathcal{D}_G$ we have
		\begin{equation*}
			\dot{S}(x,u)\leq
			\sum_{i=1}^{N}p_i\begin{bmatrix}
				\dot{u}_i\\\dot{y}_i
			\end{bmatrix}^\text{T}
			X_i
			\begin{bmatrix}
				\dot{u}_i\\\dot{y}_i
			\end{bmatrix}-\sum_{i=1}^{N_d}p_i\gamma_i\left(\|f_i\|\right)
		\end{equation*}
		It follows from the definition of $P_\pi$ that
		\begin{equation*}
			\begin{aligned}
				\sum_{i=1}^{N}p_i\begin{bmatrix}
					\dot{u}_i\\\dot{y}_i
				\end{bmatrix}^\text{T}
				&X_i
				\begin{bmatrix}
					\dot{u}_i\\\dot{y}_i
				\end{bmatrix}\\
				&=\begin{bmatrix}
					\dot{u}\\ \dot{y}
				\end{bmatrix}^\text{T}P_\pi^\text{T}\text{blkdiag}(p_1X_1,\dots,p_{N}X_{N})P_\pi\begin{bmatrix}
					\dot{u}\\ \dot{y}
				\end{bmatrix}
			\end{aligned}
		\end{equation*}
		On the other hand, the network coupling \eqref{eq:c5-HN} determines the algebraic relation $-u=h_{net}(y)$ between $u$ and $y$. Hence,
		\begin{equation*}
			\begin{bmatrix}
				\dot{u}\\ \dot{y}
			\end{bmatrix}=\begin{bmatrix}
				-\frac{\partial h_{net}(y)}{\partial y}\\I
			\end{bmatrix}\dot{y}
		\end{equation*}
		Thus, by \eqref{eq:c5-global} and noting that $\mathcal{D}_y$ is the image of $\mathcal{D}_G$ under $h(x,u)$, it follows that for an arbitrary $(x,u)\in\mathcal{D}_G$ we have
		\begin{equation*}
			\sum_{i=1}^{N}p_i\begin{bmatrix}
				\dot{u}_i\\\dot{y}_i
			\end{bmatrix}^\text{T}
			X_i
			\begin{bmatrix}
				\dot{u}_i\\\dot{y}_i
			\end{bmatrix}\leq0
		\end{equation*}

		Similarly, for any $r\in[0,\infty)$ define the function
		\begin{equation*}
			\gamma(r):=\min_{(r_1,\dots,r_{N_d})\in D(r)}\left(p_1\gamma_1(r_1)+\dots+p_{N_d}\gamma_n(r_{N_d})\right)
		\end{equation*}
		We can verify that $\gamma(r)$ is a class $\mathcal{K}$ function on $[0,\infty)$ and
		\begin{equation*}
			\gamma(\|f\|)\leq\sum_{i=1}^{N_d}p_i\gamma_i(\|f_i\|)
		\end{equation*}
		Hence, for any $(x,u)\in\mathcal{D}_G$ we have $\dot{S}(x,u)\leq-\gamma(\|f(x,u)\|)$, which completes the proof.
	\end{proof}
