\title{Mapping the changing structure of science through diachronic periodical embeddings}

\author{Zhuoqi Lyu\orcidlink{0000-0002-5787-0862}}
\affiliation{Department of Data Science, College of Computing, City University of Hong Kong, Hong Kong, China}

\author{Qing Ke\orcidlink{0000-0002-2945-5274}}
\email{Correspondence to q.ke@cityu.edu.hk}
