		This appendix demonstrates that the Jacobian matrix $Dp(x,t,\nu;\alpha)$ of $p(x,t,\nu;\alpha)$ has full-row rank on the domain $\mathbb{R}^{n_0}\times(0,2)\times\mathbb{R}^{m_0}\times\mathbb{R}^{n_0}$, and that $Dp_\alpha(x,2,\nu)$ maintains full-row rank on $\mathbb{R}^{n_0}\times\mathbb{R}^{m_0}$, a property essential for the proof of Theorem~\ref{nfpe-thm-log4}.\par
		Defining $g(x,t,\nu;\alpha)$ as the initial $n_0$ components of $p(x,t,\nu;\alpha)$, we write the Jacobian matrix $Dp(x,t,\nu;\alpha)$ as
		\begin{equation}
			Dp(x,t,\nu;\alpha)=\left(\begin{array}{cccc}
				D_{x} g&D_t g&D_\nu g&-c(t)(2-\theta(t))I^{n_0\times n_0} \\
				B_1+B_2&C&0&0\\
			\end{array}\right),
			\nonumber
		\end{equation}
		where $I^{n_0\times n_0}$ denotes the identity matrix,
		\begin{equation}
			B_1=\left(\begin{array}{cccc}
				{b^1_1}^\top&&&\\
				&{b^2_1}^\top&&\\
				&&\ddots&\\
				&&&{b^{m_n}_n}^\top
			\end{array}\right)\in \mathbb{R}^{m_0\times n_0} \text{ with } b^{j}_i=(\frac{d}{dx^i(w^i_{I^j_i}a)}\gamma^i(x,t;w^i_{I^j_i}a):a\in A(I^j_i))^\top\in\mathbb{R}^{|A(I^j_i)|}.
			\nonumber
		\end{equation}
		The matrix $B_2\in \mathbb{R}^{m_0\times n_0}$ assigns to each element, where both row and column indices correspond to $w^i_{I^j_i}\neq\emptyset,i\in N,j\in M_i$, the value $(\theta(t)-1)d\gamma^i(x,t;w^i_{I^j_i})/dx^i(w^i_{I^j_i})$, with remaining entries zero. The vector $C\in\mathbb{R}^{m_0}$ represents the partial derivative of the last $m_0$ components of $p(x,t,\nu;\alpha)$ with respect to $t$. Since both $I^{n_0\times n_0}$ and $B_1+B_2$ are of full-row rank, the Jacobian matrix $Dp(x,t,\nu;\alpha)$ has full-row rank on $\mathbb{R}^{n_0}\times(0,2)\times\mathbb{R}^{m_0}\times\mathbb{R}^{n_0}$.\par
		When $t=2$, the system~(\ref{nfpe-eqt-log4}) is reduced into
		\begin{equation*}\label{nfpe-eqt-apn1}\begin{array}{l}
				\lambda^i(x,2;w^i_{I^j_i}a)-\nu^i_{I^j_i}=0,\;i\in N,j\in M_i,a\in A(I^j_i),\\
