			\end{array}
		\end{equation*}
		The Jacobian matrix then takes the form
		\begin{equation}
			Dp_\alpha(x,2,\nu)=\left(\begin{array}{cc}
				F&-E\\
				B_1&0\\
			\end{array}\right),
			\nonumber
		\end{equation}
		where
		\begin{equation}
			E=\left(\begin{array}{cccc}
				{e^1_1}&&&\\
				&{e^2_1}&&\\
				&&\ddots&\\
				&&&{e^{m_n}_n}
			\end{array}\right)\in \mathbb{R}^{n_0\times m_0} \text{ with } e^{j}_i=(1,1,\ldots,1)^\top\in\mathbb{R}^{|A(I^j_i)|},
