		\end{equation}
		and $F=\text{diag}(d\lambda^i(x,2;w^i_{I^j_i}a)/dx^i(w^i_{I^j_i}a): i\in N,j\in M_i,a\in A(I^j_i))$. By applying row and column operations to $Dp_\alpha(x,2,\nu)$, we obtain
		\begin{equation}
			Dp_\alpha(x,2,\nu)=\left(\begin{array}{cc}
