Here we give the details and proofs corresponding to the fixed-parameter tractability section concerning \textsc{Strong} \CycleDetection. Let us start with a pseudo-code implementation. We choose a list structure for the search path $P$, and besides the typical list and array operations, function $A$ returns the arcs adjacent to a given vertex, and the other undefined functions (e.g. \texttt{earliestAtLeast}) should be clear from the context and function name. 

\begin{algorithm}[]
\DontPrintSemicolon
\caption{\texttt{containsStrongCycle}}\label{algo:full_cycle_detection}
\SetKwInOut{Input}{Input}
\SetKwInOut{Output}{Output}

\Input{temporal digraph $\mathcal{D}$}
\Output{\texttt{true} if $\mathcal{D}$ contains a \strongcycle, \texttt{false} otherwise}	
\For{%$a = (r,v)$ changed arc
	$a = rv$ \texttt{in} $A(\mathcal{D})$}{ 
	$P \gets $ \texttt{newList}$(r, v)$ \tcp*{search path}
	$T_r \gets$ $[0] * (\tau + 1)$ \tcp*{root timetable} 
	\For{$t \in [0, ..., \max(\lambda(a))]$}{
		$T_r[t] \gets \texttt{earliestAtLeast}(\lambda(a), t)$\tcp*[f]{EAT$_P^{\geq t}(r,v)$} 
	}
	$T_P \gets$ $[0] * (\tau + 1)$ \tcp*{path timetable} 
	$T_P[\tau] \gets \texttt{min}(\lambda(a))$ \tcp*[]{LDT$_P(r,r)$ and EAT$_P(r,v)$} 
	% $T_P[] \gets \texttt{min}(\lambda(a))$ \tcp*{$[$EAT$(r,v),$ LDT$(r, r)]$}
	% \texttt{add}($W_p$, $[0, \texttt{max}(\lambda(a))]$) \tcp*{$[$EAT$(v,v),$ LDT$(r, v)]$}
	% $T \gets \texttt{newStack}((T_r, T_P))$ \tcp*{timetables stack}
	$B \gets ([\texttt{false}] * m) * 4^{(\tau+1)^2}$ \tcp*{blocking matrix}
	\lIf{$\texttt{searchStrongCycle}(\mathcal{D}, P, T_r, T_P, B)$}
	{
		\Return \texttt{true}
	}
}
\Return \texttt{false}\;
\end{algorithm}	

\begin{algorithm}[]
\DontPrintSemicolon
\caption{\texttt{searchStrongCycle} (see also \Cref{fig:strong_cycle_search})}\label{algo:search_full_cycle}
\SetKwInOut{Input}{Input}
\SetKwInOut{Output}{Output}

\Input{temporal digraph $\mathcal{D}$, search path $P$, root and path timetables $T_r$ and $T_P$, and blocking matrix $B$}
\Output{\texttt{true} iff the current search path $P$ results in a strong-cycle}

%$(T_r, T_P) \gets \texttt{peek}(T)$\;
$u \gets \texttt{last}(P)$\;
\For{%$a = (u, v)$ changed arc
	$a = uv$ \texttt{in} $A(u)$}{ 
	\If(\tcp*[f]{$a$ doesn't block $T_r$ and $T_P$}){\texttt{not} $B[\texttt{order}(a)][\texttt{order}(T_r, T_P)]$}{
		% $i_u \gets \texttt{maxIndexWithNonZeroValue}(T_r)$\;
		$(T'_{r}, T'_{P},$ extended) $\gets \texttt{extend}(T_r, T_p, \lambda(a))$ \;
		\If{$extended$}
		{
			\lIf{$v \in P$}{\Return{\texttt{true}}}\label{line:returnTrue}
			% $w_v \gets [0, \texttt{max}(W_{r+1}, \texttt{key}=\texttt{lambda }[a,b] : a)]$ \tcp*{$[0$, LDT$(r, v)]$}
			% $T'_P[$index$] \gets \max(T'_P[$index$], \min(\lambda(a)))$\;
			% $w_v \gets [0, \texttt{max}(t \texttt{ for } [t, \_] \in W_{r+1})]$ \tcp*{$[$EAT$(v, v)$, LDT$(r, v)]$}
			% % $w_v \gets [0, \texttt{LDT}(P, r, v)]$\;
			% \texttt{add}$(W_{p+1}, w_v)$\; 
%			\texttt{add}$(T, (T'_{r}, T'_{P}))$\;	
			\texttt{add}$(P, v)$\;
			\lIf{\texttt{searchStrongCycle}$(\mathcal{D}, P, T'_r, T'_P, B)$}
			{
				\Return \texttt{true} 
			}
%			\texttt{pop}$(T)$\;
			\texttt{remove}$(P, v)$\;
		}
		$B[\texttt{order}(a)][\texttt{order}(T_r, T_P)] \gets \texttt{true}$ \tcp*[f]{block $T_r$ and $T_P$ on $a$}
	}
}
\Return \texttt{false}\;
\end{algorithm}	

\begin{algorithm}[]
\DontPrintSemicolon
\caption{\texttt{extend}}\label{algo:extend}
\SetKwInOut{Input}{Input}
\SetKwInOut{Output}{Output}

\Input{Root timetable $T_r$, path timetable $T_P$, and arc $a = uv$}
\Output{Root timetable $T'_{r}$ and path timetable $T'_{P}$, corresponding to the input timetables extended over $a$, and a boolean value that flags \texttt{false} if the path timetable cannot extend correctly}

$T'_{r} \gets \texttt{copy}(T_r)$\;
$T'_{P} \gets \texttt{copy}(T_P)$\;
\For{$t$ \texttt{in} $[1, ..., \tau]$}{ 
	\If{$T_r[t] > 0$ \texttt{and} \texttt{containsAtLeast}$(\lambda(a), T_r[t]+1)$}
	{
		$T'_r[t] \gets \texttt{earliestAtLeast}(\lambda(a), T_r[t]+1)$ \tcp*[f]{update EAT$_P^{\geq t}(r, v)$}
	}
	\lElse(){
		$T'_r[t] \gets 0$} 
	\If{$T_P[t] > 0$ \texttt{and} \texttt{containsBetween}$(\lambda(a), T_P[t], t+1)$}
	{
		$T'_P[t] \gets \texttt{earliestBetween}(\lambda(a), T_P[t], t+1)$\tcp*[f]{update EAT$_P(\_,v)$}
	}
	\lElse{\Return ($T_r, T_P, \texttt{false}$)}
}
$i \gets \texttt{maxIndexWithNonZeroValue}(T_r)$\tcp*[]{LDT$_P(r,u)$}
$T'_{P}[i-1] \gets \max(T'_{P}[i-1], \min(\lambda(a)))$\tcp*[]{add EAT$_P(u,v)$}
\Return $(T'_{r}, T'_{P}, \texttt{true})$\;
\end{algorithm}	

