    \includegraphics[width=0.95\columnwidth]{figs/method2_schematic.jpg}
    \caption{Schematic of Method 2: Ensemble-Based Covariance Propagation. Both data-driven and dynamic models use the same framework for covariance estimation based on ensemble perturbation.}
    \label{fig:method2}
