\subsection{Bilinear complexity}
%In the following discussion, all rings are commutative rings except additional instructions.
For convenience, we collect some basic facts about the bilinear complexity. The standard reference for this subsection is \cite{burgisser2013algebraic}.
\begin{definition}\label{def2}
Let $\mathcal{R}$ be a commutative ring and let $\mathbb{U},\mathbb{V},\mathbb{W}$ be finitely generated free $\mathcal{R}$-modules. The bilinear complexity (or rank) of a $\mathcal{R}$-bilinear map $f: \mathbb{U} \times \mathbb{V} \to \mathbb{W}$, denote by $\rank_{\mathcal{R}}(f)$, is the smallest positive integer $r$ to ensure the existence of $\alpha_j \in \Hom (\mathbb{U},\mathcal{R}),\beta_j \in \Hom (\mathbb{V},\mathcal{R})$ and $w_j \in \mathbb{W}$, $1 \le j \le r$, such that
\[
f (u,v) = \sum_{j=1}^r \alpha_j (u) \beta_j(v) w_j, \quad (u,v)\in \mathbb{U}\times \mathbb{V}.
\]
\end{definition}
We denote by $C_{\mathcal{R}}(f)$ the total number of arithmetic operations required to compute $f$ over $\mathcal{R}$. In the literature, $C_{\mathcal{R}}(f)$ is called the \emph{total complexity} of $f$. It is obvious that
\begin{equation}\label{eqn:rank<complexity}
\rank_{\mathcal{R}}(f) \le C_{\mathcal{R}}(f).
\end{equation}
Let $\mathcal{S}$ be a commutative ring containing $\mathcal{R}$ as a sub-ring. For each free $\mathcal{R}$-module $\mathbb{U}$, we denote $\mathbb{U}^{\mathcal{S}} \coloneqq \mathbb{U} \otimes_{\mathcal{R}} \mathcal{S}$. Similarly, if $f:\mathbb{U}\times \mathbb{V} \to \mathbb{W}$ is a $\mathcal{R}$-bilinear map, then we denote by $f^{\mathcal{S}}: \mathbb{U}^{\mathcal{S}} \times \mathbb{V}^{\mathcal{S}} \to \mathbb{W}^{\mathcal{S}}$ the $\mathcal{S}$-bilinear map obtained by extending $f$ naturally. By definition, we have 
\begin{equation}\label{eqn:rank extn}
\rank_{\mathcal{S}} (f^{\mathcal{S}}) \le \rank_{\mathcal{R}} (f).
\end{equation}
%\begin{definition}
%Given a ring $R$, $R-$modules $U,V,W$ and a bilinear map $f:U\times V\to W$. $f$ can be viewed as a tensor $T\in Hom(U,R)\otimes Hom(V,R)\otimes W$. The \emph{border rank} of $f$ is the border rank of $T$, which is denoted by $\underline{\mathcal{R}}_{R}(f)$
%\label{def3}
%\end{definition}
If there exist finitely generated free $\mathcal{R}$-modules $\mathbb{U}', \mathbb{V}', \mathbb{W}'$, $\mathcal{R}$-bilinear map $f': \mathbb{U}' \times  \mathbb{V}' \to \mathbb{W}'$ and $\mathcal{R}$-linear maps $\varphi_1:\mathbb{U} \to \mathbb{U}'$, $\varphi_2:\mathbb{V} \to \mathbb{V}'$ and $\varphi_3:\mathbb{W}' \to \mathbb{W}$ such that $f = \varphi_3 \circ f' \circ (\varphi_1 \times \varphi_2)$, then we say that \emph{$f$ is a restriction of $f'$}, denoted by $f \le f'$. Clearly, $f \le f'$ implies
 \begin{equation}\label{eqn:rank restriction}
\rank_{\mathcal{R}} (f) \le \rank_{\mathcal{R}} (f').
\end{equation}
