\subsection{Exponent of matrix multiplication}
Let $\mathcal{R}$ be a commutative ring. We denote by $\langle m,n,p\rangle_{\mathcal{R}}$ the $\mathcal{R}$-bilinear map of multiplying an $m\times n$ matrix with an $n\times p$ matrix over $\mathcal{R}$. The \emph{exponent of matrix multiplication} over $\mathcal{R}$ is \[
\omega(\mathcal{R}) \coloneqq \inf \lbrace 
\tau \in \mathbb{R}: C_{\mathcal{R}} (\langle n,n,n\rangle_{\mathcal{R}}) = O(n^\tau) 
\rbrace.\]
The same proof of Corollary~15.18 in \cite{burgisser2013algebraic} leads to:
\begin{lemma}\label{lem:rank matrix extn}
For any commutative $\mathcal{k}$-algebra $\mathcal{R}$, $\omega(\mathcal{R}) = \omega(\mathcal{k})$.
\end{lemma}
Because of Lemma~\ref{lem:rank matrix extn}, we simply abbreviate $\omega(\mathcal{R})$ by $\omega$. The proof of Theorem~15.11 in \cite{burgisser2013algebraic} can be extended to show:
\begin{theorem}\label{thm5}
If there exist positive integers $e_{i},h_{i},l_{i}$, $1\le i \le s$, such that $\rank_{\mathcal{R}} \left(\bigoplus\limits_{i=1}^{s}\langle e_{i},h_{i},l_{i}\rangle_{\mathcal{R}}\right)\le \tau$, then $\sum\limits_{i=1}^s (e_{i}h_{i}l_{i})^{\omega/3}\le\tau$.
 \end{theorem}
 %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{\'{E}tale algebra and Galois algebra}\label{subsec:etale algebra}
Let $\mathcal{k}$ be a field and let $\mathcal{A}$ be a finite \'{e}tale $\mathcal{k}$-algebra, i.e., $\mathcal{A}$ is a finite product of finite separable field extensions of $\mathcal{k}$. 
\begin{theorem}[primitive element theorem]\cite[Proposition~4.1]{UZ17}\label{thm:primitive element thm}
If $\mathcal{k}$ is an infinite field and $\mathcal{A}$ is a finite \'{e}tale $\mathcal{k}$-algebra, then there exists $a\in \mathcal{A}$ such that $\mathcal{A} = \mathcal{k}[a]$.
\end{theorem}
Assume further that $\sigma$ is an automorphism of $\mathcal{A}$ such that $\mathcal{A}^{\sigma} = \mathcal{k}$ and the cyclic group $\langle \sigma \rangle$ generated by $\sigma$ has order $r = \dim_{\mathcal{k}} \mathcal{A} > 1$. We say that $\mathcal{A}$ is a \emph{$\langle \sigma \rangle$-Galois algebra} \cite[Section~18.~B]{Knus98}. Examples of $\langle \sigma \rangle$-Galois algebras include:
\begin{itemize}
\item \textbf{totally split $\mathcal{k}$-algebra}: $\mathcal{A} = \mathcal{k}^r$ and $\sigma$ is defined by the cyclic left shift $(a_1,\dots, a_{r-1}, a_r) \mapsto (a_2,\dots, a_r, a_1)$. 
\item \textbf{Kummer extension}: $\mathcal{A} = \mathcal{k}(a)$ and $\sigma$ is defined by $a \mapsto \zeta a$, where $\zeta \in \mathcal{k}$ is a primitive $r$-th root of unity and $a^r \in \mathcal{k}$.
\item \textbf{Artin extension}: $\mathcal{A} = \mathcal{k}(a)$ and $\sigma$ is defined by $a \mapsto a + 1$, where $\operatorname{char}(\mathcal{k}) = r$ and $a^r - a \in \mathcal{k}$.
\end{itemize}
%$L$ is an \'{e}tale algebra and is a cyclic Galois extension of field $K$. $Gal(L/K)=G$ and $G$ is generated by $\sigma$. $[L:K]=r$.
\subsection{Skew polynomial ring}
Let $\mathcal{A}$ be a $\langle \sigma \rangle$-Galois algebra. The \emph{skew polynomial ring} $\mathcal{A}[x,\sigma]$ is the ring whose underlying group is $\mathcal{A}[x]$ and the multiplication is defined by $x x^{d} = x^{d} x =  x^{d+1}, x a=\sigma(a) x$ for $d\in \mathbb{N}, a\in \mathcal{A}$. Since $r > 1$, $\mathcal{A}[x,\sigma]$ is a non-commutative graded $\mathcal{k}$-algebra. We denote by $\mathcal{A}[x,\sigma]_d$ (resp. $\mathcal{A}[x,\sigma]^d$) the subspace consisting of polynomials of degree $d$ (resp. at most $d$). For ease of reference, we record two basic properties of $\mathcal{A}[x,\sigma]$ below.
 \begin{lemma}\cite[Lemma~1.4]{2017Fast} \label{lem6}
     The map $\varphi: \mathcal{A}[x,\sigma]\to End_{\mathcal{k}}(\mathcal{A})$ sending $\sum_{i} a_{i} x^{i}$ to $\sum_{i}a_{i}\sigma^{i}$ is a surjective homomorphism of $\mathcal{k}$-algebras whose kernel is $(x^r - 1)$.
 \end{lemma}
\begin{lemma}\cite[Proposition~2.7]{2017Fast}    \label{lem7}
    Let $p_{1}, \dots,p_{m}\in \mathcal{k}[x]$ be pairwise coprime and let $p= \prod_{j=1}^m p_j$. The natural map:
    \begin{equation*}
        \mathcal{A}[x,\sigma]/p(x^{r})\to \mathcal{A}[x,\sigma]/p_{1}(x^{r})\times\cdots \mathcal{A}[x,\sigma]/p_{m}(x^{r})
    \end{equation*}
    is a $\mathcal{k}$-algebra isomorphism.
\end{lemma}
Let $\mathcal{k}^{r\times r}$ be the algebra of $r\times r$ matrices over $\mathcal{k}$. The following is a direct consequence of \cite[Proposition~30.6]{Knus98}.
