Since $I_1 = (XA - \zeta A X)$ is homogeneous, $\mathcal{k} \langle X,A\rangle/I_{1}$ is bi-graded. We denote $\deg_X(F)$ (resp. $\deg_A(F)$) the degree of $X$ (resp. $A$) in $f\in \mathcal{k} \langle X,A\rangle$. We say that $F$ has bi-degree $(\deg_X(F),\deg_A(F))$. Given $d ,e \in \mathbb{N}$, we denote $\left( \mathcal{k}\langle X,A\rangle/I_{1} \right)^{d,e} \coloneqq \operatorname{span}_{\mathcal{k}} \lbrace X^{i}A^{j}: 0\le i \le d, 0\le j\le e \rbrace$. Let $\pi_3$ the natural quotient map $\mathcal{k} \langle X, A\rangle/I_{1} \to \mathcal{k} \langle X, A\rangle/ (I_{1}+I_{3})$.
%has a graded structure with respect to $y$ and $z$. We use $deg_{y}(P)$ or $deg_{z}(P)$ to denote the maximal degree of maximal terms $y$'s or $z$'s power in $P\in K\langle y,z\rangle/I_{1}$
\begin{algorithm}[!htbp]

        \SetAlgoLined

		\KwIn{ $F_1, F_2\in \left( \mathcal{k}\langle X,A \rangle/I_{1}\right)^{d,e}$}
		%in the form $\sum\limits_{i=0}^{d}\sum\limits_{j=0}^{e}\lambda_{ij}y^{i}z^{j}$
		\KwOut{$F_1 F_2$}
		%multiplication of $CD$ in the form $\sum\limits_{i=0}^{2d}\sum\limits_{j=0}^{2e}\lambda_{ij}y^{i}z^{j}$
        Compute $d_1 = \deg_{X}(F_1)$, $e_1 = \deg_{A}(F_1)$, $d_2 = \deg_{X}(F_2)$, $e_2 =\deg_{A}(F_2)$\;
		Compute $G_1 = \pi_3(F_1)$ and $G_2 = \pi_3(F_2)$\;
        Compute $M_1 = \varphi(G_1)$ and $M_2 = \varphi(G_2)$\; 
        Compute $M = M_1 M_2$\; \label{alg2:step4}
        Compute $G = \varphi^{-1}(M)$\; \label{alg-2:step5}
        Find $F \in \left( \mathcal{k} \langle X,A\rangle/I_{1}\right)^{d_1+ d_2, e_1 + e_2}$ such that $\pi_3(F)= G$\;\label{alg-2:step6}
        Return $F$.
        \caption{multiplication on $\left( \mathcal{k} \langle X,A\rangle/I_{1} \right)^{d,e}$}
        \label{alg-2}
	\end{algorithm}
\begin{lemma}\label{lem21}
Let $\mathcal{k}$ be a field containing a primitive $r$-th root of unity and let $d, e < r/3$ be positive integers. Algorithm~\ref{alg-2} computes the multiplication of two elements in $\left( \mathcal{k}\langle X, A\rangle/I_{1} \right)^{d,e}$ by $\widetilde{O}(d^{\omega-1}r)$ arithmetic operations. 
\end{lemma}
\begin{proof}
We first prove that $F = F_1 F_2$. By definition, $F_1 F_2$ has bi-degree $(d_1 + d_2, e_1 + e_2)$. Since $\pi_3$ and $\varphi$ are $\mathcal{k}$-algebra homomorphisms and $\varphi$ is an isomorphism, $\pi_3(F_1 F_2)=\varphi^{-1}(\varphi(\pi_3(F_1))\varphi(\pi_3(F_2))) = G$. Hence $F_1 F_2$ is a solution for Step~\ref{alg-2:step6} in Algorithm~\ref{alg-2}. Thus it suffices to prove that it is also unique. Indeed, if $\pi_3(F') =\pi_3(F) = G$ for some $F,F'\in \left( \mathcal{k} \langle X,A\rangle/I_{1}\right)^{d_1+ d_2, e_1 + e_2}$, then $F'-F\in (I_1 + I_{3})/I_1$.
% and $F,F '\in K\langle y,z\rangle/I_{1}$. 
Since a nonzero element in $(I_1 + I_{3})/I_1$ has bi degree $(l,m)$ where $\min\{l,m\} \ge r > \max\{3d, 3 e\} >\max\{d_1 + d_2, e_1 + e_2\}$, we obtain $F' = F$.
%$y-$degree at least $r>3d>deg(C)+deg(D)$. $E-E'$ has degree at most $deg(C)+deg(D)$ hence it must be 0.

Next we analyze the complexity. Clearly, the cost of the first three steps of Algorithm~\ref{alg-2} is $O(dr)$. Since $F_1, F_2 \in \left(\mathcal{k}\langle X,A\rangle/I_{1}\right)^{d,r-1}$, we may deduce from the definition of $\varphi$ in Lemma~\ref{lem20} that matrices $M_1, M_2$ in Step~\ref{alg2:step4} are of the same form as those in Lemma~\ref{lem15}. Thus $M = M_1 M_2$ can be computed by $\widetilde{O}(d^{\omega-1}r)$ arithmetic operations.
%are in the form $\sum\limits_{i=0}^{r-1}\sum\limits_{j=0}^{d}\lambda_{ij}A^{i}B^{j}$. This kind of matrices are those whose nonzero elements are in $d$ given adjacent diagonals. By Lemma~\ref{lem15}, STEP 4 can be computed in $\widetilde{O}(d^{\omega-1}r)$ arithmetic operations.
Step~\ref{alg-2:step5} is equivalent to determining $\mu_{ij}\in \mathcal{k}$ such that $M =\sum\limits_{i=0}^{2d}\sum\limits_{j=0}^{2e}\mu_{ij} \alpha^{j} \beta^{i}$, where $\alpha$ and $\beta$ are matrices given in Lemma~\ref{lem20}. 
%Step~\ref{alg-2:step5} is actually equivalent to determine $\mu_{ij}$ from $U$. 
By definition of $\alpha$ and $\beta$, it is sufficient to find polynomials $f_1,\dots, f_{2d+1} \in \mathcal{k}[t]$ of degree at most $2e$ such that
\begin{equation}\label{lem:kummer:eqn:interpolation}
    f_{k}(\zeta^{l})= M_{l+1, l +k},\quad 0 \le l \le r-1, 1 \le k \le 2d+1.
\end{equation}
Here $l  +k$ is understood as $l  + k -r$ if $l + k > r$. 
%Here all index of the above equation are mod $r$. 
Since $2e + 1 < r$, the interpolation problem \eqref{lem:kummer:eqn:interpolation} in general has no solution. However, the correctness of Algorithm~\ref{alg-2} ensures that \eqref{lem:kummer:eqn:interpolation} is solvable. Hence we can compute $f_{k}$'s by polynomial interpolation at $2e+1$ points $\zeta^i, 0 \le i \le 2e$. Each interpolation can be done by a fast Fourier transform, which costs $\widetilde{O}(e)$ arithmetic operations \cite[Theorem~2.6]{burgisser2013algebraic}. Thus, the cost of of Step~\ref{alg-2:step5} is $\widetilde{O}(de)$ arithmetic operations. 
%Each interpolation can be done with $\widetilde{O}(e)$ arithmetic operations (this can be found as \textbf{Fast Polynomial Interpolation} in \cite{burgisser2013algebraic}). 
It is obvious that Step~\ref{alg-2:step6} only costs $O(dr)$ operations. 

Lastly, since $d, e < r$, the above analysis implies that the total cost of Algorithm~\ref{alg-2} is $\widetilde{O}(d^{\omega - 1} r)$. 
\end{proof}
