 \begin{lemma}\label{lem28}
 Given $F =\sum_{i=0}^{d}\sum_{j=0}^{r-1}\lambda_{ij}X^{i} A^{j}$ in $\mathcal{k} \langle X, A \rangle/J_1$, Algorithm~\ref{alg-5} computes $\mu_{ij}\in \mathcal{k}, 0 \le i \le d, 0 \le j \le r-1$ such that $F=\sum_{i=0}^{d}\sum_{j=0}^{r-1}\mu_{ij}A^{j}X^{i}$ by $\widetilde{O}(dr)$ arithmetic operations. Similarly, if $F =\sum_{i=0}^{d}\sum_{j=0}^{r-1}\mu_{ij}z^{j}y^{i}\in  \left( \mathcal{k} \langle X, A \rangle/J_1 \right)^{d,r-1}$ is given, then one can rewrite $F$ as $\sum_{i=0}^{d}\sum_{j=0}^{r-1}\lambda_{ij}y^{i}z^{j}$ by $\widetilde{O}(rd)$ arithmetic operations as well. 
 \end{lemma}
 \begin{proof}
By symmetry, it is sufficient to prove the first part. We observe that $F =\sum_{i=0}^{d}\sum_{j=0}^{r-1}\lambda_{ij} X^{i} A^{j}=\sum_{i=0}^{d} X^{i}(\sum_{j=0}^{r-1}\lambda_{ij}A^{j})$. Thus, nonzero elements in $M = \varphi(\pi(_3(E))$ are simply evaluations of polynomials $f_0,\dots, f_{d} \in \mathcal{k}[t]$ at points $0,1\dots, r-1$. Here $f_{i}(t)=\sum_{j=0}^{r-1}\lambda_{ij}t^{j}, 0 \le i \le d$. By \cite[Corollary~3.20]{burgisser2013algebraic}, evaluations of each $f_i$ can be completed by $\widetilde{O}(r)$ operations. Hence the cost of Step~\ref{alg-5:step1} is $\widetilde{O}(dr)$.
%By using \textbf{Fast Polynomial Evaluation} (see \cite{burgisser2013algebraic}), STEP 1 costs $\widetilde{O}(rd)$ arithmetic operations. 

By Lemma~\ref{lem26}, $\varphi$ is an isomorphism, thus $\mu_{ij}$'s can be determined by solving $M = \sum_{i=0}^d \sum_{j=0}^{r - 1} \mu_{ij} \alpha^j \beta^i$, where $\alpha,\beta$ are matrices defined in Lemma~\ref{lem26}. Therefore, $\mu_{ij}$'s can be obtained by interpolating $d+1$ polynomials of degree at most $r-1$ at points $0,\dots, r-1$. According to \cite[Corollary~3.22]{burgisser2013algebraic}, each polynomial interpolation can be done by $\widetilde{O}(dr)$ operations. The cost of Step~\ref{alg-5:step2} is $\widetilde{O}(dr)$ and this completes the proof.
%     \par Rewrite $F =\sum_{i=0}^{d}\sum_{j=0}^{r-1}\mu_{ij} A^{j} X^{i}=\sum_{i=0}^{d}(\sum_{j=0}^{r-1}\mu_{ij}A^{j})X^{i}$, and we can obtain the exact value of $\mu_{ij}$ via $M$ and computing $\mu_{ij}$, $j=0,2,\cdots,r-1$ for any given $i$ equals to a polynomial interpolation at $0,1,\cdots,r-1$ with value.
%     By using \textbf{Fast Polynomial Interpolation} (see \cite{burgisser2013algebraic}), STEP 2 costs $\widetilde{O}(rd)$ arithmetic operations. Together, the lemma is proven.
 \end{proof}

