\subsection{Tower of Galois algebras}
This subsection is devoted to generalize Propositions~\ref{prop16}, \ref{thm-22} and \ref{thm-23}. Namely, we prove that the lower bound established in Section~\ref{sec:lower bound} is quasi-optimal for a $\langle \sigma \rangle$-Galois algebra $\mathcal{A}_2$ over $\mathcal{k}$, if there exists a tower $\mathcal{k} \subseteq \mathcal{A}_1 \subseteq \mathcal{A}_2$ such that either $\mathcal{A}_1/\mathcal{k} $ or $\mathcal{A}_2/\mathcal{A}_1$ is one the three types discussed in Subsections~\ref{subsec:totally split algebra}--\ref{subsec:artin extension}.
%Corollaries~\ref{coro31} and \ref{coro33} shows that the quasi-optimal upper bound can also be achieved if $L/K$ can be factored as $L/L'/K$ where one of extension $L/L'$ or $L'/K$ is Kummer or Artin extension and the degree of the other extension is small.

Let $\mathcal{k} \subseteq \mathcal{A}_1 \subseteq \mathcal{A}_2$ be a tower of finite dimensional \'{e}tale $\mathcal{k}$-algebras. We denote $r_1 \coloneqq \dim_{\mathcal{k}}\mathcal{A}_1$ and $r_2 \coloneqq \dim_{\mathcal{k}}\mathcal{A}_2$. Assume further that $\sigma$ is an automorphism of $\mathcal{A}_2$ such that $\sigma|_{\mathcal{A}_1}$ is also an automorphism of $\mathcal{A}_1$ and that both $\mathcal{A}_1$ and $\mathcal{A}_2$ are $\langle \sigma \rangle$-Galois algebra. 
%Let $\sigma$ be the element generating both $Gal(L_{2}/K)$. Since $Gal(L_{1}/K)=Gal(L_{2}/K)/(\sigma^{r_{2}/r_{1}}-1)$, and the quotient map is the restriction map, we write $\sigma$ to denotes $\sigma_{L_{1}}$.

For $i=1,2$, we denote by $\mu^{(i)}_d$ the $\mathcal{k}$-bilinear map of multiplying two elements in $\mathcal{A}_i[x,\sigma]^{d}$. Moreover, we notice that $\sigma^{r_1}$ is an automorphism of $\mathcal{A}_2$ and $\sigma^{r_1}|_{\mathcal{A}_1} = \id_{\mathcal{A}_1}$. Thus $\mathcal{A}_2[x,\sigma^{r_1}]^d$ is an algebra over $\mathcal{A}_1$. We denote the $\mathcal{A}_1$-bilinear map of multiplying two elements in $\mathcal{A}_2[x,\sigma^{r_1}]^d$ by $\mu_d^{(1,2)}$.

Moreover, we assume that each automorphism of $\mathcal{A}$ can be computed by $\widetilde{O}(r)$ arithmetic operations in $\mathcal{k}$. This is a direct consequence of the availability assumption for representational data in \cite[Assumption H]{GHS20}.
\begin{lemma}\label{lem30} 
Let $\mathcal{k},\mathcal{A}_1,\mathcal{A}_2, \sigma,\mu^{(1)}_d,\mu^{(2)}_d$ and $\mu^{(1,2)}_d$ be as above. Then we have $C_{\mathcal{k}}(\mu_d^{(2)})=\widetilde{O}\left(r_1^3 C_{\mathcal{A}_1}\left(\mu_{\lceil d/r_1\rceil}^{(1,2)}\right)\right)$. If moreover $\mathcal{A}_2 = \mathcal{A}_1[a]$ for some $a\in \mathcal{A}_1$, then $C_{\mathcal{k}}(\mu_d^{(2)}) = O\left( \left(\frac{r_2}{r_1} \right)^2 C_{\mathcal{k}} (\mu_d^{(1)}) \right)$.
\end{lemma}
\begin{proof}
Given $f_1,f_2\in \mathcal{A}_2[x,\sigma]^d$, we re-write \[
f_1=\sum_{k=0}^{r_{1}-1}x^{k} g_{k}(x^{r_{1}}),\quad f_2 =\sum_{l=0}^{r_{1}-1}h_{l}(x^{r_{1}})x^{l}
\]
