\subsection{Data Format} \label{ap:dataset}

\noindent \textbf{Image Type:} diagram, line plot, algorithm, and picture. \\
\noindent \textbf{Image Purpose:} supplemental, when the image is non-essential and all information about the problem is stated in the problem text or crucial, when the image is required to solve the problem. One can determine that the question in Figure \ref{ap:fig:example_complex_supplemental} has a supplemental image since it could be inferred from the text. \\


\begin{figure}[t]
  \includegraphics[width=\columnwidth]{figures/supplemental_complex_question.PNG}
  \caption{Example of a complex question with supplemental image.}
  \label{ap:fig:example_complex_supplemental}
\end{figure}



\noindent \textbf{Question Type:} multiple choice questions (MCQ), multiple choice questions multiple answers (MCQ-MA), and compound questions containing multiple sub-MCQ questions connected by the same question topic and having some related information in each other.\\
\noindent \textbf{Complexity of Problem Conditions:} ``Complex'' means that the question involves multiple concepts of the subject, while ``Simple'' would require only one or two closely related concepts to solve the problem. This condition does not directly reflect problem difficulty; a question may involve a single difficult concept or multiple simple ones. Distinguishing between simple and complex questions allowed us to evaluate whether models struggled with interdependent conditions. Simple questions involve fewer variables, while complex ones require integrating multiple pieces of information. 

One can determine that the question in Figure \ref{ap:fig:example_complex_supplemental} is ``Complex'' and the image is ``Supplemental''. The question is complex because it involves the Hodgkin-Huxley model, differential equations governing potassium channel dynamics, and voltage-dependent parameters, requiring knowledge of electrophysiology and mathematical modeling. The image is supplemental because it provides graphical representations of \( n_{\infty}(u) \) and \( \tau_n(u) \), but all necessary equations and definitions are clearly described in the text, making the image helpful but not essential.

\subsubsection{Description of Labels}
\label{sec:label_description}
\begin{enumerate}
    \item \textbf{Course\_name}:
    \begin{itemize}
        \item \textit{Description}: The name or identifier of the course associated with the question.
        \item \textit{Example}: \texttt{"Calculus I"}, \texttt{"Physics 101"}
    \end{itemize}

    \item \textbf{Exercise\_name}:
    \begin{itemize}
        \item \textit{Description}: The unique exercise id.
    \end{itemize}

    \item \textbf{Question}:
    \begin{itemize}
        \item \textit{Description}: The text of the question, may include LaTeX formatting and placeholders for images.
    \end{itemize}

    \item \textbf{Gold\_answer}:
    \begin{itemize}
        \item \textit{Description}: The correct answer to the question. 
    \end{itemize}

    \item \textbf{Question\_type}:
    \begin{itemize}
        \item \textit{Description}: The format or type of the question.
        \item \textit{Possible Labels}:
        \begin{itemize}
            \item \texttt{"MCQ"} (Multiple Choice Question)
          %  \item \texttt{"Open-ended"}
            \item \texttt{"MCQMA"} (MCQ Multiple Answers)
            \item \texttt{"Compound"} (a non-open-ended question with multiple objectives)
        \end{itemize}
    \end{itemize}

    \item \textbf{Image\_type}:
    \begin{itemize}
        \item \textit{Description}: The type of images included in the question.
        \item \textit{Possible Labels (Others may be added as we manually label)}:
        \begin{itemize}
            \item \texttt{"line plot"}
            \item \texttt{"bar plot"}
            \item \texttt{"scatter plot"}
            \item \texttt{"histogram"}
            \item \texttt{"pie chart"}
            \item \texttt{"table"}
            \item \texttt{"image"}
            \item \texttt{"diagram"}
        \end{itemize}
    \end{itemize}

    \item \textbf{Image\_purpose}:
    \begin{itemize}
        \item \textit{Description}: The role of the image in the context of the question.
        \item \textit{Possible Labels}:
        \begin{itemize}
            \item \texttt{"Crucial"} (Essential for solving the question)
            \item \texttt{"Supplemental"} (Doesn’t provide additional context)
        \end{itemize}
    \end{itemize}

    \item \textbf{Problem\_conditions}:
    \begin{itemize}
        \item \textit{Description}: The complexity of the conditions within the problem.
        \item \texttt{"Complex"} doesn’t necessarily mean that the problem is difficult. It simply means that many conditions are in play.
        \item \textit{Possible Labels}:
        \begin{itemize}
            \item \texttt{"Simple"} (Conditions are straightforward and not interacting)
            \item \texttt{"Complex"} (Multiple conditions interact to find the answer)
        \end{itemize}
    \end{itemize}

    \item \textbf{Question\_images}:
    \begin{itemize}
        \item \textit{Description}: A list of filenames or identifiers for images included in the question.
    \end{itemize}

    \item \textbf{Question\_length\_characters}:
    \begin{itemize}
        \item \textit{Description}: The length of the question text is measured in characters.
    \end{itemize}


    \item \textbf{Num\_objectives}:
    \begin{itemize}
        \item \textit{Description}: The number of sub-questions within the question.
        \item \textit{Example}: \texttt{1}, \texttt{2}
    \end{itemize}

    \item \textbf{Language}:
    \begin{itemize}
        \item \textit{Description}: The language in which the question is written.
        \item Always in \texttt{"English"} because we translated the French ones.
    \end{itemize}

    \item \textbf{Original\_language}:
    \begin{itemize}
        \item \textit{Description}: The original language of the question before translation.
        \item \textit{Example}: \texttt{"French"}
    \end{itemize}

    \item \textbf{Was\_translated}:
    \begin{itemize}
        \item \textit{Description}: Indicates whether the question was translated from another language.
        \item \textit{Possible Values}: \texttt{true} or \texttt{false}
    \end{itemize}

    \item \textbf{Image\_file\_type}:
    \begin{itemize}
        \item \textit{Description}: The file format of the images used.
        \item \textit{Example}: \texttt{"PNG"}, \texttt{"JPEG"}
    \end{itemize}

    \item \textbf{Answer\_format}:
    \begin{itemize}
        \item \textit{Description}: The expected format of the answer.
        \item \textit{Possible Labels}:
        \begin{itemize}
            \item \texttt{"Only MCQ Letter"} (previously called MCQ)
            \item \texttt{"Only Numeric Answer"}
            \item \texttt{"Derivation"}
            \item \texttt{"Text"}
            \item \texttt{"Code"}
            \item \texttt{"Calculation"}
        \end{itemize}
    \end{itemize}

    \item \textbf{Solution\_type}:
    \begin{itemize}
        \item \textit{Description}: Indicates whether the question has a unique correct answer or multiple correct answers.
        \item \textit{Possible Labels}:
        \begin{itemize}
            \item \texttt{"Unique answer"}
            \item \texttt{"Multiple answers"}
        \end{itemize}
    \end{itemize}

    \item \textbf{Type\_of\_text}:
    \begin{itemize}
        \item \textit{Description}: The formatting or typesetting used in the question text.
        \item \textit{Example}: \texttt{"LaTeX"}, \texttt{"Plain text"}, \texttt{"XML"}
    \end{itemize}

    \item \textbf{Objective\_dependency}:
    \begin{itemize}
        \item \textit{Description}: Indicates whether the objectives in the question are independent or dependent on previous ones.
        \item \textit{Possible Labels}:
        \begin{itemize}
            \item \texttt{"All Independent"} (Objectives can be solved separately)
            \item \texttt{"Dependent"} (Some objectives rely on answers from previous parts)
        \end{itemize}
    \end{itemize}

\end{enumerate}



