\begin{algorithm}
\caption{Training process}\label{alg:cap}
\begin{algorithmic}
\Require Dynamic graphs $G =\{\G_1,\dots,\G_T\}$ 
% \Ensure $y = x^n$
% \State $y \gets 1$
% \State $X \gets x$
% \State $N \gets n$
\State $\Theta_{t - 1} \leftarrow GCN^{(parameters)}$
\While{$MRR_{\Delta t}$ is increasing} % \Comment{$w$ is the window size}
\State {Generate overlapped windows $\Delta t$ on $G$}
\For{t $\in \{1,\dots,{\Delta t}\}$}
    \State $X_t^{global} \leftarrow GRU(X_t^{random \ wallk})$

    % \State {$\mathcal{L}_{GRU_t}  \leftarrow$ Calculate prediction loss of GRU}
    \State $X_t^{local}  \leftarrow GCN(\G_t, X_t, \Theta_{t - 1})$
    \State $X_t^{fused} \leftarrow CA(\mathcal{Q}_t^{local}, \mathcal{K}_t^{global}, \mathcal{V}_t^{global})$ 
    \State {$\mathcal{L}_{t}^{fused} \leftarrow$ Calculate prediction loss of $X_t^{fused}$}
    \State {$grad_t \leftarrow$ autograd($\Theta_t$, $\mathcal{L}_{t}^{fused}$)}
    \State {$weight_t \leftarrow$ $\frac{1}{\mathcal{L}_{t}^{fused}+ \epsilon}$}
    \State {$ssm\_state_t \leftarrow$ SSM($grad_t$, $weight_t$)}
    \State {$\Theta_t \leftarrow$ param\_update($grad_t$, $\Theta_{t - 1}$, $SSM\_state_t$)}
    \State $X_{t + 1}^{global} \leftarrow GRU(X_{t + 1}^{random \ wallk})$
    \State {$\hat{\mathcal{L}}_{t + 1}^{global} \leftarrow$ Calculate prediction loss of GRU}
    \State $X_{t + 1}^{local} \leftarrow GCN(\G_{t + 1}, X_{t + 1}, \Theta_t)$
    \State $X_{t + 1}^{fused} \leftarrow CA(\mathcal{Q}_{t + 1}^{local}, \mathcal{K}_{t + 1}^{global}, \mathcal{V}_{t + 1}^{global})$ 
    \State $\hat{\mathcal{L}}_{t + 1}^{fused} \leftarrow$ Calculate prediction loss of $X_{t + 1}^{fused}$
    \State $\hat{\mathcal{L}}_{t+i:\Delta t}^{fused}\leftarrow  \hat{\mathcal{L}}_{t + 1}^{fused}$
      \EndFor
\EndWhile

\noindent{\Return $\Theta$}
\end{algorithmic}
\end{algorithm}


