% \emph{\textbf{Supplementary}}.
% appendix (section ~\ref{appendix:dpo-algo}).

% \subsection{Hin-DPO Training Algorithm}\label{appendix:dpo-algo}

\begin{algorithm}[H]
\caption{Our Hin-DPO Training Algorithm}
\begin{algorithmic}[1]
\REQUIRE Training dataset ad Dataloader \( D \) with win and lose samples (paired or unpaired), initial model parameters \( \theta_0 \), reference model \( \pi_{\text{ref}} \), number of iterations \( T \), scaling factor \( \beta \), temperature parameter \( \tau \)
\STATE Initialize model \( \pi_{\theta} \) with parameters \( \theta_0 \)
\STATE Set \( \pi_{\theta} \) to training mode and \( \pi_{\text{ref}} \) to evaluation mode
\FOR{iteration = 1 to \( T \)}
    \FOR{each batch in \( D \)}
        \STATE Initialize running mean \( \mu \gets 0 \) and running variance \( \sigma^2 \gets 0 \) \COMMENT{Running statistics for probability distribution}
        \STATE Set \( \text{num\_iter} = 5 \) \COMMENT{Number of iterations for variance computation}
        \FOR{iter = 1 to \( \text{num\_iter} \)}
            \STATE Compute logits for the preferred response:
            \STATE \( \text{logits} \gets \pi_{\theta}(\text{pref\_ids}, \text{pref\_mask}).\text{logits} \)
            \STATE Compute probabilities:
            \STATE \( \text{probs} \gets \exp(\text{log\_probs(logits, pref\_ids)}) \)
            \STATE Update Mean and Variance:
            \STATE \( \mu \gets \mu + \frac{\text{probs} - \mu}{\text{iter}} \)
            \STATE \( \sigma^2 \gets \sigma^2 + (\text{probs} - \mu) \times (\text{probs} - \mu) \)
        \ENDFOR
        \STATE Compute final variance:
        \STATE \( \sigma^2 \gets \frac{\sigma^2}{\text{num\_iter} - 1} \)
        \STATE Get log probabilities for preferred and dispreferred responses using \( \pi_{\theta} \):
        \STATE \( \text{model\_pref\_log} \gets \text{log\_prob}(\pi_{\theta}(\text{pref\_ids}, \text{pref\_mask}), \text{pref\_ids}) \)
        \STATE \( \text{model\_dispref\_log} \gets \text{log\_prob}(\pi_{\theta}(\text{dispref\_ids}, \text{dispref\_mask}), \text{dispref\_ids}) \)
        \STATE Get log probabilities for preferred and dispreferred responses using reference model \( \pi_{\text{ref}} \):
        \STATE \( \text{ref\_pref\_log} \gets \text{log\_prob}(\pi_{\text{ref}}(\text{pref\_ids}, \text{pref\_mask}), \text{pref\_ids}) \)
        \STATE \( \text{ref\_dispref\_log} \gets \text{log\_prob}(\pi_{\text{ref}}(\text{dispref\_ids}, \text{dispref\_mask}), \text{dispref\_ids}) \)
        \STATE Compute Hin-DPO loss:
        \STATE \( \text{loss} \gets \text{Hin-DPO\_loss}(\text{model\_pref\_log}, \text{model\_dispref\_log}, \text{ref\_pref\_log}, \text{ref\_dispref\_log}, \sigma^2, \beta) \)
        \STATE Backpropagate loss:
        \STATE \( \text{loss.backward()} \)
        \STATE Update model parameters:
        \STATE \( \theta \gets \text{optimizer.step()} \)
    \ENDFOR
\ENDFOR
\end{algorithmic}
\end{algorithm}



\noindent
In Equation~\ref{eq:dpo_loss_1} \& \ref{eq:dpo_loss_2}, $L_{\text{Hin-DPO}}$ represents the modified Direct Preference Optimization (DPO) loss function. The terms $\pi_\theta(y \mid x)$ and $\pi_{\text{ref}}(y \mid x)$ denote the probabilities assigned by the learned policy and the reference policy, respectively, for a response $y$ given input $x$. The dataset sample $(x, y_w, y_l) \sim D$ consists of an input $x$, a preferred response $y_w$, and a rejected response $y_l$. The \textit{Actuality} scores $s_w$ and $s_l$ quantify the factual accuracy of the preferred and rejected responses, respectively, ensuring factually grounded optimization. The hyperparameter $\beta$ controls the preference weighting, while $v$ represents the \textit{Finesse} score, capturing prediction variance to regulate uncertainty. A small positive term $\epsilon$ is added to prevent division by zero, and $\sigma(\cdot)$ denotes the sigmoid function for smooth preference modelling. The gradient analysis of \textit{Hin-DPO} is presented in Section~\ref{grad-analysis} of the appendix.


\textbf{Preserving Core DPO Training Process:}  
Despite the inclusion of these additional parameters, the core preference-based alignment in DPO remains intact. The \textit{Actuality} and \textit{Finesse} scores act as dynamic weighting mechanisms, adjusting rewards to improve factual consistency while mitigating uncertainty.

\textbf{Utilization of \textit{Actuality}:}  
We leverage \textit{Actuality} scores to modulate the weighting of preferred and rejected responses. Specifically, $(1 + s_w)$ amplifies the log probability of the preferred response, ensuring that factually accurate explanations are prioritized. Conversely, $\max(0.01, s_l)$ is applied to the rejected response, penalizing factually weak explanations without over-penalization.

\textbf{Impact of \textit{Finesse}:}  
The \textit{Finesse} score, computed via variance in predictions across different temperature settings, regulates the scaling factor in DPO loss. Low variance (indicating stable predictions) amplifies the reward, while high variance (close to 1) retains standard DPO behaviour. A small learnable parameter $\epsilon$ prevents instability.
