\caption{HR Table Information Extraction and Query Processing}
\label{alg:hr_inference}
\SetKwProg{Offline}{Offline Preprocessing}{:}{end}
\SetKwProg{Online}{Online Inference}{:}{end}

\Offline{}{
    Initialize Claude V3 Haiku model\;
    Initialize AmazonQ for RAG\;
    \ForAll{document \$d\$ in corpus}{
        tables = TableDetectionModule(\$d\$)\;
        \tcp{CV-based table embed in image detection method from document}
        \ForAll{table \$t\$ in tables}{
            prompt = GenerateHRSpecificPrompt(\$t\$)\;
            \tcp{Contextual prompting for Talent Domain, LLM=Claudev3 Haiku}
            structured\_text = LLM(prompt)\;
            \tcp{Extract semantic structure}
            knowledge\_base += IndexForRetrieval(structured\_text)\;
            \tcp{Build vector index}
        }
    }
}
\Online{Query \$Q\$}{
    relevant\_context = AmazonQ.Retrieve(\$Q\$, knowledge\_base)\;
    \tcp{Vector similarity search}
    combined\_context = query\_context + relevant\_context\;
    \tcp{LLM for retrieval and answer generation: Claude v3 Haiku}
    response = LLM(\$Q\$, combined\_context)\;
    \tcp{Context-aware response from table embed in images}
    \Return response\;
}
\end{algorithm}

