def multi_modality_enhancement_prompt(image):
    prompt = f"""###Instruction: Act as an intelligent 
    document processing agent specialized in 
    talent management documentation. Your task is to:
    1. Parse the hierarchical table embedded in image
    2. Convert each table cell into contextually meaningful 
       text while preserving:
       - Row-column relationships and Numerical precision
       - Contextual dependencies
    3. Generate complete, well-formed sentences that capture:
       - Cell value and its position context
       - Related header information
       - Any conditional relationships
    For the given HR document image {image}, maintain data 
    fidelity while ensuring the output is optimized 
    for downstream RAG chat applications to support user's
    question-anwering in real-time.
    ###Response: """
    return prompt
