\newcommand{\four}[4]{%
  % #1 = Strongly Disagree (Percent)
  % #2 = Disagree (Percent)
  % #3 = Agree (Percent)
  % #4 = Strongly Agree (Percent)
  \begin{tikzpicture}[baseline]
    \pgfmathsetmacro{\barwidth}{3.5} % Adjust width
    \pgfmathsetmacro{\widthSD}{#1*\barwidth/100}
    \pgfmathsetmacro{\widthD}{#2*\barwidth/100}
    \pgfmathsetmacro{\widthA}{#3*\barwidth/100}
    \pgfmathsetmacro{\widthSA}{#4*\barwidth/100}

    % Bar segments with custom colors (yellow to red)
    \fill[softyellow] (0,0) rectangle (\widthSD,0.5); % Strongly Disagree
    \fill[softorange] (\widthSD,0) rectangle (\widthSD+\widthD,0.5); % Disagree
    \fill[softred] (\widthSD+\widthD,0) rectangle (\widthSD+\widthD+\widthA,0.5); % Agree
    \fill[darkred] (\widthSD+\widthD+\widthA,0) rectangle (\widthSD+\widthD+\widthA+\widthSA,0.5); % Strongly Agree

    \draw[black] (0,0) rectangle (\barwidth,0.5);

    % Optional: show labels only if percentage is large enough
    \pgfmathparse{#1} \ifdim\pgfmathresult pt > 15pt
      \node[font=\scriptsize] at (\widthSD/2, 0.25) {#1\%};
    \fi
    \pgfmathparse{#2} \ifdim\pgfmathresult pt > 15pt
      \node[font=\scriptsize] at (\widthSD+\widthD/2, 0.25) {#2\%};
    \fi
    \pgfmathparse{#3} \ifdim\pgfmathresult pt > 15pt
      \node[font=\scriptsize] at (\widthSD+\widthD+\widthA/2, 0.25) {#3\%};
    \fi
    \pgfmathparse{#4} \ifdim\pgfmathresult pt > 15pt
      \node[font=\scriptsize, text=white] at (\widthSD+\widthD+\widthA+\widthSA/2, 0.25) {#4\%};
    \fi
  \end{tikzpicture}%
}


