\title{On Jailbreaking Quantized Language Models Through Fault Injection Attacks}

\author{Noureldin Zahran$^\dagger$, Ahmad Tahmasivand$^\ddagger$, Ihsen Alouani$^\S$, Khaled Khasawneh$^\ddagger$ and Mohammed E. Fouda$^\dagger$\\
