    \centering
    \includegraphics[width=\linewidth]{Figures/Figure2.pdf}
    \caption{(a) The peg-in-hole problem is considered as inserting a peg into its matching hole on a planar board (a randomly generated peg is adopted as the example). (b) An overview of the task formulation is presented, including the geometry representation of the peg, the hole, and the overall task environment.}
    \label{fig:task}
\vspace{-0.5cm}
\end{figure}

\subsection{Preliminaries}

\subsubsection{Geometry of the Peg and Hole}\label{geo_pah} The 3-dimensional (3-D) geometry of the hole is described in the \textit{hole reference frame} $\{H\}$, as an intrusion of a 2-D polygonal base defined by an ordered sequence of vertices $\mathcal{V}_h=(v^0_h, v^1_h, ..., v^n_h), v_h\in\mathbb{R}^3, z_{v_h}=0$ on the $XY$-plane of  $\{H\}$. $S(\mathcal{V}_h)=\cup_{i=0}^n \{v_h^i \}\subset \mathbb{R}^3$ is the corresponding unordered set of the $\mathcal{V}_h$. The intrusion is along the negative direction of the $Z$-axis of $\{H\}$. $\mathcal{V}_h$ defines a planar region $\mathcal{A}_h\subset\mathbb{R}^3$ on the $XY$-plane of $\{H\}$ as:
\begin{equation}
\label{area_def}
    \mathcal{A}_h = \{ (x, y, z)\in \mathbb{R}^3  \mid f_{\mathcal{A}_h}(x,y)\leq0 \land z=0\}
\end{equation}
where $f_{\mathcal{A}_h}(x, y)$ is an implicit distance function to describe the boundary of $\mathcal{A}_h$ as $f_{\mathcal{A}_h}(x, y)=0$ and its interior area as $f_{\mathcal{A}_h}(x, y)<0$, exterior area as $f_{\mathcal{A}_h}(x, y)>0$.

The 3-D geometry of the peg is described in the \textit{peg reference frame} $\{E\}$, as an extrusion of a 2-D polygon base  $\mathcal{V}_e=(v^0_e, v^1_e, ..., v^n_e), v_e\in\mathbb{R}^3, z_{v_e}=0$ on the $XY$-plane of  $\{E\}$. Its corresponding unordered set is denoted as $S(\mathcal{V}_e)=\cup_{i=0}^n \{v_e^i \}\subset \mathbb{R}^3$.The extrusion is along the positive direction of $Z$-axis of $\{E\}$, and $\mathcal{V}_e$ is considered approximated equal to $\mathcal{V}_h$ but defined in different frames. 

\subsubsection{Task Environment}
We specify the \textit{Cartesian world frame} $\{O \}$ attached to the task board, as its $XY$-plane is aligned with the board surface and its orthogonal $Z$-axis points outward the task board. The pose of the hole in the world frame is denoted as $T_{\{OH\}}\in \text{SE(3)}$. We describe the task environment using a occupancy function $\Gamma: \mathbb{R}^3\mapsto [-1, 0, 1]$, which is defined as follows:
\small
\begin{equation}
\label{task_env}
\Gamma(x, y, z) = \left\{
             \begin{array}{lr}
             -1,&  z<0 \land f_{T_{\{OH\}}\mathcal{A}_{h}}(x, y) >0 \\
            1, &  z>0  \lor (z\leq0 \land  f_{T_{\{OH\}}\mathcal{A}_{h}}(x, y) < 0) \\
            0, & \text{Otherwise} \\
\end{array}
\right.
\end{equation}
\normalsize

in which $-1$ denotes occupied by the task board, $0$ denotes on the surface of the task board, and $1$ denotes the free space. An initial area of interest $\mathcal{A}_\text{board}\subset\mathbb{R}^3$ is specified on the $XY$-plane of $\{O\}$ that guarantees $T_{\{OH\}}\mathcal{A}_h\subset \mathcal{A}_\text{board}$. 

 \subsubsection{Compliant Interactions for the Peg}
As the peg is in a prism-shaped geometry as defined in Sec.~\ref{geo_pah}, we use the densely sampled points $\mathcal{P}_e=\{p_e^i\in \mathbb{R}^3\}_{i=1}^M$ on the edges of the peg for collision checking (considered continuous along the lateral and base edges), in which $p_e=(x,y,z)$ is in the Cartesian coordinates of $\{E\}$. The sampled points are assumed to be rigidly attached to each other, as the entire point set undergoes the same rigid body transformation (rotation and translation). The pose of frame $\{E\}$  with reference to frame $\{O\}$ at time $t$ is represented as $\mathbf{x}_{t}=[\mathbf{p}; \mathbf{r}]\in\mathbb{R}^6$, in which $\mathbf{p}\in \mathbb{R}^3$ is the position vector and $\mathbf{r}\in \mathbb{R}^3$ is the orientation represented with Euler angle. The target peg-in-hole state is denoted as $\mathbf{x}^*$. The corresponding transformation matrix of $\mathbf{x}_{t}$ is denoted as $T_{\{OE\},t}\in \text{SE(3)}$. An overview of the task environment with the manipulated peg is illustrated in Fig.~\ref{fig:task}-(b).

To enable safe contact between the peg and its task environment, we formulate the impedance control based on the desired state $\mathbf{x}^{\text{d}}_t\in\mathbb{R}^6$ at time $t$. A wrench $\mathbf{F}\in \mathbb{R}^6$ (consisting of 3-D force and torque) is applied to the peg by a Cartesian impedance controller as formulated:
\begin{equation}
\label{impedance}
    \mathbf{F} = \mathbf{K}_d (\mathbf{x}^{\text{d}}_t - \mathbf{x}_{t}) - \mathbf{D}_d \dot{\mathbf{x}}_{t}
\end{equation}
in which $\mathbf{K}_d\in\mathbb{R}^{6\times6}$ is the diagonal stiffness matrix to decouple compliance in each degree of freedom, $\mathbf{D}_d\in \mathbb{R}^{6\times6}$ is the damping matrix for movement stabilizing and $\dot{\mathbf{x}}_{t}\in \mathbb{R}^6$ is the velocity of $\{E\}$ with reference to $\{O\}$ at time $t$. 


An interaction command $\mathbf{c}_t =(\mathbf{x}_{t}, \mathbf{x}_{t}^{\text{d}})$ at time $t$ is defined by its starting state $\mathbf{x}_{t}$ (considered steady as $\dot{\mathbf{x}}_{t}=0$) and a desired state $\mathbf{x}_{t}^{\text{d}}$. A compliant interaction $\mathbf{x}_{t+1}=\Pi(\mathbf{x}_{t}, \mathbf{x}_{t}^\text{d})$ between the peg and its task environment is an unknown but observable process $\Pi: \mathbb{R}^6\times\mathbb{R}^6\mapsto\mathbb{R}^6$ from the starting state $\mathbf{x}_{t}$ to the next steady state $\mathbf{x}_{t+1}$, under the drive of $\mathbf{x}_{t}^\text{d}$ and the environmental constraints in the frame of $\{O\}$. Except for the virtually defined desired state $\mathbf{x}_{t}^\text{d}$, any physical existing state $\mathbf{x}_{t+1}$ during this process is constrained by its task environment as follows:
\begin{equation}
\label{non-penetration}
    \forall p_o \in T_{\{OE\},t+1}\mathcal{P}_e, \Gamma(x_{p_o},y_{p_o},z_{p_o} )\neq-1
\end{equation}
We do not explicitly predict or trace the trajectory of the peg during this process but only observe its steady state at $\mathbf{x}_{t}$ and $\mathbf{x}_{t+1}$. 
At the steady state $\mathbf{x}_{t+1}$, any external contact wrench $\mathbf{F}_\text{ext}\in \mathbb{R}^6$ in frame $\{O\}$ is balanced by the pose deviation as:
\begin{equation}
\label{ext_force}
    \mathbf{F}_\text{ext} = \mathbf{K}_d (\mathbf{x}^{\text{d}}_t - \mathbf{x}_{t+1})
\end{equation}
while the velocity $\dot{\mathbf{x}}_{t+1}=0$ of the peg remains zero.

We use the intersection point set $\mathcal{P}_{o, \text{footprint},t}\subset \mathbb{R}^3$ between the peg's edges and the $XY$-plane of $\{O \}$ at the steady pose $\mathbf{x}_{t}$ to describe the outcome of each interaction as:
\begin{equation}
   \mathcal{P}_{o, \text{footprint}} = \{ p_o \in T_{\{OE\},t}\mathcal{P}_e\mid \forall p_o=(x,y,z) , z=0 \}
\end{equation}
$\mathcal{P}_{o, \text{footprint}}$ reflects the spatial relation between the peg and the task board.



\subsection{Problem Statement}
% \textcolor{red}{start from here}
\label{pb_state}
We formulate the peg-in-hole assembly task as a progressive uncertainty elimination process in the state space of perception and execution.
We aim to plan interactions $\mathbf{c}_{t}=(\mathbf{x}_{t}, \mathbf{x}_{t}^{\text{d}})$ between the peg and its task environment to 1) iteratively reduce the uncertainty of the perception result of the target hole and 2) finish the peg insertion under execution and perception uncertainty. An overview of the peg-in-hole assembly process is outlined in Alg.~\ref{alg:two_stage}.

\textbf{Perception State Space:} We use $\widetilde{T}_{\{OH\}}$ to denote the estimated state of the ground truth $T_{\{OH\}}$. The estimation result at time $t$ is represented with a probabilistic density function $P_t(\widetilde{T}_{\{OH\}})$ bounded by a proposal region $\mathcal{X}_t\subset \text{SE(3)}$, which is defined as follows:
\begin{equation}
\label{prob_vf}
P_t(\widetilde{T}_{\{OH\}}) = \left\{
             \begin{array}{lr}
             \frac{1}{|\mathcal{X}_t|}, & \widetilde{T}_{\{OH\}} \in \mathcal{X}_t \\
            0, & \widetilde{T}_{\{OH\}} \notin \mathcal{X}_t
\end{array}
\right.
\end{equation}
where $|\mathcal{X}_t|$ denotes the volume of region $\mathcal{X}_t$. 

We aim to form a recursive sequence of proposal regions based on the outcomes $\mathcal{P}_{o, \text{footprint},t}$ of each interaction $\mathbf{c}_t$:
\begin{equation}
\label{virtual_funnel}
\mathcal{X}_0 \supseteq \mathcal{X}_1 \supseteq \mathcal{X}_2 \supseteq \dots \supseteq \mathcal{X}_{T1} 
\end{equation}
As $\mathcal{X}_{t}$ shrinks over steps, the expected spread of $\widetilde{T}_{\{OH\}}$ decreases and the uncertainty range of the perceived hole's state is reduced.


\textbf{Execution Task Space:} Let $\Delta \mathbf{x}\in\mathbb{R}$ be the deviation between the steady state $\mathbf{x}_{t}$ and the peg-in-hole state $\mathbf{x}^*$. Based on the estimated state distribution of $P_{T1}(\widetilde{T}_{OH})$, we aim to shrink $\Delta \mathbf{x}$ at each step of interaction $\mathbf{c}_t$ to progressively reach the peg-in-hole configuration as follows:
\small
\begin{equation}
\label{physical_f}
    \Delta \mathbf{x}_{0}  > \Delta \mathbf{x}_{1} > \Delta \mathbf{x}_{2} > \dots > \Delta \mathbf{x}_{T2}
\end{equation}
\normalsize
We consider a successful peg-in-hole assembly when $\Delta \mathbf{x}$ reaches zero.



\begin{algorithm}
\caption{Peg-in-Hole Assembly}
\renewcommand{\algorithmicrequire}{\textbf{Input:}}
\renewcommand{\algorithmicensure}{\textbf{Output:}}
\begin{algorithmic}[1]
\label{alg:two_stage}
\REQUIRE base polygon $\mathcal{V}_{h}$, initial area of interest $\mathcal{A}_\text{board}$, peg geometry as $\mathcal{P}_e$, world frame $\{O\}$
\STATE $t\gets 0$ \COMMENT{Initialize time step for perception}
\STATE $\mathcal{X}_{T1}\gets$ InteractivePerception($\mathcal{V}_{h}, \mathcal{A}_\text{board}, \mathcal{P}_e, \{O\}$) \COMMENT{Alg.~\ref{interactive_p}}
\STATE $t\gets 0$ \COMMENT{Reset time step for execution}

\STATE $\mathbf{x}_{t} \gets$ CornerAlignment($\mathcal{X}_{T1}$) \COMMENT{Alg.~\ref{alg:alignment}}
\WHILE{not reach $\mathbf{x}^*$}   
\STATE $\mathbf{x}_{t}^{\text{d}} \gets$ InsertionPlanning($\mathbf{x}_{t}$) \COMMENT{Alg.~\ref{alg:insertion}}
\STATE $\mathbf{x}_{t+1}\gets \mathbf{c}_t(\mathbf{x}_t, \mathbf{x}_{t}^{\text{d}})$
\STATE $t\gets t+1$
\ENDWHILE

\end{algorithmic}
\end{algorithm}


\section{Funnel-based Manipulation Planning}
\label{funnel_based_planning}

A manipulation funnel represents a convergence process by iterative contractions from a larger entrance to a smaller exit state space, ensured by task-specific interactions. A general funnel formulation is defined as \textit{Definition}~\ref{funnel_form}.
\begin{definition}
\label{funnel_form}
Let $S$ be a task-relevant space that could represent any system parameters. Given a target state $\mathbf{s}^*$, we aim to find subspaces $S_{\text{in}} \subset S$ so that after applying some state transition functions, denoted as $\Pi: S\rightarrow S$, the resultant output space $S_{\text{out}} \subset S$ is guaranteed to be strictly smaller than the input space: $|S_{\text{in}}|> |S_{\text{out}}|$. If these conditions are satisfied , $\mathbf{s}^*\in S_\text{in}$ and $\mathbf{s}^*\in S_\text{out}$, a tuple $\mathcal{F} = (S_\text{in}, \Pi, S_\text{out})$ is called a manipulation funnel.

\end{definition}

We first define the task-specific interactions based on the task mechanics in Section~\ref{interaction}. Then,  we introduce the formal approach to construct manipulation funnels in perception state space (Section~\ref{sec:vf}) and execution task space (Section~\ref{sec:pf}).


\subsection{Task Mechanics and Interaction Primitives}
\label{interaction}
Funnel-based manipulation planning requires deep exploitation of the intrinsic task mechanics~\cite{mason1985mechanics}. As perception and physical uncertainties are inevitable~\cite{rodriguez2021unstable}, our key insight is forming an aligned \textit{corner} between the inclined peg and the target hole to create contact constraints for undesired motion freedoms and progressively enter the allowed clearance (as illustrated in Fig.~\ref{fig:mechanics}-(a)). A \textit{corner} from the hole is defined by arbitrary vertex $v_h^\text{corner}\in S(\mathcal{V}_h)$ as the local angle $\angle v_h^\text{corner}$ formed by $v_h^\text{corner}$ and its nearby edges from the interior side. In this paper, we use the case of $\angle v_h^\text{corner} < \pi$ for motion funnel construction. However, theoretically, it also applies to the case of $\angle v_h^\text{corner} > \pi$ as long as the local convexity exists. 

