\subsection{Perception Manipulation Funnel}
\label{sec:vf}
The perception manipulation funnel aims to iteratively reduce the proposal region $\mathcal{X}_t$ of the target hole's distribution $P_t(\widetilde{T}_{\{OH\}})$ through observation from each interaction. By strategically placing the supporting vertex $p_v$ of the desired state $\mathbf{x}_t^{\text{d}}$ beneath the $XY$-plane of $\{O\}$, we can intentionally capture the encountered contact constraints reflected on the resulted steady state $\mathbf{x}_{t+1}$. As illustrated in Fig.~\ref{fig:env_id}, after each interaction, the observation $\mathcal{P}_{o, \text{footprint},t}$ can be interpreted as an inequality constraint as defined in \textit{Definition}~\ref{ineq} to limit the distribution of $\widetilde{T}_{\{OH\}}$.

\begin{definition}
\label{ineq}
An inequality constraint on the possible space of $\widetilde{T}_{\{OH\}}$ is defined as $g_t(\widetilde{T}_{\{OH\}}) \geq 0$ based on the observation $\mathcal{P}_{o, \text{footprint},t}$, where $g_t(\widetilde{T}_{\{OH\}})$ is defined as:
\begin{equation}
\begin{aligned}
 \forall p_o\in& \mathcal{P}_{o, \text{footprint},t}, \\
 &g_t(\widetilde{T}_{\{OH\}}) = \left\{
             \begin{array}{lr}
            f_{\widetilde{T}_{\{OH\}}\mathcal{A}_h}(p_o), |\mathcal{P}_{o,\text{footprint},t}|=1& \\
           -\max f_{\widetilde{T}_{\{OH\}}\mathcal{A}_h}(p_o), \text{Otherwise} &
\end{array}
\right.
\end{aligned}
\end{equation}
in which $|\cdot|$ is the cardinality of the set. For a potential hole's state $\widetilde{T}_{\{OH\}}$, any contact point (as $ |\mathcal{P}_{o,\text{footprint},t}|=1$) should be excluded from the hole's area, while any intersection area (as $ |\mathcal{P}_{o,\text{footprint},t}|>1$) should be fully contained by the hole's area.
\end{definition}

The proposal region at $t=0$ is derived from the initial area of interest $\mathcal{A}_{\text{board}}$ as follows:
\begin{equation}
\label{eq:init_x0}
    \mathcal{X}_0 = \{ \widetilde{T}_{\{OH\}}\mid \widetilde{T}_{\{OH\}}\mathcal{A}_h \subset \mathcal{A}_\text{board}   \}
\end{equation}

The proposal region at step \( t \) is defined as:
\begin{equation}
\label{region_t}
\mathcal{X}_t = \{\widetilde{T}_{\{OH\}} \in \mathcal{X}_0\subset SE(3) \mid  g_i(\widetilde{T}_{\{OH\}}) \geq 0, \, i=1, 2,..., t\}    
\end{equation}  
which is updated at step \( t+1\) with the new added constraint $g_{t+1}(\widetilde{T}_{\{OH\}}) \geq 0$ as:
\begin{equation}
\label{eq:region_update}
\mathcal{X}_{t+1} = \mathcal{X}_{t} \cap \{\widetilde{T}_{\{OH\}} \in SE(3) \mid g_{t+1}(\widetilde{T}_{\{OH\}}) \geq 0 \}
\end{equation}

\begin{lemma}
\label{fs_region}
As defined in Eq.~\eqref{eq:region_update}, the volume $|\mathcal{X}_t|$ of the feasible region $\mathcal{X}_t$ is monotonically decreasing ($\mathcal{X}_{t+1}\subseteq \mathcal{X}_{t}$) over nonidentical interactions $\mathbf{c}_t^v$.
\end{lemma}
\begin{proof}
Since $\mathcal{X}_{t+1}$ is the intersection of $\mathcal{X}_{t}$ with another constraint set $g_{t+1}(\widetilde{T}_{\{OH\}})\geq 0$ and $\{g_{t}(\widetilde{T}_{\{OH\}})\geq 0\} \neq \{g_{t+1}(\widetilde{T}_{\{OH\}})\geq 0\}$ under nonidentical interactions,  $|\mathcal{X}_t|$ is decreasing or stays the same when new constraints are added.
\end{proof}
As $\mathcal{X}_t$ shrinks over steps in \textit{Lemma}~\ref{fs_region}, the expected spread of $\widetilde{T}_{\{OH\}}$ decreases, and the allowable state space of the target hole narrows.

\begin{lemma}
\label{vf_approach}
The ground truth state of the hole is always included in the allowable state space as $T_{\{OH\}}\in \mathcal{X}_t$ over interactions $\mathbf{c}_t^v$.
\end{lemma}
\begin{proof}
As $T_{\{OH\}} \in \mathcal{X}_0$ and $T_{\{OH\}}\in \{\widetilde{T}_{\{OH\}}\mid g_t(\widetilde{T}_{\{OH\}})\geq0 \}$, thus proven $T_{\{OH\}} \in \mathcal{X}_t$ as defined in Eq.~\eqref{region_t}.
\end{proof}

Since the proposal region $\mathcal{X}_{t+1}\subseteq \mathcal{X}_{t}$ of the target hole is monotonically shrinking over interactions $\mathbf{c}_t^v$, meanwhile the target state $T_{\{OH\}}$ is guaranteed to be contained by $\mathcal{X}_t$ and $\mathcal{X}_{t+1}$, we introduce the perception manipulation funnel as defined in \textit{Theorem}~\ref{pf_conv}.
\begin{theorem}
\label{pf_conv}
The process of proposal region shrinkage $\mathcal{X}_{t+1}\subseteq \mathcal{X}_{t}$ through compliant interactions $\mathbf{c}_t^v$ is a manipulation funnel in the perception state space.
\end{theorem}
\begin{proof}
As proven in \textit{Lemma}~\ref{fs_region} and~\ref{vf_approach}, the proposal region $\mathcal{X}_t$ is shrinking and approaching $T_{\{OH\}}$ over random interactions $\mathbf{c}_t^v$
, thus proving that the perception manipulation funnel is established based on the general \textit{Definition}~\ref{funnel_form}
\end{proof}

Additionally, a maximum entropy-based method is introduced to improve convergence efficiency. An overview is outlined in Alg.~\ref{interactive_p}. The probability distribution $P_t(\widetilde{T}_{\{OH\}})$ of the target hole's state is defined by Eq.~\ref{prob_vf} and the initial area for exploration $\mathcal{A}_\text{board}$ is divided into grid points $\mathcal{G}=\{\mathbf{g}_i \mid i=1, 2, ..., N\}$ where $\mathbf{g}_i\in \mathbb{R}^3$ on the $XY$-plane of $\{O\}$. During each interaction, number $K$ of potential hole's states is sampled as $\{\widetilde{T}_{\{OH\}, i}\}^K_{i=1}\sim P_t(\widetilde{T}_{\{OH\}})$. The probability $P_{\text{in}}$ that $\mathbf{g}$ is included by the target hole is defined by:

\begin{gather}
    P_{\text{in}}(\mathbf{g}) = \frac{\sum^K_{i=1}h(\widetilde{T}_{\{OH\}, i}, \mathbf{g})}{K},\\
    % P_{\text{out}}(\mathbf{g}) = 1 -  P_{\text{in}}(\mathbf{g}) \\
    h(\widetilde{T}_{\{OH\}}, \mathbf{g}) =   \left\{
             \begin{array}{lr}
            1, & \mathbf{g}\in \widetilde{T}_{\{OH\}}\mathcal{A}_{h} \\
           0, & \text{Otherwise}
\end{array}
\right. 
\end{gather}
Let $ \mathcal{H}(\cdot)$ represent the entropy of the given probabilistic density function. The expected entropy reduction is formulated as:
\begin{equation}
    \Delta \mathcal{H}(\mathbf{g}) = \mathcal{H}(P_t(\widetilde{T}_{\{OH\}})) - E[\mathcal{H}(P_t(\widetilde{T}_{\{OH\}})\mid \mathbf{g})]
\end{equation}
where $E[\mathcal{H}(P_t(\widetilde{T}_{\{OH\}})\mid \mathbf{g})]$ is the expected entropy after evaluating $\mathbf{g}$.
To maximize information gain, the desired state should spatially overlap with the selected grid point $\mathbf{g}^* \in \mathcal{G}$ that maximizes $\Delta \mathcal{H}(\mathbf{g})$ for contact constraints identification:
\begin{equation}
\label{eq:grid_max}
\mathbf{g}^* = \arg\max_{\mathbf{g} \in \mathcal{G}} \Delta \mathcal{H}(\mathbf{g})
\end{equation}
The convergence of the proposed entropy-based exploration is proven in \textit{Theorem}~\ref{pf_conv}. 

\begin{algorithm}
\caption{Entropy-based Interactive Perception}
\renewcommand{\algorithmicrequire}{\textbf{Input:}}
\renewcommand{\algorithmicensure}{\textbf{Output:}}
\label{interactive_p}
\begin{algorithmic}[1]
\REQUIRE  $\mathcal{V}_{h}$, $\mathcal{A}_\text{board}$, $\mathcal{P}_e$, $\{O\}$
% \ENSURE Task finished 
\STATE $t\gets0$
\STATE Sample grid points $\mathcal{G}\gets\mathcal{A}_\text{board}$
\STATE Initialize proposal region $\mathcal{X}_t\gets\mathcal{A}_\text{board}$ \COMMENT{Eq.\eqref{eq:init_x0}}
\WHILE{not converged}  
    \STATE  $\mathbf{g}^*\gets$ Select grid point for interaction  \COMMENT{Eq.\eqref{eq:grid_max}}
    \STATE  $\mathcal{P}_{o,\text{footprint},t}$ $\gets$ Active contact with the selected point
    \STATE  $\mathcal{X}_{t+1}\gets$ ConstraintsUpdate($\mathcal{P}_{o,\text{footprint},t}$)  \COMMENT{Eq.\eqref{eq:region_update}}
    \STATE $t\gets t+1$
\ENDWHILE
\ENSURE bounded region $\mathcal{X}_{T1}$


\end{algorithmic}
\end{algorithm}





\subsection{Physical Manipulation Funnel}
\label{sec:pf}

\begin{figure*}
    \centering
    \includegraphics[width=0.9\textwidth]{Figures/Figure5_2.pdf}
    \caption{(a) The peg's state $\mathbf{x}_t$ is projected as  $[v_{\text{lateral}}; \theta_\text{lateral}]$. (b) By setting the translation deviation between the desired state $\mathbf{x}^{\text{d}}_t$ and the starting state $\mathbf{x}_t$ only on the $XY$-plane of $\{O\}$, a 2-D potential energy field is formulated. (c) The corner alignment process is formulated as aligning the point $v_t = v_\text{lateral}$ to the corner $v_j=v_h^\text{corner}$ under the drive of the created potential energy field, while the edges are considered non-penetration walls.}
\label{subspace}
\vspace{-0.5cm}
\end{figure*}

The physical manipulation funnel aims to leverage environmental contacts as physical constraints in the execution task space to iteratively reduce $\Delta \mathbf{x}$ for peg-in-hole insertion. Based on the task mechanics as Fig.~\ref{fig:mechanics}-(a), we consider a sequential process as 1) aligning an inclined state to its corresponding corner and 2) adjusting the aligned inclined state to insertion. All the states $\mathbf{x}_t$ described in this section are considered inclined states, which are defined by $p_v$, $\alpha$, and $\beta$ as introduced in Eq.~\eqref{pv_vertex} and~\eqref{n_vertex}. We describe the spatial relationship between the $\mathbf{x}_t$ and $\mathbf{x}^*$ (the target peg-in-hole state) based on the $\mathcal{P}_{o, \text{footprint},t}$ and the target corner $v_h^\text{corner}$. Specifically,
$\mathcal{P}_{o, \text{footprint},t}$ forms a 2-D polygon as $\mathcal{V}_{o, \text{footprint},t}=(p_o^0, p_o^1,...,p_o^k), p_o\in\mathcal{P}_{o, \text{footprint},t}$ with a corresponding area $\mathcal{A}_{o, \text{footprint},t}\subset\mathbb{R}^3$ on the $XY$-plane of $\{O\}$. The state deviation $\Delta \mathbf{x}$ is defined based on $\mathcal{V}_{o, \text{footprint},t}$ and $v_h^\text{corner}$ as \textit{Definition}~\ref{subspace_proj}.



\begin{definition}
\label{subspace_proj}
Given an inclined peg state $\mathbf{x}_t$ with the lateral edge of the supporting vertex $p_v$ intersects with the $XY$-plane of $\{O\}$, we project its state as $\Psi: \mathbb{R}^6\mapsto \mathbb{R}^4$. We use the $v_\text{lateral}\in \mathbb{R}^3$ and the angle value $\theta_\text{lateral}\in\mathbb{R}$ of $\angle v_\text{lateral}$ to describe the pose as $\Psi(\mathbf{x}_t)=[v_{\text{lateral}}; \theta_{\text{lateral}}]$, as illustrated in Fig.~\ref{subspace}-(a). $v_{\text{lateral}}$ is the intersection point between the lateral edge of $p_v$ and the $XY$-plane of $\{O\}$, $\angle v_\text{lateral}$ is the angle formed by $v_{\text{lateral}}$ and its nearby vertices in $\mathcal{V}_{o, \text{footprint},t}$. Given the target corner for alignment $v_h^\text{corner}$ and its corresponding angle $\angle v_h^\text{corner}$, the deviation $\Delta \mathbf{x}$ is transformed into $\Delta \mathbf{s}$ as follows:
\begin{equation}
    \Delta \mathbf{s} = \overset{\text{translation deviation:}\Delta v}{\left\|v_{\text{lateral}}-T_{\{OH\}}v_h^{\text{corner}} \right\|} +  \overset{\text{inclined deviation:}\Delta \theta}{|\theta^\text{corner}-\theta_\text{lateral}|}
\end{equation}
where $\theta^\text{corner}, \theta_\text{lateral}$ is the angle value of $\angle v_h^\text{corner}$ and $\angle v_\text{lateral}$ respectively. $\Delta \mathbf{x}\rightarrow0$ is considered equal to $\Delta \mathbf{s}\rightarrow 0$.
\end{definition}



Since the footprint fully contains the projection of the intersection part beneath the board surface plane, the environmental constraints as defined in Eq.~\ref{non-penetration} are projected into the $XY$-plane of $\{O\}$ as $\mathcal{A}_{o, \text{footprint},t}\subset T_{\{OH\}}\mathcal{A}_h$. 
% \end{proof}



In the following, we describe the process of inclined corner alignment as $\Delta v$ reaches zero and the process from inclined to insertion as $\Delta \theta$ reaches zero. Since each degree of freedom in the Cartesian space of $\{O\}$ is decoupled as $\mathbf{K}_d$ is a diagonal stiffness matrix, we aim to leverage the potential caused by translation deviation for corner alignment and rotational deviation for insertion based on \textit{Lemma}~\ref{energy_f_l}. 

\begin{lemma}
\label{energy_f_l}
Under the quasi-static assumption, the motion of the peg $\mathbf{x}$ is considered driven by a potential energy field:
\begin{equation}
\label{energy_peg}
U(\mathbf{x}) = \frac{1}{2} (\mathbf{x}_d - \mathbf{x})^\top \mathbf{K}_d (\mathbf{x}_d - \mathbf{x})   
\end{equation}
Given an interaction $\mathbf{c}_t^v=(\mathbf{x}_t, \mathbf{x}^{\text{d}}_t)$, the resulted steady pose $\mathbf{x}_{t+1}$ automatically falls into its nearby local minimum energy under the non-penetration environmental constraints as $U(\mathbf{x}_t)\geq U(\mathbf{x}_{t+1}) \geq U(\mathbf{x}_t^{\text{d}})$ .
\end{lemma}
\begin{proof}
The peg tends to rest at a lower energy state in the potential energy field. Also, the peg cannot move to a higher energy state without external force.
\end{proof}



\textbf{Inclined Corner Alignment:} By constraining the deviation between the starting state $\mathbf{x}_t$ and desired state $\mathbf{x}_t^{\text{d}}$ only as planar translation in the $XY$-plane of $\{O\}$ (as illustrated in Fig.~\ref{subspace}-(b)), the applied external force to the peg defined by Eq.~\eqref{ext_force} can be projected into the $XY$-plane as follows:
\begin{equation}
    \mathbf{F}_\text{ext}^\text{planar} = \mathbf{K}_d [\Delta x, \Delta y, 0, 0, 0, 0]^\text{T}
\end{equation}
The formulation of $\mathbf{F}_\text{ext}^\text{planar}$ can be rewritten into a potential energy field based on the desired point $v_d\in\mathbb{R}^3$ and any point $v\in\mathbb{R}^3$ on the $XY$-plane of $\{O\}$ in a quadratic form:
\begin{equation}
\label{energy}
U_\text{XOY}(v) = \frac{1}{2} (v_d - v)^\top \mathbf{K}_d|_{1:3, 1:3} (v_d - v)    
\end{equation}
As illustrated in Fig.~\ref{subspace}-(c12), for an angle formed by the target corner vertex $v_j = T_{\{OH\}}v_h^\text{corner}$ and its nearby vertices, its edges are considered non-penetration walls in $U_\text{XOY}(v)$. Let $v_t$ be the position of $v_\text{lateral}$ at time $t$; we aim to leverage such constraints to shape the motion of $v_t$ to rest at  $v_j$ under the drive of $U_\text{XOY}(v)$.
Specifically, our objective is to formulate a \textit{potential well} to let $v_j$ be the local minimum in a potential energy field so that $v_t$ tends to rest at $v_j$ without escaping. This process involves two fundamental requirements: 1) finding an area $\mathcal{A}_\text{well}$ to place the attraction point $v_d$ (defined by $\Psi(\mathbf{x}_t^\text{d})$) and 2) finding the \textit{basin of attraction} $\mathcal{A}_\text{basin}$ where all initial states $v_t$ inside it will eventually move to $v_j$. Both $\mathcal{A}_\text{well}$ and $\mathcal{A}_\text{basin}$ should only condition on the non-penetration constraints from angle $\angle v_i v_j v_k$.

We start with a straightforward example of aligning a point $v_t$ to a determinate vertex $v_j$ in the small interior area of an angle $\angle v_i v_j v_k$ on the $XY$-plane of $\{O\}$. First, the formulation of $\mathcal{A}_\text{well}$ is defined in \textit{Lemma}~\ref{well1}. Then, we introduce the formulation of $\mathcal{A}_\text{basin}$ in \textit{Lemma}~\ref{well2}.

\begin{lemma}
\label{well1}
Area $\mathcal{A}_{\text{well}} \subset \mathbb{R}^3$ exist on the $XY$-plane of $\{O\}$ and only condition on the angle $\angle v_i v_j v_k$ (as visualized in Fig.~\ref{subspace}-(c1): Region A), for any desired point $v_d\in\mathcal{A}_{\text{well}}$, $v_j$ is always the local minimum state in the created basin of attraction $\mathcal{A}_{\text{basin}}^{v_d}\subset \mathbb{R}^3$ (as visualized in Fig.~\ref{subspace}-(c2): Region B). $\mathcal{A}_{\text{well}}$ is defined as:
\begin{equation} 
\label{wells}
    \mathcal{A}_{\text{well}} = \{v\in \mathbb{R}^3 \mid \frac{\pi}{2}\leq \angle v_i v_j v \leq (\frac{3\pi}{2} - \angle v_i v_j v_k) \}
\end{equation}
while $\mathcal{A}_{\text{basin}}^{v_d}$ is defined as:
\small
\begin{equation}
    \mathcal{A}_{\text{basin}}^{v_d} = \{v\in \mathbb{R}^3 \mid 
    \angle v_i v_d v \leq \angle v_i v_d v_k \cap \angle v_i v_j v \leq \angle v_i v_jv_k\}    
\end{equation}
\normalsize

\end{lemma}
\begin{proof} 
The absolute distance between $v_d\in\mathcal{A}_\text{well}$ and $v_t$ represents the energy level of a quadratic-formed energy field. As $\forall v_d\in \mathcal{A}_\text{well}, \forall v_t \in \mathcal{A}_{\text{basin}}^{v_d}, v_t\neq v_j: |v_d-v_t|>|v_d-v_j|$, thus proven $v_j$ is the local minimum state in $\mathcal{A}_{\text{basin}}^{v_d}$, $\mathcal{A}_\text{well}$ and $\mathcal{A}_{\text{basin}}^{v_d}$ establish.
\end{proof} 

\begin{lemma}
\label{well2}
Area $\mathcal{A}_{\text{basin}}\subset \mathbb{R}^3$ exist on the $XY$-plane of $\{O\}$ and only condition on the angle $\angle v_i v_j v_k$ (as visualized in Fig.~\ref{subspace}-(c3): Region B). For any desired point $v_d\in\mathcal{A}_{\text{well}}$ defined in Eq.~\eqref{wells}, $v_j$ is always the local minimum state in $\mathcal{A}_{\text{basin}}$. 
$\mathcal{A}_{\text{basin}} = \cap \{\mathcal{A}_{\text{basin}}^{v_d}\mid \forall v_d\in\mathcal{A}_{\text{well}}\}$ is defined as 
\begin{equation}
\begin{aligned}
 \mathcal{A}_{\text{basin}} =  & \{v\in \mathbb{R}^3 \mid \angle v v_i v_j \leq \frac{\pi}{2} \cap \angle v v_k v_j \leq \frac{\pi}{2}\}\\ &\text{when } \mid v_d - v_j \mid
  \rightarrow\infty \land v_d\in \mathcal{A}_{\text{well}}
\end{aligned}
\end{equation}
\end{lemma}
\begin{proof}
The original energy gradient of $U_\text{XOY}(v)$ is derived as $\mathbf{F}_\text{energy}= -\nabla U_\text{XOY}(v)$. While $\mid v_d - v_j \mid \neq 0$, any $v_t\in\mathcal{A}_\text{basin}$ moves along with the force gradient and will get in contact with the non-penetration wall first. As long as $v_t$ is in contact with the wall, the component of the energy gradient $\mathbf{F}_\text{energy}$ that is normal to the wall is canceled out by the non-penetration constraint as illustrated in Fig.~\ref{subspace}-(b2). Given the wall's normal vector $\mathbf{n}_\text{wall}$ at the contact point, the modified force gradient is derived as $\mathbf{F}_\text{total}=\mathbf{F}_\text{energy}+\mathbf{F}_\text{wall}=-\nabla  U_\text{XOY}(v) + (\nabla  U_\text{XOY}(v)\cdot\mathbf{n}_\text{wall})\mathbf{n}_\text{wall}$. For any $v_t$ in contact with the wall, it performs physical gradient descent under force $\mathbf{F}_\text{total}$ and reaches the local minimum as the force gradient $\mathbf{F}_\text{total}=0$ when $\mathbf{n}_\text{wall}$ is on the same line of $\mathbf{F}_\text{energy}$. As proven in \textit{Lemma}~\ref{well1}, the local minimum of energy field is at $v_j$, thus proven $\mathcal{A}_{\text{basin}}$ establish.
\end{proof}




Based on $\mathcal{A}_\text{well}$ and $\mathcal{A}_\text{basin}$, the corner alignment process is introduced in \textit{Lemma}~\ref{ali} through potential well construction.  
\begin{lemma}
\label{ali}
Under the condition that energy caused by translation deviation is significantly larger than that caused by rotation deviation, by setting the desired state $\mathbf{x}_t^{\text{d}}$ with its projected $v_d\in\mathcal{A}_{\text{well}}$, any starting state $\mathbf{x}_t$ with $v_t\in \mathcal{A}_\text{basin}$ will automatically align with the target corner (as the lateral edge of $p_v$ intersects with $ v_j$ at state $\mathbf{x}_{t+1}=\Pi(\mathbf{x}_t, \mathbf{x}_{t}^{\text{d}})$).
\end{lemma}
\begin{proof}
As the command from impedance control and the target corner creates a potential well with $v_j$ as its local minimum energy state, as proved in \textit{Lemma}~\ref{well1} and~\ref{well2}, $\mathbf{x}_{t+1}$ automatically rests at the local minimum state as $v_{t+1}\rightarrow v_j$.
\end{proof}

We relax the assumption on a determinate $v_j = T_{\{OH\}}v_h^\text{corner}$ and expand the potential well construction process on the probabilistic distribution of the target hole's state $P(\widetilde{T}_{\{OH\}})$, as outlined in Alg.~\ref{alg:alignment}. $K$ states are sampled as $\{\widetilde{T}_{\{OH\},i}\}^{K}_{i=1} \sim P(\widetilde{T}_{\{OH\}})$ and the ground truth of $T_{\{OH\}}$ is assumed to be covered the samples. By calculating the intersection area of $\widetilde{\mathcal{A}}_\text{basin}=\cap \{\mathcal{A}_{\text{basin,i}}\}^k_{i=1}$ and $\widetilde{\mathcal{A}}_\text{well}=\cap \{\mathcal{A}_{\text{well,i}}\}^K_{i=1}$ over pose samples $\{\widetilde{T}_{\{OH\},i}\}^{K}_{i=1}$, it is guaranteed to find a sub-area as $\widetilde{\mathcal{A}}_\text{well}\subset T_{\{OH\}}\mathcal{A}_\text{well}$ and $\widetilde{\mathcal{A}}_\text{basin}\subset T_{\{OH\}}\mathcal{A}_\text{basin}$ for potential well construction. Theoretically, the robustness of the corner alignment is conditioned on  $\widetilde{\mathcal{A}}_\text{well}$ and $\widetilde{\mathcal{A}}_\text{basin}$ instead of the geometric size of $\mathcal{V}_{h}$. 
\begin{algorithm}
\caption{Nondeterministic Corner Alignment}
\renewcommand{\algorithmicrequire}{\textbf{Input:}}
\renewcommand{\algorithmicensure}{\textbf{Output:}}
\begin{algorithmic}[1]
\label{alg:alignment}
\REQUIRE bounded region $\mathcal{X}_{T1}$, $P(\widetilde{T}_{\{OH\}})\gets \mathcal{X}_{T1}$
% \ENSURE Task finished 
\STATE Initialize samples $\{\widetilde{T}_{\{OH\},i}\}^{K}_{i=1} \sim P(\widetilde{T}_{\{OH\}})$, $T_{\{OH\}} \in \widetilde{T}_{\{OH\},i}\}^{K}_{i=1}$, $\widetilde{\mathcal{A}}_\text{well} = \widetilde{\mathcal{A}}_\text{basin} = {XY}\text{-plane of }  \{O\}$
\FOR{$i = 0,1,..., K-1$}
\STATE $\widetilde{\mathcal{A}}_\text{well}$ = $\widetilde{\mathcal{A}}_\text{well}\cap \widetilde{T}_{\{OH\},i}\mathcal{A}_\text{well}$
\STATE $\widetilde{\mathcal{A}}_\text{basin}$ = $\widetilde{\mathcal{A}}_\text{basin}\cap \widetilde{T}_{\{OH\},i}\mathcal{A}_\text{basin}$
\ENDFOR
 \STATE $v_\text{lateral}\gets \Psi(\mathbf{x})$, $v_\text{lateral}\in \widetilde{\mathcal{A}}_\text{basin}$
\STATE $v^{\text{d}}_\text{lateral}\gets \Psi(\mathbf{x}^{\text{d}})$, $v^{\text{d}}_\text{lateral}\in \widetilde{\mathcal{A}}_\text{well}$
\STATE Execute interaction $c^v=(\mathbf{x}, \mathbf{x}^{\text{d}})$
\end{algorithmic}
\end{algorithm}


