\begin{restatable}{theorem}{welfareapproxspecial}\label{thm:welfareapproxspecial}
The following claims holds:
\begin{enumerate}[leftmargin=*, label=(\arabic*)]
    \item For path DPGs, there is an FPTAS for computing the optimal social welfare.
    \item For enemies and neutrals DPGs, there is a polynomial time algorithm that computes location profiles whose social welfare is at least $0.879$ of the optimal social welfare.
    %\item For friends and enemies DPGs, \textcolor{blue}{Can we do someting better here?}
\end{enumerate}
\end{restatable}
\begin{proof}[Proof Sketch]
For enemies and neutrals DPGs, we use the close connection between \textup{\textsc{MaxCut}} and finding a welfare optimal location profile. In particular, this connection allows us to apply the approximation algorithm of \citet{GoWi19940879} for \textup{\textsc{MaxCut}} to our setting. 

For path DPGs, we design an FPTAS by introducing a set of possible locations $L=\{\frac{0}{k},\frac{1}{k},\dots,\frac{k}{k}\}$. We then show that we can find the location profile $A^*$ that maximizes the social welfare subject to the condition that $A_i^*\in L$ for all $i\in N$ in polynomial time with respect to $|N|$ and $k$. Specifically, we reduce this problem to finding a longest path in a directed acyclic graph with $nk$ vertices. Moreover, we prove that the social welfare of $A^*$ is at least $1-\frac{2}{k}$ times the optimal social welfare, so our algorithm is indeed an FPTAS.
\end{proof}

\subsection{Price of Anarchy}

Finally, we relate our results for welfare optimality and jump stability by investigating the price of anarchy of DPGs. The price of anarchy, as suggested by 
%PL: KoPa09b is the journal version of the 1999 conference paper with same name, where they precisely claim to introduce the PoA (without using that name)
\citet{KoPa09b}, is the ratio between the optimal social welfare and that of the worst jump stable location profile. To formally define this concept, let $JS(I)$ denote the set of jump stable location profiles for a DPG $I$. Then, the \emph{price of anarchy} of a DPG $I$ with $JS(I)\neq \emptyset$ is
    \[PoA(I)=\frac{\max_{A\in [0,1]^n} \USW{}_I(A)}{\min_{A\in JS(I)}\USW{}_I(A)}.\]

We next show that every DPG (that permits jump stable location profiles) has a price of anarchy of at most $2$. Consequently, every algorithm for computing jump stable location profiles guarantees at least half of the optimal social welfare. 

%\begin{definition}
%    Given a distance preservation game $I=\langle N,M,d\rangle$ with $n$ agents, the price of anarchy is
%    \[PoA(I)=\frac{\max_{A\in [0,1]^n} \USW{}(A)}{\min_{A:A\text{ is } JS}\USW{}(A)}\]
%\end{definition}

\begin{restatable}{theorem}{POA}\label{thm:POA}
   It holds that $PoA(I)\leq 2$ for all DPGs $I$ with $JS(I)\neq\emptyset$. Further, there is a DPG $I$ with $JS(I)\neq\emptyset$ and $PoA(I)=2$.
\end{restatable}
\begin{proof}
    Consider a DPG $I=\langle N,(M_i)_{i\in N},(d_i)_{i\in N}\rangle$ and let $A\in JS(I)$. We focus on an agent $i\in N$ and will show that $u_i(A)\geq \frac{|M_i|}{2}$. For this, we observe that $u_i(A)\geq u_i(A^{i\mapsto 0})$ and $u_i(A)\geq u_i(A^{i\mapsto 1})$ since $A$ is jump stable. Next, let $j$ denote an agent in $M_i$. When agent $i$ jumps to $0$, we have that $u_i(A^{i\mapsto 0}, j)=1-|A(j)-d_i(j))|$. Similarly, it holds that $u_i(A^{i\mapsto 1}, j)=1-|1-A(j)-d_i(j)|$. Next, it can be shown by a case distinction with respect to the absolute values that $|A(j)-d_i(j)|+|1-A(j)-d_i(j)|\leq 1$, so $1-|A(j)-d_i(j))|+1-|1-A(j)-d_i(j)|\geq 1$. %%SN: The case distinction part is not obvious and we should have a formal proof for this. 
    Applying the same argument for all agents in $M_i$ shows that $u_i(A^{i\mapsto 0})+u_i(A^{i\mapsto 1})\geq |M_i|$. Since $u_i(A)\geq u_i(A^{i\mapsto 0})$ and $u_i(A)\geq u_i(A^{i\mapsto 1})$, this means that $u_i(A)\geq \frac{|M_i|}{2}$. Finally, by summing over all agents, it follows that the social welfare of $A$ is at least half of the optimum. 

    Next, to show that our bound on the price of anarchy is tight, let $I$ be the symmetric DPG illustrated in \cref{fig:ex3}. % DPG with four agents $N=\{1,2,3,4\}$ such that $M_1=M_3=\{2,4\}$, $M_2=M_4=\{1,3\}$, and $d_i(j)=1$ for all $i\in N$, $j\in M_i$. 
    Moreover, let $A$ denote the location profile where $A_1=A_2=0$ and $A_3=A_4=1$. For each agent $i$, both agents in $M_i$ are at the opposite ends of the unit interval in $A$. Thus, all points in $[0,1]$ yield utility $1$ for each agent. Consequently, $A$ is jump stable and $\USW{}_I(A)=4$. However, in the location profile $A'$ with $A'_1=A'_3=0$ and $A'_2=A'_4=1$, every agent's utility is $2$ and $\USW{}_I(A')=8$. Hence, $PoA(I)=2$.
\end{proof}

The proof of \Cref{thm:JSsymmetric} shows that welfare optimality implies jump stability for symmetric DPGs. Thus, for symmetric DPGs, the {price of stability}, i.e., the ratio between the optimal social welfare and that of the best jump stable location profile \citep{anshelevich2008price}, is $1$. In contrast, the price of stability can be arbitrarily close to $2$ for general DPGs.
