\section{Proofs}\label{apdx:proof}

\begin{proof}[Proof of \Cref{prop:valid}]
Note that $\mathcal{C}_i$ are disjoint. 
Therefore, letting $c_i = \abs{\mathcal{C}_i}$ and $a_i = \abs{\mathcal{D}_{L}^\phi \cap \mathcal{C}_i}$, we have
\begin{align}
\frac{\abs{\mathcal{D}_{L}^\phi \cap \bigcup_{i \in \mathcal{K}_*}\mathcal{C}_i}^2}{ \abs{\bigcup_{i \in \mathcal{K}_*}\mathcal{C}_{i}}}
= \frac{(\sum_{i \in \mathcal{K}_*} a_i)^2}{\sum_{i \in \mathcal{K}_*} c_i}
= \frac{A^2}{C},
\end{align}
where $A = \sum_{i \in \mathcal{K}_*} a_i$ and $C = \sum_{i \in \mathcal{K}_*} c_i$. 

If $\ell \notin \mathcal{K}_*$, we must have 
\begin{align}
&\frac{(a_\ell + \sum_{i \in \mathcal{K}_*} a_i)^2}{c_\ell + \sum_{i \in \mathcal{K}_*} c_i}
< \frac{A^2}{C}
\intertext{and it is equivalent to}
\iff & \frac{(a_\ell + A)^2}{c_\ell + C}
- \frac{A^2}{C} < 0
\\
\iff & \frac{C a_\ell^2 + 2 C a_\ell A + C A^2 - C A^2 - c_\ell A^2}{(c_\ell + C) C}
< 0
\\
\iff & C a_\ell^2 + 2 C a_\ell A - c_\ell A^2 < 0
\\
\iff & \frac{a_\ell}{c_\ell }(a_\ell + 2 A)  < \frac{A^2}{C}.
\end{align}

If $k \in \mathcal{K}_*$, we must have 
\begin{align}
&\frac{(- a_k + \sum_{i \in \mathcal{K}_\phi} a_i)^2}{- c_k + \sum_{i \in \mathcal{K}_\phi} c_i}
\leq \frac{A^2}{C}.
\intertext{and it is equivalent to}
\iff & \frac{(-a_k + A)^2}{-c_k + C}
- \frac{A^2}{C} \leq 0
\\
\iff & \frac{C a_k^2 - 2 C a_k A + C A^2 - C A^2 + c_k A^2}{(-c_k + C) C}
\leq 0
\\
\iff & C a_k^2 - 2 C a_k A + c_k A^2 \leq 0
\\
\iff & \frac{a_k}{c_k }(- a_k + 2 A)  \geq \frac{A^2}{C}.
\end{align}

Altogether, we have
\begin{multline}
\frac{a_\ell}{c_\ell }(a_\ell + 2 A) < \frac{A^2}{C} \leq \frac{a_k}{c_k }(- a_k + 2 A)
\\
\implies
1 \leq \frac{(a_\ell + 2 A)}{(- a_k + 2 A)} < \frac{a_k/ c_k}{a_\ell / c_\ell }.
\end{multline}
This completes the proof.
\end{proof}

\begin{proof}[Proof of \Cref{prop:mcar}]
For a given $\mathcal{K}_*$, we have
\begin{align}
\frac{(\sum_{k \in \mathcal{K}}\abs{\mathcal{D}_{L}^\phi \cap \mathcal{C}_k})^2}{\abs{\mathcal{D}_{L}^\phi}\sum_{k \in \mathcal{K}} \abs{\mathcal{C}_k}}
&= \frac{(\sum_{i \in \mathcal{K}} c n_i \mathbb{I}\{i \leq K_A\})^2}{\abs{\mathcal{D}_L^\phi} \sum_{i \in \mathcal{K}} n_i}
\\
&= \frac{c^2}{\abs{\mathcal{D}_L^\phi} } \frac{ (\sum_{i \in \mathcal{K}} n_i \mathbb{I}\{i \leq K_A\})^2 }{ \sum_{i \in \mathcal{K}} n_i}.
\end{align}
The right-most side is maximized when $\mathcal{K}_* = \{1, \dots, K_A\}$. 
The reason is as follows. 
The inclusion of $i > K_A$ only increases the denominator. 
Therefore, $\mathcal{K}_*$ only includes $i \leq K_A$. 
Then, it is easy to see that for $\mathcal{K} \in 2^{\{1, \dots, K_A\}}$, 
\begin{equation}
\frac{c^2}{\abs{\mathcal{D}_L^\phi} } \frac{ (\sum_{i \in \mathcal{K}} n_i \mathbb{I}\{i \leq K_A\})^2 }{ \sum_{i \in \mathcal{K}} n_i}
= \frac{c^2}{\abs{\mathcal{D}_L^\phi} } \sum_{i \in \mathcal{K}} n_i
\end{equation}
and the right-hand side is maximized when $\mathcal{K} = \{1, \dots, K_A\}$. This completes the proof.
\end{proof}

