\title{PBFT‑Backed Semantic Voting for Multi‑Agent Memory Pruning}

\author{\IEEEauthorblockN{Bach Duong}
\IEEEauthorblockA{\textit{FPT University}\\
\textit{Sun Asterisk}\\
duong.xuan.bach@sun-asterisk.com}
