\vspace{-20pt}
  \caption{(a) Signal mixing in the real world; (b) Relative RIR model; and (c) Relative RIR from virtual sources to real channels. Measurement noise is ignored in the figures.}
  \label{fig:signal_model}
  \vspace{-2pt}
\end{figure}
