% \section{Background}
% Forward Convolutive Prediction (FCP)~\cite{unssor, fcp, fcp2} and Diffusion Posterior Sampling~\cite{DPS} are two crucial components of our method. In short, FCP is a way to estimate relative room impulse response (relative RIR) that can filter a single-channel speech source to another channel (mentioned as relative RIR estimator in Sec.~\ref{sec:overview} and Fig.~\ref{fig:overview}), and DPS is a sampling technique to use a pre-trained unconditional diffusion model to solve inverse problems.
\vspace{-4pt}
\subsection{Relative RIR Estimation}\label{sec:fcp}
Since log likelihood $\log~p(x_{1:C} | \hat{s}^0_{1:K}, g^{1:K}_{0\rightarrow {1:C}})$ is tractable, we propose to estimate the $g^{1:K}_{0\rightarrow {1:C}}$ in a maximum likelihood manner using mixtures $x_{1:C}$ and denoised sources $\hat{s}^0_{1:K}$:
{\small
\setlength{\abovedisplayskip}{5pt} % Reduce space above the equation
\setlength{\belowdisplayskip}{1pt} % Reduce space below the equation
\begin{align}
        \hat{g}^{1:K}_{0\rightarrow {1:C}}~~=~~\underset{g^{1:K}_{0\rightarrow {1:C}}}{\arg\max}\;~~ \log\;~p(x_{1:C} | g^{1:K}_{0\rightarrow {1:C}}, \hat{s}^0_{1:K})\label{eq:relativerir_ml}
\end{align}}
However, previous work has shown that it is better to estimate the filters in spectral domain~\cite{eras, consolidated} instead of in the time domain shown above. 
Hence, we transform to the Short-Time-Fourier-Transform (STFT) domain.
In STFT domain, Eq.~\ref{eq:virtual_signal_model} becomes:
{\small
\setlength{\abovedisplayskip}{5pt} % Reduce space above the equation
\setlength{\belowdisplayskip}{5pt} % Reduce space below the equation
\begin{align} 
  S_{k,c}(l, f) &= G^k_{0\rightarrow c}(f) \cdot S_{k}(l, f)\label{eq:rtf}
\end{align}
}
where $S_{k,c}(l, f)$ and $S_{k}(l, f)$ are the STFT of $s_{k,c}(t)$ and $s_k(t)$, respectively. 
$G^k_{0\rightarrow c}(f)$ is the discrete Fourier transform of $g^k_{0\rightarrow c}(t)$, where the FFT size is the same as the STFT. 

\textbf{Relaxing narrowband assumption:} The above equation is unrealistic for speech signals because it makes a narrowband approximation; it assumes that the length of the relative RIR filter is shorter than the FFT size. 
In real environments, the relative RIR filter can be in hundreds of milliseconds, while the FFT size is usually only tens of milliseconds. 
To relax this assumption, we model the relative RIR over multiple time-frames as $G^k_{0\rightarrow c}(l, f)$.
This multi-frame filter in the STFT domain is then {\em convolved} with the virtual source as follows:
% {\small
% \setlength{\abovedisplayskip}{3pt} % Reduce space above the equation
% \setlength{\belowdisplayskip}{3pt} % Reduce space below the equation
% \begin{align} 
%   S_{k,c}(l, f) &= G^k_{0\rightarrow c}(l, f) *_l S_{k}(l, f)\label{eq:stft_relative}\\
%    G^k_{0\rightarrow c}(l, f) *_l S_{k}(l, f) &= \sum_{j=-F}^{P} G^k_{0\rightarrow c}(j, f) S_{k}(l-j, f)\label{eq:stft_relative2}
% \end{align}
% }
{\small
\setlength{\abovedisplayskip}{6pt} % Reduce space above the equation
\setlength{\belowdisplayskip}{6pt} % Reduce space below the equation
\begin{align} 
   S_{k,c}(l, f) &= G^k_{0\rightarrow c}(l, f) *_l S_{k}(l, f)\label{eq:stft_relative}
\end{align}
}
where $l,f$ are frame and frequency index, and $F, P$ are the number of future and past frames of the relative RIR $G^k_{0\rightarrow c}(l, f)$, all in STFT domain.
Observe that $*_l$ in~Eq.\ref{eq:stft_relative} denotes {\em convolution} in the frame dimension:
{\small
\setlength{\abovedisplayskip}{3pt} % Reduce space above the equation
\setlength{\belowdisplayskip}{3pt} % Reduce space below the equation
\begin{align} 
   G^k_{0\rightarrow c}(l, f) *_l S_{k}(l, f) &= \sum_{j=-F}^{P} G^k_{0\rightarrow c}(j, f) S_{k}(l-j, f)\label{eq:stft_relative2}
\end{align}
}
Thus, the complete signal model --- that connects the virtual sources to the actual mixtures at the microphones --- can be modeled as:
{\small
\setlength{\abovedisplayskip}{3pt} % Reduce space above the equation
\setlength{\belowdisplayskip}{3pt} % Reduce space below the equation
\begin{align}\label{eq:spec_model}
    X_c(l, f) =\sum\limits_{k=1}^{K} G^k_{0\rightarrow c}(l, f)*_l S_{k}(l, f) + N_c(l, f)
\end{align}
}
