% \texttt{WhiteBoxUQ}         & Limited       & Minimal       &    None    \\
% \texttt{LLMPanel} & Universal      & Low-High   & Low-high     \\
%  \texttt{UQEnsemble}         & Flexible      & Flexible   & Flexible    \\ 
% \bottomrule
% \end{tabular}
% \label{tab:classes}
