\subsection{Proof of Lemma \ref{lem:unst-neighs-with-swing-neighs}}


To prove Lemma \ref{lem:unst-neighs-with-swing-neighs}, we follow the argument in the first half of the proof of \cite[Lemma 3.3]{jhk-etal2021}.

\begin{proof}[Proof of Lemma \ref{lem:unst-neighs-with-swing-neighs}]
    Let $D = c\adv p^{3/2}n^{1/2}$ for a constant $c$ chosen later.
    Fix an arbitrary choice of the $S$.
    This also fixes the coloring $\Clr$.
    Temporarily call the vertices $u$ such that $\bClr_1(u) = -1$ and $\Clr_1(u) = 1$ \emph{flipping}.
    It suffices to show that with probability $1 - O(n^{-1})$, every $v\in V$ has at least $D$ flipping neighbors, since the choices of $S$ are symmetrical.

    Let us narrow down to a special type of flipping neighbors that we can control.
    We call $u\in N(v)$ \emph{vulnerable} if $d_{\bR_0}(u) = d_{\bB_0\setminus S}(u)$ and $u$ has at least 1 neighbor in $S$.
    If $u$ is vulnerable, we have
    \begin{equation*}
        d_{\bR_0}(u) - d_{\bB_0}(u)
        = d_{\bR_0}(u) - d_{\bB_0\setminus S}(u) - d_S(u)
        = - d_S(u) < 0
        \implies \bClr_1(u) = -1.
    \end{equation*}
    We also have
    \begin{equation*}
        d_{R_0}(u) - d_{B_0}(u)
        = d_{\bR_0}(u) + d_S(u) - (d_{\bB_0}(u) - d_S(u))
        = d_S(u) < 0
        \implies \Clr_1(u) = 1.
    \end{equation*}
    Therefore a vulnerable vertex is flipping.
    The advantage is that we can easily lower bound the number of vulnerable neighbors of $v$.
    We claim that $v$ has at least $D$ vulnerable neighbors with probability $1 - O(n^{-2})$.

    We claim that with high probability $|N(v)\cap S| < .1\adv$.
    This is a $\Bin(\adv, p)$ random variable with mean $p\adv < 10$, so it is close to a Poisson variable.
    By Lemma \ref{lem:poisson-bound},
    \begin{equation*}
        \Pr\left(|N(v)\cap S| \ge .1\adv\right)
        \le 2\left(\frac{e\adv p}{.1\adv} \right)^{.1\adv}
        \le 2(30p)^{.1\adv} < n^{-2},
    \end{equation*}
    where the last inequality holds if $\adv > 20\log n$, which holds if $\adv p^{3/2}n^{1/2} \ge \log n$ and $p < n^{-1/2}\log n$.

    For each $U\subset V\setminus \{v\}$, we say $U$ is \emph{regular} if $|U\cap S| < .1\adv$ and $|U| \ge pn/2$.
    By the above and a Chernoff bound, $N(v)$ is regular with probability $1 - O(n^{-2})$.

    Fix a regular $U\subset V\setminus \{v\}$ and condition the probability space of $G$ on the event $U = N(v)$.
    Let $V^+ \defeq \bR_0 \setminus \{v\}$ and $V^- \defeq \bB_0 \setminus \{v\}$.
    Let $W \defeq (V\setminus \{v\}) \setminus U$ and let $W^+ \defeq V^+ \cap W$ and $W^- \defeq V^- \cap W$.
    We have $|W^-\cap S| = |W\cap S| = |S| - |U\cap S| - \one_S(v) > .8\adv$.

    % For each $u\in U$, consider the event that $u$ is vulnerable.
    % It would be great if these events were independent, since we can then easily control the amount of $u$ for which they happen.
    % Although they are not, we can define a set of ``less likely'' events that are independent.

    Let $I_u$ be the event that $u$ is vulnerable.
    It is the conjunction of the two independent events: $\{d_{\bR_0}(u) = d_{\bB_0\setminus S}(u)\}$ and $\{d_S(u) \ge 1\}$.
    % so $\Pr(I_u)$ is the product of their probabilities.
    Consider the former, we have
    \begin{equation*}
        \Pr\left(
            d_{\bR_0}(u) = d_{\bB_0\setminus S}(u)
        \right)
        = \Pr\left(
            d_{V^+}(u) + \Clr_0(v) = d_{V^-\setminus S}(u)
        \right)
        \ge \frac{r_B}{\sqrt{p(1 - p)|V\setminus S|}}
        \ge \frac{r_B}{\sqrt{pn}},
    \end{equation*}
    for a constant $r_B$ depending on $B$.
    For the latter, we have
    \begin{equation*}
        \Pr(d_S(u) \ge 1) \ge \Pr(d_{W^-\cap S}(u) \ge 1) \ge 1 - (1 - p)^{|W^-\cap S|}
        \ge 1 - (1 - p)^{.8\adv}
        \ge 1 - e^{-.8p\adv} \ge s_Bp\adv,
    \end{equation*}
    for a constant $s_B$ depending on $B$, where the last inequality is due to $p\adv \le B$.
    Therefore
    \begin{equation*}
        \Pr(I_u) = \Pr\left(
            d_{\bR_0}(u) = d_{\bB_0\setminus S}(u)
        \right) \cdot \Pr(d_S(u) \ge 1)
        \ge \frac{r_Bs_B p\adv}{\sqrt{pn}}.
    \end{equation*}
    Since $\{I_u\}_{u\in U}$ are independent after exposing $U$ (note that $S$ is fixed), and there are $|U| \ge pn/2$ of them, the number of vulnerable neighbors of $v$ dominates $X \sim \Bin\bigl(\frac{pn}{2}, r_Bs_B\adv \sqrt{\frac{p}{n}}\bigr)$ in probability.
    Note that $\E{X} = \frac{1}{2}r_Bs_B \adv p^{3/2}n^{1/2} = \frac{r_Bs_B}{2c}D$.
    Choose $c = c_B = r_Bs_B/4$,
    by a Chernoff bound,
    \begin{equation*}
        \Pr(X < D)
        = \Pr\left(X < \frac{1}{2} \E{X} \right)
        \le \exp\left[
            \frac{1}{8}\adv p^{3/2}n^{1/2}
        \right]
        \le n^{-2},
    \end{equation*}
    given $\adv p^{3/2}n^{1/2} \ge 16\log n$.
    Since this holds for all regular $U$ and the probability of an irregular $U$ is less than $n^{-2}$, the total exceptional probability is $O(n^{-2})$.
    The proof is complete.
