\subsection{Proof of Lemma \ref{lem:almost-pos-v}}


Let us move on to the proof of Lemma \ref{lem:almost-pos-v}.
Since $D$ is fixed throughout the proof, we simply let $A_{v}$ denote the event that $v$ is $D$-almost Red.
We abuse the notation and let $A$ be the set of $D$-almost Red vertices.
We have $|A| = \sum_{v\in V}\one_{A_v}$, so
\begin{equation*}
    \E{|A|} = \sum_{v\in V} \Pr(A_v)
    \ \text{ and } \
    \Var{|A|} = \sum_{v\in V} \Var{\one_{A_v}}
    + \sum_{v_1\neq v_2\in V} \Cov{\one_{A_{v_1}}, \one_{A_{v_2}}}
\end{equation*}
Our strategy is simple: we lower bound $\E{|A|}$ by lower bounding each $\Pr(A_v)$, then upper bound $\Var{|A|}$ by upper bounding $\Cov{\one_{A_{v_1}}, \one_{A_{v_2}}}$ for each distinct pair $(v_1, v_2)$ (note that $\Var{\one_{A_v}} \le 1/4$ for each $v$).
Once the two bounds are available, we can just use Chebyshev's inequality \cite{chebyshev} to lower bound $|A|$ with high probability.



\subsubsection{Step 1: Lower bounding $\E{|A|}$}  \label{sec:almost-pos-set-exp}


Here is the main result of this step.
Throughout this section and the next, we assume the objects and conditions of Theorem \ref{thm:main-p<n^(-1/2)}.

\begin{claim}  \label{claim:almost-pos-set-exp}
    Let $A$ be the set of $D$-almost positive vertices.
    Let $B > 0$ be an arbitrary constant
    There are universal constants $C_1$ and $C_2$ (large enough) and a constant $c_B$ depending only on $B$ (small enough) such that if $pn \ge C_1\log^2 n$ and $B\sqrt{pn} \ge D \ge C_2\log n$, then
    \begin{equation*}
        \E{|A|} \ge \frac{n}{2} + c_BD\sqrt{\frac{n}{p}}.
    \end{equation*}
\end{claim}


To prove this claim, we want to lower bound $\Pr(A_v)$ for each $v\in V$.
We have the following claim
\begin{claim}  \label{claim:P(A_v)}
    Consider the objects and assumptions of Lemma \ref{lem:almost-pos-v}.
    Let $Z^+, Z^-$ be two independent copies of $\Bin(n/2 - \lceil pn \rceil, p)$.
    We have
    \begin{equation}  \label{eq:P(A_v)}
        \E{\one_{A_v}} \ge \Phi\left(\frac{D}{2\sqrt{pn}} + 2\bClr_0(v)\Pr(Z^+ = Z^-)\sqrt{pn}\right)
		\pm O\left(\frac{1}{\sqrt{pn}}\right).
    \end{equation}
\end{claim}


Suppose this holds, then we can prove Claim \ref{claim:almost-pos-set-exp}.

\begin{proof}[Proof of Claim \ref{claim:almost-pos-set-exp}]
    Claim \ref{claim:P(A_v)} implies for $|A| = \sum_{v\in V}\one_{A_v}$:
    \begin{equation*}
        \E{|A|} \ge \sum_{v\in V}
        \Phi\left(x_v
        \right) \pm O\left(\frac{\sqrt{n}}{\sqrt{p}}\right),
        \ \text{ where } \ 
        x_v \defeq \frac{D}{2\sqrt{pn}}
        + 2\bClr_0(v)\Pr(Z^+ = Z^-)\sqrt{pn}.
    \end{equation*}
    Note that each term inside $\Phi(\cdot)$ is less than $20$ in absolute value.
    Since the number of vertices $v$ for which $\bClr_0(v)$ are $1$ and $-1$ are both $n/2$, we can form pairs of opposite colors.
    For each pair $v, v'$, we have, by \cite[Lemma 2.4]{jhk-etal2021}, for a fixed positive function $f_0$,
    \begin{equation*}
        \Phi(x_v) + \Phi(x_{v'})
        \ge 1 + f_0(20)(x_v + x_{v'})
        = 1 + \frac{f_0(20)D}{\sqrt{pn}}.
    \end{equation*}
    This implies, if one allows $D \ge \log n$,
    \begin{equation*}
        \E{|A|} \ge \frac{n}{2} + \frac{f_0(20)D\sqrt{n}}{\sqrt{p}}
        \pm O\left(\frac{\sqrt{n}}{\sqrt{p}}\right)
        \ge \frac{n}{2} + \frac{f_0(20)D}{2}\sqrt{\frac{n}{p}}.
    \end{equation*}
    The proof is complete.
\end{proof}



The main technical challenge is Claim \ref{claim:P(A_v)}.
Fix $v\in V$.
We have $\Pr(A_v) = \Pr(\bdif_1(v) \ge -D)$.
There are two ways to write $\bdif_1(v)$ as a sum of random variables.
The first choice is $\bdif_1(v) = \sum_{u\in N(v)} \bClr_1(u)$, which is hard to analyze because $N(v)$ is random.
The second is $\bdif_1(v) = \sum_{u\in V} \bClr_1(u)\one_{u\adj v}$.
This is still hard because $\{\bClr_1(u)\}_{u\in V}$ are dependent random variables.


The key actually lies in the first method.
Fix $U\subset V$ and condition $G$ on the event $U = N(v)$, then the first sum has a fixed number of summands.
Further a subgraph $H$ over $U$ and condition on $G(U) = H$, the variables in the sum are now independent.


The vast majority of cases for $U$ will be \emph{regular}, meaning the statistics of $U$ and $G(U)$ are close to their expected values.
For convenience, we define the notations (similar to Lemma \ref{lem:unst-neighs-with-swing-neighs}'s proof):
\begin{itemize}
    \item $U^+ = \bR_0 \cap U$ and $U^- = \bB_0 \cap U$.

    \item $W = (V\setminus \{v\}) \setminus U$, then $W^+ = \bR_0 \cap W$ and $W^- = \bB_0 \cap W$.

    \item $V^+ = U^+ \cup W^+$ ($= \bR_0 \setminus \{v\}$ and $V^- = U^- \cup W^- = \bB_0 \setminus \{v\}$.

    \item We call the set $U\subset V$ and the subgraph $H$ drawn over $U$ \emph{regular} if they satisfy all conditions below.
    \begin{equation*}  \label{eq:regular-subset}
    \begin{aligned}
        |U^+| = \frac{pn}{2} \pm 3\sqrt{pn\log n},
        \ \quad \
        |U^-| = \frac{pn}{2} \pm 3\sqrt{pn\log n},
        \\
        \|\mathbf{d}_U\|_\infty \le \log n,
        \quad
        \left| \one_{|U|}^T\mathbf{d}_U \right| \le 5\log n,
        \ \text{ and } \
        \|\mathbf{d}_U\|_2 \le 3\sqrt{pn\log n},
        % \ \text{ where } \ 
        % \mathbf{d}_U \defeq [d_{U^+}(u) - d_{U^-}(u)]_{u\in U}.
        % \\
        % \max_{u\in V}|d_{U^+}(u) - d_{U^-}(u)| \le \log n,
        % \\
        % \sum_{u\in U} \left(d_{U^+}(u) - d_{U^-}(u)\right) = \pm 5\log n,
        % \\
        % \sum_{u\in U} \left(d_{U^+}(u) - d_{U^-}(u)\right)^2 \le 5pn\log n.
        % % \ \quad \
        % % \sum_{u\in U}(d_{U^+}(u) - d_{U^-}(u))^2 \le 10pn\log n,
    \end{aligned}
    \end{equation*}
    where $\mathbf{d}_U \defeq [d_{U^+}(u, H) - d_{U^-}(u, H)]_{u\in U}$ is a vector in $\R^{|U|}$.
\end{itemize}


Simple Chernoff bounds show that $U$ is regular with probability $1 - O(n^{-2})$.
The strategy is to analyze $\bdif_1(v)$ conditioned on a regular $U = N(v)$ and $H = G(U)$ to take advantage the independence of its summands.
Let us proceed with the formal proof.



\begin{proof}[Proof of Claim \ref{claim:P(A_v)}]
    Fix subset $U\subset V$ and subgraph $H$ over $U$, that are both regular, and condition $G$ on the events $N(v) = U$ and $H = G(U)$.
    Until noted otherwise, we omit them from the probability notation.

    As discussed above, we write
    $\Pr(A_v) = \Pr(\bdif_1(v) \ge -D)$, where $\bdif_1(v) = \sum_{u\in U} \bClr_1(u)$ is a sum of independent random variables.
    By the Berry-Esseen theorem \cite{esseen}, one can replace this sum with a Gaussian variable with the same expectation and variance, at the cost of some error.
    We have
    \begin{equation*}
        \E{\bdif_1(v)} = \sum_{u\in U} \E{\bClr_1(u)} = \sum_{u\in U} \eps_u
        \ \text{ where } \
        \eps_u \defeq \E{\bClr_1(u)}.
    \end{equation*}
    The notation $\eps_u$ is convenient because one can easily write
    \begin{equation*}
        \Var{\bClr_1(u)} = 1 - \eps_u^2
        \ \text{ and } \ 
        \E{\left|\bClr_1(u) - \E{\bClr_1(u)}\right|^3} = 1 - \eps_u^4,
    \end{equation*}
    the latter being important for the error term in the Berry-Esseen theorem.
    By the Berry-Esseen theorem, we have
    \begin{equation}  \label{eq:P(A_v)-proof-esseen1}
    \begin{aligned}
        \Pr(A_v) 
        & = \Phi\left(
            \frac{
                D + \E{\bdif_1(v)}
            }{
                \left(\Var{\bdif_1(v)}\right)^{1/2}
            }
        \right)
        \pm C_0 \frac{
            \sum_{u\in U} \E{\left|\bClr_1(u) - \E{\bClr_1(u)}\right|^3}
        }{
            \left(\Var{\bdif_1(v)}\right)^{1/2}
        }
        \\
        & = \Phi\left(
            \frac{
                D + \sum_{u\in U} \eps_u
            }{
                \left(|U| - \sum_{u\in U} \eps_u^2\right)^{3/2}
            }
        \right)
        \pm C_0 \frac{
            |U| - \sum_{u\in U} \eps_u^4
        }{
            \left(|U| - \sum_{u\in U} \eps_u^2\right)^{3/2}
        }.
    \end{aligned}
    \end{equation}
    Let us compute $\eps_u$ for $u\in U$ and then move on to their sum.
    Ideally, we want $\eps_u$ to be small, meaning $\Pr(\bClr_1(u) = 1)$ to be close to $1/2$.
    We have
    \begin{equation*}
    \begin{aligned}
        & \Pr(\bClr_1(u) = 1) = \Pr\left(
            d_{V^+}(u) - d_{V^-}(u) + \bClr_0(v) - \one_{U^-}(u) \ge 0
        \right)
        \\
        & \Pr\left(
            d_{W^+}(u) - d_{W^-}(u) + d_{U^+}(u) - d_{U^-}(u) \bClr_0(v) - \one_{U^-}(u) \ge 0
        \right).
    \end{aligned}
    \end{equation*}
    Note that in our conditioned space, the only random variables in the last expression are $d_{W^+}(u) \sim \Bin(|W^+|, p)$ and $d_{W^-}(u) \sim \Bin(|W^-|, p)$.
    Temporarily let $m_u$ to be the fixed part.
    We have
    \begin{equation*}
        m_u \defeq d_{U^+}(u) - d_{U^-}(u) + \bClr_0(v) - \one_{U^-}(u)
        = \pm (\|\mathbf{d}_U\|_\infty + 2)
        = \pm O(\log n).
    \end{equation*}


    By Berry-Esseen, we can replace $X^+ - X^-$ with a Gaussian random variable with mean $\E{X^+ - X^-} = p(|W^+| - |W^-|)$ and variance $\Var{X^+ - X^-} = p(1 - p)|W|$, at the cost of an error
    \begin{equation*}
        C_0 \frac{p(1 - p)[p^2 + (1 - p)^2]|W|}{[p(1 - p)|W|]^{3/2}}
        \le \frac{2C_0}{\sqrt{pn}}.
    \end{equation*}
    We have, by regularity of $U$,
    \begin{equation}  \label{eq:P(a_v)-proof-eps_u-crude}
    \begin{aligned}
        & \Pr(\bClr_1(u) = 1)
        = \Pr\left(
            X^+ - X^- + m_u \ge 0
        \right)
        = \Phi\left(
            \frac{m_u + p(|W^+| - |W^-|)}{\sqrt{p|W|}}
        \right)
        \pm \frac{2C_0}{\sqrt{pn}}
        \\
        & = \frac{1}{2}
        + O\left(
            \frac{m_u + p(|W^+| - |W^-|)}{\sqrt{p|W|}}
        \right)
        \pm \frac{2C_0}{\sqrt{pn}}
        =  \frac{1}{2}
        + O\left(
            \frac{\pm \log n \pm p\sqrt{pn\log n}}{\sqrt{pn}}
        \right)
        \pm \frac{2C_0}{\sqrt{pn}}
        \\
        & = \frac{1}{2} \pm O\left(\frac{\log n}{\sqrt{pn}}\right)
        \quad \implies \ 
        |\eps_u| = O\left(\frac{\log n}{\sqrt{pn}}\right).
    \end{aligned}
    \end{equation}
    This crude bound allows us to estimate $\Var{\bClr_1(v)}$ and the Berry-Esseen error in Eq. \eqref{eq:P(A_v)-proof-esseen1}.
    We have
    \begin{equation}  \label{eq:P(A_v)-proof-esseen1-var}
        \Var{\bClr_1(v)} = |U| - \sum_{u\in U}\eps_u^2
        = |U| \left(
            1 - O\left(\frac{\log^2 n}{pn}\right)
        \right).
    \end{equation}
    Recall that we are allowed $pn \ge C\log^2 n$ for a large enough $C$, so this bound is still meaningful.
    For the error term, temporarily let $\delta = (pn)^{-1/2}\log n$, we have
    \begin{equation}  \label{eq:P(A_v)-proof-esseen1-err}
        \frac{|U| - \sum_{u\in U}\eps_u^4}{
            \left( |U| - \sum_{u\in U}\eps_u^2 \right)^{3/2}
        }
        = \frac{|U|(1 - O(\delta^4))}{|U|^{3/2}(1 - O(\delta^2))^{3/2}}
        = O\left( \frac{1}{\sqrt{pn}} \right).
    \end{equation}
    We keep these bounds in mind for later use.


    Now let us estimate $\sum_{u\in U}\eps_u$ more carefully.
    We expect more cancellations than simply adding the crude bounds in Eq. \eqref{eq:P(a_v)-proof-eps_u-crude}.
    By \cite[Lemma 2.5]{jhk-etal2021}, we have
    \begin{equation*}
    \begin{aligned}
        & \sum_{u\in U} \Pr(\bClr_1(u) = 1)
        = \sum_{u\in U} \Pr\left(
            X^+ - X^- + m_u \ge 0
        \right)
        \\
        & = \sum_{u\in U} \left[
            \Pr(X^+ \ge X^-) + m_u\Pr(X^+ = X^-)
            \pm O\left(\frac{m_u^2}{p|W|}\right)
        \right]
        \\
        & = |U|\Pr(X^+ \ge X^-)
        + \Pr(X^+ = X^-)\sum_{u\in U}m_u
        \pm O\left(\frac{1}{pn}\sum_{u\in U}m_u^2\right).
    \end{aligned}
    \end{equation*}
    Let us simplify the above expression.
    We have
    \begin{equation*}
    \begin{aligned}
        \sum_{u\in U} m_u
        & = \sum_{u\in U} \left(d_{U^+}(u) - d_{U^-}(u)\right)
        + \bClr_0(v)|U| - |U^-|
        = \one_{|U|}^T\mathbf{d}_U
        + \bClr_0(v)|U| - |U^-|
        \\
        & = \bClr_0(v)|U| - \frac{|U|}{2} \pm 4\sqrt{pn\log n},
    \end{aligned}
    \end{equation*}
    where the last estimate is due to $U$ being regular.
    Next, also by regularity,
    \begin{equation*}
    \begin{aligned}
        \sum_{u\in U} m_u^2
        & \le 2\sum_{u\in U} \left[\left(d_{U^+}(u) - d_{U^-}(u)\right)^2 + 4\right]
        = \|\mathbf{d}_U\|_2^2 + 8|U|
        \le 10pn\log n.
    \end{aligned}
    \end{equation*}
    Therefore
    \begin{equation}  \label{eq:P(A_v)-proof-sum-eps_u-temp1}
    \begin{aligned}
        \sum_{u\in U} \Pr(\bClr_1(u) = 1)
        & = |U|\Pr(X^+ \ge X^-)
        + \Pr(X^+ = X^-) \left(
            \bClr_0(v)|U| - \frac{|U|}{2} \pm 4\sqrt{pn\log n}
            \right)
        \pm O(\log n)
        \\
        & = |U|\left(
            \Pr(X^+ \ge X^-) - \frac{\Pr(X^+ = X^-)}{2}
            + \bClr_0(v)\Pr(X^+ = X^-)
        \right)
        \pm O(\log n).
    \end{aligned}
    \end{equation}
    Ideally, we want the first term to simplify $|U|/2$, so that the sum on the left-hand side is close to $|U|/2$, meaning $\sum_{u\in U}\eps_u$ is close to $0$.
    This will work out if $X^+$ and $X^-$ have identical distributions.
    While this is not the case, we can replace them with i.i.d. random variables at some cost.

    Let $Z^+$ and $Z^-$ be two independent copies of $\Bin(n/2 - \lceil pn \rceil, p)$.
    By \cite[Corollary 2.8]{jhk-etal2021}, we can replace $X^\pm$ respectively with $Z^\pm$ in $\Pr(X^+\ge X^-)$ and $\Pr(X^+ = X^-)$ for an error of at most
    \begin{equation*}
        O\left(\frac{p\bigl(||W^+| - (n/2 - \lceil pn \rceil)| \vee ||W^-| - (n/2 - \lceil pn \rceil)|\bigr)}{\sqrt{pn}}\right)
        = O\left(\frac{p\sqrt{pn\log n}}{\sqrt{pn}} \right)
        = O(p\sqrt{\log n}).
    \end{equation*}
    %	Using Eq. \eqref{eq:|U|-cond}, we have $T = O(\sqrt{pn}\log n)$, so the error is $O(p\log n)$.
    Now by symmetry,
    $
    ~\Pr(Z^+\ge Z^-) - \frac{1}{2}\Pr(Z^+ = Z^-) = \frac{1}{2},
    $
    so Eq. \eqref{eq:P(A_v)-proof-sum-eps_u-temp1} becomes
    \begin{equation*}
    \begin{aligned}
        \sum_{u\in U} \Pr(\bClr_1(u) = 1)
        & = |U|\left[\frac{1}{2} \pm O(p\sqrt{\log n}) + \bClr_0(v)\Pr(Z^+ = Z^-)\right] \pm O(\log n) \\
        & = \frac{|U|}{2} + \bClr_0(v)|U|\Pr(Z^+ = Z^-) \pm O(p|U|\sqrt{\log n}) \pm O(\log n) \\
        & = \frac{|U|}{2} + \bClr_0(v)|U|\Pr(Z^+ = Z^-) \pm O\bigl(\log n\bigr),
    \end{aligned}
    \end{equation*}
    where we use the fact $p|U| = O(p^2n) = O(\sqrt{\log n})$.
    %	Recall that our goal is the expression $\sum_{u\in U_{13}}\eps_u$.
    Since $\eps_u = 2\Pr(\bClr_1(u) = 1) - 1$, we have
    \begin{equation}  \label{eq:P(A_v)-proof-sum-eps_v}
        \sum_{u\in U} \eps_u = 2\bClr_0(v)|U|\Pr(Z^+ = Z^-) \pm O\bigl(\log n\bigr).
    \end{equation}
    Note that the first term on the right-hand side is $\Theta(\sqrt{pn})$, so it is indeed the main term.

    Now we can finally estimate $\Pr(A_v)$.
    Plugging Eqs. \eqref{eq:P(A_v)-proof-esseen1-var}, \eqref{eq:P(A_v)-proof-esseen1-err}, \eqref{eq:P(A_v)-proof-sum-eps_v} into Eq. \eqref{eq:P(A_v)-proof-esseen1}, we get
    \begin{equation*}
        \Pr(A_v)
        = \Phi\left(
            \frac{
                D + 2\bClr_0(v)|U|\Pr(Z^+ = Z^-) \pm O\bigl(\log n\bigr)
            }{
                \sqrt{|U|(1 - O(\delta^2))}
            }
        \right)
        \pm O\left(\frac{1}{\sqrt{pn}}\right),
    \end{equation*}
    where $\delta = (pn)^{-1/2}\log n$ as previously defined.
    We analyze the term inside $\Phi(\cdot)$.
    By the regularity of $U$, $|U| = pn(1 \pm O(\delta))$, so we can write this term as
    \begin{equation}  \label{eq:P(A_v)-proof-esseen2}
    \begin{aligned}
        & \frac{D}{\sqrt{|U|(1 - O(\delta^2))}}
        + \frac{
            2\bClr_0(v)\Pr(Z^+ = Z^-)\sqrt{|U|}
        }{\sqrt{1 - O(\delta^2)}}
        \pm \frac{O(\sqrt{\log n})}{\sqrt{|U|(1 - O(\delta^2))}}
        \\
        & = \frac{D}{\sqrt{pn(1 \pm O(\delta))}}
        + 2\bClr_0(v)\Pr(Z^+ = Z^-)\sqrt{pn(1 \pm O(\delta))}
        \pm O\bigl(\delta^2\bigr)
        \\
        & = \frac{D}{\sqrt{pn}}
        + 2\bClr_0(v)\Pr(Z^+ = Z^-)\sqrt{pn}
        \pm O\left(
            \delta \left(
                \frac{D}{\sqrt{pn}} + \Pr(Z^+ = Z^-)\sqrt{pn} + \delta
            \right)
        \right).
    \end{aligned}
    \end{equation}
    Consider the error term.
    By the assumption $D \le 10\sqrt{pn}$, and the facts that $\Pr(Z^+ = Z^-) \le 4(pn)^{-1/2}$ and $\delta < .1$, this error term is just $O(\delta) = O((pn)^{-1/2}\log n)$.
    We get
    \begin{equation}  \label{eq:P(A_v)-proof-esseen3} 
        \Pr(A_v) = \Phi\left(
            \frac{D \pm O(\log n)}{\sqrt{pn}}
            + 2\bClr_0(v)\Pr(Z^+ = Z^-)\sqrt{pn}
        \right) \pm O\left( \frac{1}{\sqrt{pn}} \right).
    \end{equation}

    By allowing $D \ge C\log n$ for a sufficient constant $C$, we have
    $D\pm O(\log n) \ge D/2$.
    % \begin{equation*}
    %     \frac{D}{\sqrt{pn}} \pm O\left(\frac{\log n}{\sqrt{pn}}\right)
    %     \ge \frac{D}{2\sqrt{pn}}.
    % \end{equation*}
    Eq. \eqref{eq:P(A_v)-proof-esseen3} then implies
    \begin{equation*}
        P(A_v) = \Phi\left(
            \frac{D}{2\sqrt{pn}}
            + 2\bClr_0(v)\Pr(Z^+ = Z^-)\sqrt{pn}
        \right)
        % \pm O\left(\delta\right)
        \pm O\left(\frac{1}{\sqrt{pn}}\right),
    \end{equation*}
    which is the desired expression.
    We are not done yet, since this is actually $\Pr(A_v \mid U = N(v), H = G(U))$ for the fixed regular pair $(U, H)$ that we have been using.
    However, since the total probability of irregular pairs is $O(n^{-2})$, which gets absorbed by the error term $O((pn)^{-1/2})$ above, this does not affect $\Pr(A_v)$ in the general case.
    The proof is complete.
\end{proof}






\subsubsection{Step 2: Upper bounding $\Var{|A|}$}



Below is the main claim

\begin{claim}  \label{claim:almost-pos-set-var} 
    Let $A$ be the set of $D$-almost positive vertices.
    Let $B > 0$ be an arbitrary constant.
    There are universal constants $C_1$, $C_2$ (large enough) such that if $pn \ge C_1\log^2 n$ and $B\sqrt{pn} \ge D \ge C_2\log n$, then
    \begin{equation*}
        \Var{|A|} = O\left(\frac{n\log^2 n}{p} \right).
    \end{equation*}
\end{claim}


The key idea is to write
\begin{equation*}
    \Var{|A|} = \sum_{v\in V} \Var{\one_{A_v}} + \sum_{v_1\neq v_2}\Cov{\one_{A_{v_1}}, \one_{A_{v_2}}}
\end{equation*}
Since the first part is at most $n/4$, it suffices to consider the covariances.
Fix a distinct pair $v_1, v_2\in V$, we have the claim


\begin{claim}  \label{claim:Cov(A_v1, A_v2)}
    Under the settings of Claim \ref{claim:almost-pos-set-var}, we have
    \begin{equation*}
        \left| \Cov{\one_{A_{v_1}}, \one_{A_{v_2}}} \right|
        = O\left( \frac{\log^2 n}{pn} \right).
    \end{equation*}
\end{claim}


Suppose this holds, we can prove Claim \ref{claim:almost-pos-set-var}.
\begin{proof}[Proof of Claim \ref{claim:almost-pos-set-var}]
    By the decomposition above, we have
    \begin{equation*}
        \Var{|A|} \le \frac{n}{4} + \binom{n}{2} \cdot
        O\left( \frac{\log^2 n}{pn} \right)
        = O\left( \frac{n\log^2 n}{p} \right).
    \end{equation*}
    The proof is complete.
\end{proof}


Now we move to the main technical challenge.
Similarly to the proof of Claim \ref{claim:P(A_v)}, we want to prove Claim \ref{claim:Cov(A_v1, A_v2)} in an ``ideal'' environment, namely where the statistics of $N(v_1)$ and $N(v_2)$ are close to their expectations.


This time we want to expose everything inside both $N(v_1)$ and $N(v_2)$.
Fix $U\subset V$ with partition $U = U_1 \cup U_2 \cup U_3$ and a subgraph $H$ over $U$, and condition $G$ on the events $U_1 = N(v_1) \setminus N(v_2)$, $U_2 = N(v_2) \setminus N(v_2)$, $U_3 = N(v_1) \cap N(v_2)$ (all excluding $v_1$ and $v_2$) and $H = G(U)$.


We introduce some extra notation:
\begin{itemize}
    \item $U_{13} \defeq U_1 \cup U_3 = N(v_1) \setminus \{v_2\}$ and $U_{23} \defeq U_2 \cup U_3 = N(v_2) \setminus \{v_2\}$ in our conditioned space.

    \item $U^+ \defeq U\cap \bR_0$ and $U^- \defeq U\cap \bB_0$.
    Define the same ``Red'' and ``Blue'' versions for the sets defined above.

    \item $W = (V\setminus \{v_1, v_2\}) \setminus U$.
    Define $W^+$ and $W^-$ similarly to the above.

    \item $V^+ = U^+ \cup W^+$ and $V^- = U^- \cup W^-$.

    \item The tuple $(U_1, U_2, U_3, H)$ is \emph{regular} if the following conditions hold.
    \begin{equation*}
    \begin{aligned}
        |U_{13}^+|, |U_{13}^-|, |U_{23}^+|, |U_{23}^-| = \frac{pn}{2} \pm 3\sqrt{pn\log n}, \quad
		|U_3^+|, |U_3^-| \le \log n,
        \\
        \|\mathbf{d}_U\|_\infty \le \log n,
        \quad
        \|\mathbf{d}_U\|_2 \le 3\sqrt{pn\log n},
        \quad
        \left| \one_{|U_{13}}^T \mathbf{d}_{U_{13}} \right|
        \vee \left| \one_{|U_{23}}^T \mathbf{d}_{U_{23}} \right|
        \le 5\log n,
        % \\
  %       |E(U_{13}^+)| - |E(U_{13}^-)|,
  %       \quad
		% |E(U_2^+, U_{13})| - |E(U_2^-, U_{13})|
		% = \pm 10\sqrt{pn}\log n,      
    \end{aligned}
    \end{equation*}
    where $\mathbf{d}_U = [d_{U^+}(u, H) - d_{U^-}(u, H)]_{u\in U} \in \R^{|U|}$ is the previously defined vector
    and $\mathbf{d}_{U_{13}} \in \R^{|U_{13}|}$ and $\mathbf{d}_{U_{23}} \in \R^{|U_{23}|}$ are its restrictions to $U_{13}$ and $U_{23}$ respectively.
	% and $G_U$, the subgraph of $G$ consisting of all edges inside $U$, satisfies:
	% \begin{equation}  \label{eq:d_U(u)-cond}
	% 	\begin{aligned}
	% 		\max_{u\in V}\ \bigl|d_{U^+}(u) - d_{U^-}(u)\bigr| \le \log n, \\
	% 		\sum_{u\in U}(d_{U^+}(u) - d_{U^-}(u))^2 \le C_{\eqref{eq:d_U(u)-cond}}pn\log n
	% 		\text{ for some universal constant } C_{\eqref{eq:d_U(u)-cond}}, 
	% 	\end{aligned}
	% \end{equation}
	% \begin{equation}  \label{eq:U-edges-cond}
	% 	|E(U_{13}^+)| - |E(U_{13}^-)|, \quad
	% 	|E(U_2^+, U_{13})| - |E(U_2^-, U_{13})|
	% 	= \pm 10\sqrt{pn}\log n. 
	% \end{equation}
\end{itemize}


Again, simple Chernoff bounds show that $U_1, U_2, U_3$ and $H$ are regular with probability $1 - O(n^{-2})$.
Now we can proceed to the formal proof.


\begin{proof}[Proof of Claim \ref{claim:Cov(A_v1, A_v2)}]
    Let $h_i = \E{\one_{A_{v_i}}}$ without any conditioning.
    Fix disjoint $U_1, U_2, U_3$ and subgraph $H$ over $U = U_1 \cup U_2 \cup U_3$ such that they are regular.
    Condition $G$ on the events $(N(v_1) \setminus \{v_2\}) \setminus N(v_2) = U_1$, 
    $(N(v_2) \setminus \{v_1\}) \setminus N(v_1) = U_2$,
    $(N(v_1) \setminus \{v_2\}) \cap (N(v_2) \setminus \{v_1\}) = U_3$,
    and $H = G(U)$.
    The covariance on this conditioned probability is off from the real covariance by an error of just $O(n^{-2})$.
    Until noted otherwise, we omit the events from the probability.

    We first rewrite the covariance as
    \begin{equation}  \label{eq:Cov(A_v1, A_v2)-proof-cov1}
        \Cov{\one_{A_{v_1}}, \one_{A_{v_2}}}
        = \E{(\one_{A_{v_1}} - h_1)(\one_{A_{v_2}} - h_2)}
    \end{equation}
    We want to split this into a product, but $A_{v_1}$ and $A_{v_2}$ are not independent.
    However, their only shared dependency is on the first day colors of their joint neighbors, $U_3$.

    Fix a set of first day colors $\{j_u\}_{u\in U_3}$ for these vertices.
    Condition the space further on the event $\mathcal{J} \defeq \{\forall u\in U_3, \ \bClr_1(u) = j_u\}$.
    This does not affect $\bClr_1(u)$ for the other $u\in U$ as they are all independent.
    We can rewrite the conditioned Eq. \eqref{eq:Cov(A_v1, A_v2)-proof-cov1} as
    \begin{equation*}
        \Cov{\one_{A_{v_1}}, \one_{A_{v_2}} \mid \mathcal{J}}
        = \left(
            \E{\one_{A_{v_1}} \mid \mathcal{J}} - h_1
        \right)
        \cdot \left(
            \E{\one_{A_{v_2}} \mid \mathcal{J}} - h_2
        \right).
    \end{equation*}
    Consider the factor $\E{\one_{A_{v_1}} \mid \mathcal{J}} - h_1$.
    Let $H_1(\mathcal{J}) = \E{\one_{A_{v_1}} \mid \mathcal{J}}$ for convenience.
    Let  $j \defeq \sum_{u\in U_3} j_u$.
    Reuse the computation leading Eq. \eqref{eq:P(A_v)-proof-esseen1} to get
    \begin{equation}  \label{eq:Cov(A_v1, A_v2)-proof-j-esseen1}
        H_1(\mathcal{J})
        = \Phi\left(
            \frac{
                D + \bClr_1(v_2)\one_{v_1\adj v_2}
                +  j + \sum_{u\in U_1} \eps_u
            }{
                (|U_1| - \sum_{u\in U_1}\eps_u^2)^{1/2}
            }
        \right)
        \pm O\left(
            \frac{
                |U_1| - \sum_{u\in U_1}\eps_u^4
            }{
                (|U_1| - \sum_{u\in U_1}\eps_u^2)^{3/2}
            }
        \right).
    \end{equation}
    In this space conditioned on $\mathcal{J}$, the variables $\eps_u = \E{\bClr_1(u)}$ for $u\in U_1$ are not affected since they are independent from $\{\bClr_1(u)\}_{u\in U_3}$.
    Note that this expression only depends on $j$ rather the specific values in $\{\bClr_1(u)\}_{u\in U_3}$.


    Fix another set of colors $\{k_u\}_{u\in U_3}$ and consider the event $\mathcal{K} = \{\forall u\in U_3, \ \bClr_1(u) = k_u\}$.
    Define $H_1(\mathcal{K})$ analogously to $H_1(\mathcal{J})$.
    The expression for $H_1(\mathcal{K})$ is almost identical to Eq. \eqref{eq:Cov(A_v1, A_v2)-proof-j-esseen1}, with $k = \sum_{u\in U_3} k_u$ replacing $j$.
    We then have
    \begin{equation}  \label{eq:Cov(A_v1, A_v2)-proof-j-k-diff}
        \left| H_1(\mathcal{J}) - H_1(\mathcal{K}) \right|
        = O\left( \frac{|j - k|}{(|U| - \sum_{u\in U_1}\eps_u^2)^{1/2}}
        \right)
        = O\left( \frac{|U_3|}{\sqrt{pn}}
        \right)
        = O\left( \frac{\log n}{\sqrt{pn}}
        \right),
    \end{equation}
    where the last two bounds are due to regularity and the analysis of $\eps_u$ in Eq. \eqref{eq:P(a_v)-proof-eps_u-crude}.


    This is an innovation from the proof in \cite{jhk-etal2021}.
    This allows us to indirectly analyze $H_1(\mathcal{J}) - h_1$ without directly computing $H_1(\mathcal{J})$.
    By showing that this expression does not change much when $\mathcal{J}$ changes, $H_1(\mathcal{J}) = \Pr(A_{v_1} \mid \mathcal{J})$ must be close to the same probability without conditioning on $\mathcal{J}$.

    Let $H_1 \defeq \Pr(A_{v_1} \mid U_1, U_2, U_3, H)$ (we write the background events explicitly here to differentiate this with $h_1$, which is $\Pr(A_{v_1})$ without any condition).
    We have, by Eq. \eqref{eq:Cov(A_v1, A_v2)-proof-j-k-diff},
    \begin{equation}  \label{eq:Cov(A_v1, A_v2)-proof-H_1(j)-H_1-diff}
        \left| H_1(\mathcal{J}) - H_1 \right|
        = O\left( \frac{\log n}{\sqrt{pn}} \right),
    \end{equation}

    We are halfway through bounding $H_1(\mathcal{J}) - h_1$.
    It remains to bound $H_1 - h_1$.
    The idea is not too different from the previous step.
    We write $H_1 = H_1(U_1, U_2, U_3, H)$, since we will look at the same variable conditioned on another regular tuple.
    First off, by almost analogous calculations to the steps leading up Eq. \eqref{eq:P(A_v)-proof-esseen3} in Section \ref{sec:almost-pos-set-exp}, we have
    \begin{equation*}
        H_1(U_1, U_2, U_3, H)
        = \Phi\left(
            \frac{D \pm O(\log n)}{\sqrt{pn}}
            + 2\bClr_0(v_1)\Pr(Z^+ = Z^-)\sqrt{pn}
        \right) \pm O\left( \frac{1}{\sqrt{pn}} \right).
    \end{equation*}
    Now fix another regular tuple $(U'_1, U'_2, U'_3, H')$.
    The same calculation applies, so we are left with
    \begin{equation*}
        \left| H_1(U_1, U_2, U_3, H)
        - H_1(U'_1, U'_2, U'_3, H') \right|
        = O\left( \frac{\log n}{\sqrt{pn}} \right).
    \end{equation*}
    The weights of the irregular tuples are just $O(n^{-2})$, which is asorbed by the error bound above, so we have
    \begin{equation}  \label{eq:Cov(A_v1, A_v2)-proof-H_1-h_1-diff}
        \left| H_1(U_1, U_2, U_3, H) - h_1 \right|
        = O\left( \frac{\log n}{\sqrt{pn}} \right).
    \end{equation}

    Back the to probability space conditioned on $(U_1, U_2, U_3, H)$.
    Now we can finally bound $H_1 - h_1$.
    Combining Eqs. \eqref{eq:Cov(A_v1, A_v2)-proof-H_1(j)-H_1-diff} and \eqref{eq:Cov(A_v1, A_v2)-proof-H_1-h_1-diff}, we get
    \begin{equation*}
        \left| H_1 - h_1 \right| = O\left( \frac{\log n}{\sqrt{pn}} \right).
    \end{equation*}
    An analogous calculation gives the same bound for $H_2 - h_2$.
    This implies
    \begin{equation*}
        \left| 
            \Cov{\one_{A_{v_1}}, \one_{A_{v_2}} \mid U_1, U_2, U_3, H}
        \right|
        = O\left( \frac{\log^2 n}{pn} \right).
    \end{equation*}
    The proof is complete, since the total weight of the irregular cases is $O(n^{-2})$, which is absorbed.
\end{proof}




\subsubsection{Proof of Lemma \ref{lem:almost-pos-v}}


Recall that $|A|$ is being used to denote the set of $D$-almost positive vertices.
Let us recall the main claims about $|A|$ from the previous two steps.
Suppose $pn \ge C_1\log^2 n$ and $B\sqrt{pn} \ge D \ge C_2\log n$ for arbitrary $B > 0$ and sufficient constants $C_1$ and $C_2$ that make Claims \ref{claim:almost-pos-set-exp} and \ref{claim:almost-pos-set-var} hold, we have
\begin{equation*}
    \E{|A|} \ge \frac{n}{2} + 2c_BD\sqrt{\frac{n}{p}}
    \ \text{ and } \
    \sqrt{\Var{|A|}} \le C\log n\sqrt{\frac{n}{p}},
\end{equation*}
for constants $c_B > 0$ (small enough) only depending on $B$ and universal $C > 0$ (large enough).


\begin{proof}[Proof of Lemma \ref{lem:almost-pos-v}]
    We continue from the argument above.
    By Chebyshev's inequality,
    \begin{equation*}
        \Pr\left(|A| \le \frac{n}{2} + c_BD\sqrt{\frac{n}{p}} \right)
        \le \frac{\Var{|A|}}{(c_BD\sqrt{n/p})^2}
        \le \frac{C^2\log^2 n}{c_B^2D^2} = O_B\left(\frac{\log^2 n}{D^2} \right).
    \end{equation*}
    The proof is complete.
\end{proof}





