\section{Preliminaries bounds on binomial random variables}  \label{sec:binom-bound}

In this section we describe several useful inequalities to bound binomial random variables.
The first one is the usual Chernoff bound \cite{hoeffding1963}.

\begin{theorem}[Chernoff bound]  \label{thm:chernoff}
	Let $X\sim \Bin(n, p)$, and $\eps > 0$. We have
	\begin{equation*}
		\begin{aligned}
			\Pr\left(X \ge (p + \eps)n\right) \le e^{-D(p + \eps \| p)n} & \quad \text{ if } \eps < 1 - p, \\
			\Pr\left(X \le (p - \eps)n\right) \le e^{-D(p - \eps \| p)n} & \quad \text{ if } \eps < p,
		\end{aligned}
	\end{equation*}
	where $D(x \| y) \defeq x\log\dfrac{x}{y} + (1 - x)\log\dfrac{1 - x}{1 - y}$ for $x, y\in (0, 1)$.
\end{theorem}

In this paper, we mainly use the following corollary of the Chernoff bound:

\begin{corollary}  \label{cor:chernoff}
	Let $X\sim \Bin(n, p)$ and $t > 0$. We have
	\begin{equation*}
		\Pr\left(X = pn \pm t\sqrt{pn}\right) \ge 1 - 2\exp\left(-\frac{t^2}{2(1 + \frac{t}{3\sqrt{pn}})} \right).
	\end{equation*}
\end{corollary}

\begin{proof}
	Let $\eps = tp^{1/2}n^{-1/2}$, so that $pn + t\sqrt{pn} = (p + \eps)n$.
	If $\eps \ge 1 - p$, the inequality trivially holds.
	If $\eps < 1 - p$, we have by Theorem \ref{thm:chernoff}:
	\begin{equation}  \label{eq:chernoff-temp1}
		\Pr(X > pn + t\sqrt{pn}) \le \exp\left[-D\Bigl(p + t\frac{\sqrt{p}}{\sqrt{n}} ~\Big\|~ p\Bigr)n\right].
	\end{equation}
	It is a well-known inequality that $D(x \| y) \ge 3(x - y)^2(2x + 4y)^{-1}$ for each $x, y \ge 0$.
	Thus
	\begin{equation*}
		D\Bigl(p + t\frac{\sqrt{p}}{\sqrt{n}} ~\Big\|~ p\Bigr)n
		\ge \frac{3\bigl(tp^{1/2}n^{-1/2}\bigr)^2}{2(3p + tp^{1/2}n^{-1/2})}n
		= \frac{t^2}{2(1 + \frac{t}{3\sqrt{pn}})}.
	\end{equation*}
	Plugging in Eq. \eqref{eq:chernoff-temp1}, we get the desired bound.

	Consider the event $X < pn - t\sqrt{pn} = (p - \eps)n$.
	If $\eps \ge p$, the inequality trivially holds.
	If $\eps < p$, i.e. $t < \sqrt{pn}$, we have by Theorem \ref{thm:chernoff}:
	\begin{equation}  \label{eq:chernoff-temp2}
		\Pr(X < pn - t\sqrt{pn}) \le \exp\left[-D\Bigl(p - t\frac{\sqrt{p}}{\sqrt{n}} ~\Big\|~ p\Bigr)n\right].
	\end{equation}
	We have
	\begin{equation*}
		D\Bigl(p - t\frac{\sqrt{p}}{\sqrt{n}} ~\Big\|~ p\Bigr)n
		\ge \frac{3\bigl(tp^{1/2}n^{-1/2}\bigr)^2}{2(3p - tp^{1/2}n^{-1/2})}n
		= \frac{t^2}{2(1 - \frac{t}{3\sqrt{pn}})}
		\ge \frac{t^2}{2(1 + \frac{t}{3\sqrt{pn}})},
	\end{equation*}
	where the last inequality is due to $0 < t < \sqrt{pn}$.
	Plugging in Eq. \eqref{eq:chernoff-temp2}, we get the desired bound.
\end{proof}




We quickly record another bound useful for binomial variables with small expectations:
\begin{lemma}  \label{lem:poisson-bound}
	For any $X\sim \Bin(n, p)$ and $t \ge epn$, we have:
	$ \Pr(X > t) \le 2\left(\frac{epn}{t}\right)^t
	$.
\end{lemma}

\begin{proof}
	For each integer $k\in [0, n]$,
	$ \Pr(X = k) = \binom{n}{k}p^k(1 - p)^{n - k} \le \frac{n^k}{k!}p^k $.
	Let $k = \lceil t \rceil$, we have
	\begin{equation*}
		\begin{aligned}
			\Pr(X > t)
			& \le \sum_{l=k}^\infty \frac{(pn)^l}{l!}
			= \frac{(pn)^k}{k!} \sum_{i=0}^\infty \frac{(pn)^i}{(i + k)(i + k - 1)\ldots (k + 1)}
			\le \frac{(pn)^k}{k!}  \sum_{i=0}^\infty \frac{(pn)^i}{(k + 1)^i} \\
			& = \frac{(pn)^k}{k!} \sum_{i=0}^\infty e^{-i} < 2\frac{(pn)^k}{k!}
			< 2\left(\frac{epn}{k}\right)^k < 2\left(\frac{epn}{t}\right)^t,
		\end{aligned}
	\end{equation*}
	where the second to last inequality is the usual Stirling bound \cite{stirling}, and the last is due to decreasing property of the expression $(a/t)^t$ for $t \ge a$.
\end{proof}


