    \centering
    \includegraphics[scale=0.4]{Patch_Slot.pdf}
    \caption{Slotted patch antenna @ 2.45GHz. \textit{PatchW} = 38, \textit{PatchL} = 28, \textit{SlotW} = 2, \textit{SlotL} = 10. (unit: mm.)}
    \label{fig:Patch}
\end{figure}

\begin{figure}[h]
