\section{Preliminary}
\subsection{Lyapunov Stability}
We consider the problem of constructing Lyapunov functions for autonomous nonlinear dynamical systems at an equilibrium point. Without loss of generality, we assume the equilibrium point is the origin. 
\begin{definition}[Dynamical systems]
\label{def:dynamical system}
An n-dimensional autonomous nonlinear dynamical system is defined as 
\begin{equation}\label{eq:nonlinear_dynamics}
    \frac{dx}{dt}=f(x)\,,x(0)=x_0,
\end{equation}
where $f:\mathcal{D}\to \mathbb{R}^n$ is a Lipschitz-continuous vector field, and $\mathcal{D}\subseteq \mathbb{R}^n$ is an open set containing the origin that defines the state space. Each $x(t)\in\mathcal{D}$ is a state vector. 
\end{definition}

\begin{definition}[Asymptotic stability]
    \label{def:asm_stb}
    The origin of system \eqref{eq:nonlinear_dynamics} is stabilized if for any $\epsilon>0$, there exists $\delta(\epsilon)>0$ such that $\lVert x(t)\rVert<\epsilon$, $\forall t\geq 0$
    if $\lVert x(0)\rVert<\delta$. The origin is asymptotically stable if it is stable and $\delta$ can be chosen such that $\lVert x(0)\rVert <\delta \implies \lim\limits_{t \to \infty}x(t)=0$ \cite{khalil2002nonlinear}.%[Definition 4.1].
\end{definition}
\begin{definition}[Lie derivative] The Lie derivative of a continuously differentiable scalar function $V:\mathcal{D}\to\mathbb{R}$ along the trajectory of \eqref{eq:nonlinear_dynamics} is 
\begin{equation}
    \label{eq:Lie}
    L_f V(x)=\sum_{i=1}^n\frac{\partial V}{\partial x_i}\frac{dx_i}{dt}=\sum_{i=1}^n\frac{\partial V}{\partial x_i}f_i(x).
\end{equation}
\end{definition}

\begin{proposition}[Lyapunov functions for asymptotic stability]\label{pro:lyap} Let $0$ be an equilibrium point for \eqref{eq:nonlinear_dynamics} and $\mathcal{D}\subseteq\mathbb{R}^n$ be a domain containing the origin. Let $V:\mathcal{D}\to\mathbb{R}$ be a continuously differentiable function such that
\begin{subequations}
    \begin{align}
        &V(0)=0 \text{ and } V(x)>0 \text{ in } D\backslash\{0\}\label{eq:Lyapunov},\\ 
        &L_f V(x)\leq 0 \text{ in } D.
    \end{align}
\end{subequations}
Then, $x=0$ is stable. Moreover, if 
\begin{equation}\label{eq:decrease}
    L_f V(x)< 0\text{ in } D\backslash \{0\},
\end{equation}
then the origin is asymptotically stable.
\end{proposition}
