\section{Learning a MIC model}%
 \label{sec_inference}

%
\MIC proposes the addition of $\Nc^2$ parameters to capture pairwise cascade interactions (see \Sec{sec:model-def}). %
Here, our intention is show that those parameters can be efficiently learned by a comprehensive Maximum Likelihood Estimation (MLE) approach, which at the same time is not complex. %
Moreover, when the likelihood can be factorized into a product of user likelihoods, then thanks to the partial log-likelihood formulas, these optimization sub-problems can be solved in parallel. %
Although developing a highly competitive optimization scheme is not in the scope of this paper, in the literature there are works dedicated to parameter inference for Hawkes processes, which use methods such as kernel decomposition \cite{zhouLearningTriggeringKernels2013,lemonnierMultivariateHawkesProcesses2017,isikFlexibleTriggeringKernels2022} or Bayesian approaches \cite{zhangEfficientNonparametricBayesian2022,nayakSmartInformationSpreading2019}.



\subsection{Computation of the log-likelihood}

First, using the formulation introduced by \cite{aalenSurvivalEventHistory2008}, for a MMHP and given the model parameters $\mathbf{\Theta}$, the conditional density function %
for the event $e_i=(u_i,c_i,t_i)$ to occur at $t_i$, combined with no other event to occur before $t_{i+1}$, is written as:
%
\begin{equation}\label{eq:cond_intensity}
 l(e_i,t_{i+1} ; \mathbf{\Theta}) =
	%
	\lambda_{u_i}^{(c_i)}(t_i)%
	\ \mathbb{P}(\text{no event in}\ (t_i,t_{i+1}])),
\end{equation}
%
where $\lambda_{u_i}^{(c_i)}(t_i)$ is the rate of occurrence of event $e_i$. %
The probability of \Eq{eq:cond_intensity} is known as \emph{exponential survival function}, which we write here for an arbitrary time interval $(t,t']$ as: %
\begin{align}\label{eq:survival-function}
 \begin{split}
	\SF{t}{t'} & := \mathbb{P}(\text{no event in}\ (t,t'])) = \exp\bigg(\!\!-\int_{t}^{t'}\!\!\! \sum_{u\in \mathcal V}\lambda_{u}(\tau) d\tau\bigg)\\
	& = \exp\bigg(\!\!- \sum_{u\in \mathcal V}\bigg[ (t'\!-t) \mu_{u}+ \sum_{v \in \mathcal F_u}\sum_{e_j \in \mathcal{H}_{v}(t,t')} \!\!\!\!\weight_{vu} K (t,t'\!-t_j)\bigg]\bigg)\!,%
 \end{split}
\end{align}
%
where $K(t,t'-t_j) = \int_t^{t-t_j}\kappa (\tau) d\tau$, with $t<t_j\leq t'$ and $\kappa(\cdot)$ the exponential kernel.

Next, we express \MIC's full observation likelihood of the whole event history $\mathcal{H} = \{e_i = (u_i,t_i,c_i)\}_{i=1}^{N_e}$ %
as:
%
\begin{align}\label{eq:full-likelihood}
 \begin{split}
  \!\!\!\!\!\!L (\mathcal H ; \mathbf{\Theta}) &= \prod_{e_i \in \mathcal{H}} l(e_i,t_{i+1} ; \mathbf{\Theta}) %
	= \prod_{e_i \in \mathcal{H}} \left[\lambda_{u_i}^{(c_i)}(t_i) \ \SF{t_i}{t_{i+1}} \right]\\
  &= \bigg[ \prod_{e_i \in \mathcal{H}} \lambda_{u_i}^{(c_i)}(t_i) \bigg]
	%
	\, \SF{0}{T},
 \end{split}
\end{align}
%
where $\prod_{e_i \in \mathcal{H}} \SF{t_i}{t_{i+1}} = \SF{0}{T}$, given \Eq{eq:survival-function}. As mentioned earlier, the full likelihood can be factorized by the partial likelihoods for each user $u$ as: $L (\mathcal H ; \mathbf{\Theta}) = \prod_{u\in \mathcal{V}} L_u (\mathcal H ; \mathbf{\Theta})$, where, using the marked user intensity of \Eq{eq:marked-intensity-u}, we can write:
%
\begin{align}
 \begin{split}
  \!\!\!\!\!\!\!\!\!\!\!L_u (\mathcal H ; \mathbf{\Theta}) &=
		\bigg[\prod_{e_i \in \mathcal{H}_u} \!\!\lambda_u^{(c_i)}(t_i) \bigg] \, \SF{0}{T} \\
   &= \bigg[\prod_{e_i \in \mathcal{H}_u} \!\!\lambda_u(t_i) f_u(c_i \vbar t_i) \bigg]
		%
		\ \SF{0}{T}.\!\!\!\!
 \end{split}
\end{align}
%
Next step is to give the expression for the log-likelihood:
%
\begin{allowdisplaybreaks}
\begin{align}\label{eq:loglikelihood}
 \begin{split}
  \mathcal{L}(\mathcal H ; \mathbf{\Theta}) &= \bigg[\sum_{e_i \in \mathcal{H}} \log(\lambda_{u_i}(t_i) f_{u_i}(c_i \vbar t_i)) \bigg] %
+ \LogSF{0}{T}%
		\\
   &= \bigg[\sum_{e_i \in \mathcal{H}}\log(\lambda_{u_i}(t_i)) + \beta\nu_{u_i}^{*(c_i)}(t_i) \\
  & \ \ \ \ \ \ \ - \sum_{e_i \in \mathcal{H}}\log \bigg(\sum_{s\in \mathcal C} \exp \Big( \beta \nu_{u_i}^{*(s)}(t_i)\Big) \bigg) \bigg]\\
  & \ \ \ \ %
		+ \LogSF{0}{T}%
		\\
   &= \bigg[\sum_{e_i \in \mathcal{H}} \log(\lambda_{u_i}(t_i)) + \beta \nu_{u_i}^{*(c_i)}(t_i) \\
  & \ \ \ \ \ \ \ - \sum_{e_i \in \mathcal{H}}\log \left(Z_{u_i}(t_i) \right)\bigg]\\
  & \ \ \ \  - \sum_{u\in \mathcal V}\bigg[ T\mu_{u} + \sum_{v \in \mathcal F_u}\sum_{e_j \in \mathcal{H}_{v}} \weight_{vu}
		%
		K (0,T-t_j)
		\bigg],
 \end{split}
\end{align}
\end{allowdisplaybreaks}%
where %
$Z_{u_i}(t_i)$ is the partition function defined in \Sec{sec:model-def}.
The partial log-likelihood is therefore expressed as follows:
%
\begin{align}\label{eq:partial_loglikelihood}
 \begin{split}
  \mathcal{L}_u(\mathcal H_u ; \mathbf{\Theta}) &= \bigg[\sum_{e_i \in \mathcal{H}_u} \log(\lambda_{u}(t_i)) + \beta \nu_{u}^{*(c_i)}(t_i)\bigg]\\
   & \ \ \ \  - \sum_{e_i \in \mathcal{H}_u}\log (Z_{u_i}(t_i) )\\
   & \ \ \ \  - T \mu_{u} - \sum_{v \in \mathcal F_u}\sum_{e_j \in \mathcal{H}_{v}} \weight_{vu}
			%
			K (0,T-t_j).
 \end{split}
 \end{align}
%
\noindent \textbf{Proposition 1}: The negative log-likelihood $\mathcal{L}$ is a convex function of the parameters $\mathbf{\Theta}$.
%
\begin{proof} The convexity of the negative partial log-likelihood is a direct consequence of the convexity of the $\operatorname{Log Sum Exp}$ function $\varphi:\mathbb R^{\Nc} \to \mathbb R$ \cite{boydConvexOptimization2004}, defined as:
%
\begin{equation}
  \varphi(\mathbf{z_i}) = \log \bigg(\sum_{s=1}^{\Nc} \exp(z_i^{(s)})\bigg),
\end{equation}
%
where $\forall s \in \mathcal{C}$, $z_i^{(s)} = \beta \nu_{u_i}^{*(s)}(t_i)$. For \MIC, the set of parameters $\mathbf{\Theta} = \left( \mathbf{M} , \mathbf{\Sigma}, \mathbf{\Weight} \right)$ are positive, ensuring the preservation of convexity. Similarly, the other terms of the negative log-likelihood are convex functions of the parameters, which proves the overall convexity of $\mathcal{L}_u$, and subsequently of $\mathcal{L}$. In the case of linear mixing, in \Eq{eq:full-likelihood} we replace $\lambda_{u_i}^{(c_i)}(t_i)$ by $\nu_{u_i}^{(c_i)}(t_i)$ and we perform the same reasoning, which also leads to a convex formulation of the log-likelihood.
\end{proof}

\subsection{Parameter inference algorithm}\label{sec:par-inferrence}

Relying on the expression of the partial and total log-likelihood (\Eq{eq:loglikelihood} and \Eq{eq:partial_loglikelihood}) we decompose the parameter inference scheme into two optimization steps, presented in \Alg{alg:optimize_theta}. \Problem{eq:probSigma} uses Maximum Likelihood Estimation (MLE) to find the cascade interaction matrix $\mathbf{\Sigma} =\left[\sigma_{cs}\right]_{cs}$ by minimizing $-\mathcal{L}(\mathcal{H} ; \mathbf{\Theta})$, with $(\mathbf{M},\mathbf{\Weight})$ fixed.
For this, we use Newton's method to approximate $\mathbf{\Sigma}$ for when the respective gradient is zero, $\mathbf{\nabla}_{\Sigma} \mathcal{L} = 0$.
Then, \Problem{eq:probMB} uses Maximum Partial Likelihood Estimation (MPLE) to find the user parameters $\mathbf{M}_u = (\mu_u^{(c)})_c$ and $\mathbf{\Weight}_u = (\weight_{vu})_{v}$, with $\mathbf{\Sigma}$ fixed. Due to the per-user factorization of the log-likelihood, the $\Nu$ sub-problems can be solved numerically in parallel.

The two problems are treated by the alternating optimization scheme of \Alg{alg:optimize_theta} until convergence. Note that the hyperparameter $\beta$ is estimated by cross-validation. As in this work focuses on modeling the interplay of user and cascade interactions, we are mainly interested in showing that learning is feasible with a typical optimization scheme. In that sense, although our proposition employes alternating optimization, the rest of the inference scheme comes from the prior line of related work and up to \cite{zarezadeCorrelatedCascadesCompete2017}.


\begin{algorithm}[t]\small
 \caption{%
	Inference of \MIC parameters
	}\label{alg:optimize_theta}
	\hspace*{\algorithmicindent} \textbf{Input:}~history of train events $\mathcal{H}$, termination threshold $\epsilon$\\
 \hspace*{\algorithmicindent} \textbf{Output:}~the set of inferred parameters $\Tilde{\boldsymbol{\mathbf{\Theta}}} = (\Tilde{\mathbf{M}}, \Tilde{\mathbf{\Weight}}, \Tilde{\mathbf{\Sigma}})$%
 \vspace{0.05cm}%
	\hrule
	\vspace{0.05cm}%
	\begin{algorithmic}[1]
	%
	  \State Initialize $\mathbf{\Theta} = (\mathbf{M}, \mathbf{\Weight}, \mathbf{\Sigma})$

			 \State Let $\Tilde{\mathbf{\Theta}} = \mathbf{\Theta}$

   \Repeat

     \State \!\!\mySqBullet~Step~1 -- Underlying cascade interaction
     \State %
					\vspace{-.9em}%
					\begin{equation}\label{eq:probSigma}
						%
						\hspace{-7.2em}%
						\Tilde{\mathbf{\Sigma}} = {{\arg\min}_{\mathbf{\Sigma}}} -\mathcal{L}(\mathcal{H}; \mathbf{M}, \mathbf{\Weight})
					\vspace{-.6em}%
					\end{equation}
     %
					\hspace{1.65cm}%
					s.t. $\forall c,s \in \mathcal{C}, \sigma_{sc} \in [0,1]$ and $ \sum_c \sigma_{sc} = 1$

					\smallskip
     \State \!\!\mySqBullet~Step~2 -- Social influence and background intensity
     \State \ \ \ \textbf{for} $u \in \mathcal{V}$ \ \textbf{do in parallel}
       \State %
							\vspace{-.9em}%
							\begin{equation}\label{eq:probMB}
							\hspace{-3.5em}\Tilde{\mathbf{M}}_u, \Tilde{\mathbf{\Weight}}_u = {\arg\min}_{\mathbf{M}_u, \mathbf{\Weight}_u} -\mathcal{L}_u(\mathcal{H}; \Tilde{\mathbf{\Sigma}})
							\vspace{-.6em}%
							\end{equation}
							%
       \hspace{2.45cm} s.t. $\mathbf{M}_u, \mathbf{\Weight}_u \geq 0$

					\State \ \ \ \textbf{end for}

					\smallskip
					\State $\mathbf{\Theta} = \Tilde{\mathbf{\Theta}}$

			\Until{$\mathcal{L}(\mathbf{\Tilde{\Theta}}) - \mathcal{L}(\mathbf{\Tilde{\Theta}}) < \epsilon$}

			 \State \Return $\Tilde{\mathbf{\Theta}} = (\Tilde{\mathbf{M}}, \Tilde{\mathbf{\Weight}}, \Tilde{\mathbf{\Sigma}})$
 \end{algorithmic}
\end{algorithm}
%




\section{Analytic derivation of characteristic quantities %
}\label{sec:th_derivation}
%
In this section, we derive closed-form expressions for the conditional intensity and the number of events for the \MIC model. The derivation follows a rather simple method to obtain moments of Hawkes processes, based on \cite{cuiElementaryDerivationMoments2020}. These analytical results are compared and validated in \Sec{sec:experiments} with experiments both on synthetic (\Fig{fig:int_eve_grid_ex}) and real data (\Fig{fig:ints_url}).

\subsection{Generic derivation}

\textit{Step~1}:~Let us consider the %
quantity $\mathbb E\big[{n_v^{(s)}}^m(t){\nu_u^{(c)}}^q(t)\big]$, where $n_v^{(s)}(t)$ is the number of events of user $v$ for cascade $s$ and $\nu_u^{(c)}(t)$ is the independent intensity of user $u$ for cascade $c$, both at time $t$ and exponentiated by $m, q \in \mathbb{N}$.

%
\noindent\textit{Step~2}:~We calculate the probabilities of the absence or occurrence of an arbitrary event $e_i = (u_i,c_i,t_i)$ that is or is not associated to user $v$ and cascade $s$, at order $o(\Delta t$):
%
\begin{align}
 \begin{split}\label{eq:step2}
 &\mathbb P\left( \neg e_i \vbar \mathcal H_t \right) = 1-\Delta t\sum_{v\in \mathcal{V}} \sum_{p \in \mathcal{C}}\lambda_v^{(p)}(t) + o(\Delta t) \\
 &\mathbb P\left(e_i \neq (v,s,t_i) \vbar \mathcal H_t \right) =\Delta t \sum_{v \in \mathcal{V}} \sum_{\substack{p \in \mathcal{C}\\(v,p) \neq(v,s)}}\!\!\!\!\!\!\!\lambda_v^{(p)}(t) + o(\Delta t) \\
 &\mathbb P\left( e_i = (v,s,t_i) \vbar \mathcal H_t \right) = \Delta t \lambda_v^{(s)}(t) + o(\Delta t).
 \end{split}
\end{align}
%
\noindent
\textit{Step~3}:~We express the evolution of the independent cascade intensity at time $t+\Delta t$ given the absence and the occurrence of an event $e_i = (u_i,c_i,t_i)$:
When no event occurs:
%
\begin{align}
 \begin{split}\label{eq:step3a}
  \nu_{u,0}^{(c)}(t+\Delta t) &= \mu_u^{(c)} + \sum_{j\in \mathcal{F}_u}\weight_{vu} \sum_{e_j \in \mathcal{H}_u(t)} e^{-(t-t_j+\Delta t)/\tau}\\
  &= \nu_u^{(c)}(t) - \Delta t (\nu_u^{(c)}(t)-\mu_u^{(c)})/\tau + o(\Delta t),
 \end{split}
\end{align}
where $\tau$ controls the scale of the temporal kernel $\kappa$ (see \Sec{sec:bakground}).
When there is an event $(u_i,c_i,t_i)$ with $t<t_i<t+\Delta t$:
%
\begin{align}
 \begin{split}\label{eq:step3b}
  \!\!\!\!\!\!\nu_{u,e_i}^{(c)}(t+\Delta t) &= \nu_{u,0}^{(c)}(t+\Delta t) + \weight_{u_i u}\delta_{c_i,c}(1-\Delta t') + o(\Delta t')/\tau,\!\! \end{split}
\end{align}
where $\delta_{\cdot,\cdot}$ is the Kronecker %
delta function and $\Delta t' = t_i - t$ is the time passed after the occurrence of event $e_i$ (\ie $0<\Delta t'<\Delta t$). Here we extend the notation of influence: $\weight_{u_i u} = 0$ if $u_i \notin \mathcal{F}_u$.

\noindent\textit{Step~4}:~We calculate and simplify the conditional expectation $h(t+\Delta t) = \mathbb E[n_v^{(s)}(t+\Delta t)\nu_u^{(c)}(t+\Delta t) \vbar \mathcal H_t]$ given the two events:
%
\begin{align}
 \begin{split}
  \!\!\!\!\!\!\!\! h(t+\Delta t) =\ & {n_v^{(s)}}^m(t){(\nu_{u,0}^{(c)})}^{q}(t) \mathbb P\left( \neg e_i \vbar \mathcal H_t \right) \\
  &+ n_v^{(s)}(t){(\nu_{u,e_i}^{(c)})}^{q}(t) \mathbb P\left(e_i \neq (w,s,t_i) \vbar \mathcal H_t \right) \\
  &+ (n_v^{(s)}(t)+1)^m{(\nu_{u,e_i}^{(c)})}^{q}(t) \mathbb P\left( e_i = (w,s,t_i) \vbar \mathcal H_t \right).\! \\
  \end{split}
\end{align}
With $\lim_{t\to 0}\frac{\mathbb E[h(t+\Delta t) - h(t)]}{\Delta t} = \frac{d \mathbb E[{n_v^{(s)}}^m(t){\nu_u^{(c)}}^q(t)]}{dt}$, using \Eq{eq:step2}, \Eq{eq:step3a} and \Eq{eq:step3b}, and taking the full expectation, we obtain the following differential equation for $\mathbb E[{n_v^{(s)}}^m(t){\nu_u^{(c)}}^q(t)]$:
%
\begin{align}
 \begin{split}\label{eq:diff_eq_Ng}
  \frac{d}{dt} \mathbb E[&{n_v^{(s)}}^m(t){\nu_u^{(c)}}^q(t)] = \\
  & -n \mathbb E[{n_v^{(s)}}^m(t){\nu_u^{(c)}}^{q-1}(t)(\nu_u^{(c)}(t)-\mu_u^{(c)})]/\tau\\
  &+ \sum_{j \in \mathcal{V}} \sum_{k=0}^{q-1} \binom{n}{k} \weight_{ju}^{q-k} \mathbb E[{n_v^{(s)}}^m(t)\lambda_j^{(c)}(t){\nu_u^{(c)}}^{k}(t)]\\
  &+ \sum_{l=0}^{m-1} \sum_{k=0}^{q} \binom{m}{l} \binom{n}{k} \weight_{vu}^{q-k}\delta_{s,c}^{q-k} \mathbb E[{n_v^{(s)}}^{l}(t) \lambda_v^{(s)}(t){\nu_u^{(c)}}^{k}(t)].\\
 \end{split}
\end{align}
%
Note that the derivation relies on the same assumptions of regularity of Hawkes processes as in \cite{cuiElementaryDerivationMoments2020}. The moments of the conditional intensity and the number of events $\mathbb E[{n_v^{(s)}}^m(t)\lambda_u^q(t)]$ can be derived in a similar way for the \MIC model:
%
\begin{align}
 \begin{split}\label{eq:diff_eq_Nlambda}
  \frac{d}{dt} \mathbb E[{n_v^{(s)}}^m(t)& \lambda_u^q(t)] = -n \mathbb E[{n_v^{(s)}}^m(t)\lambda_u^{q-1}(t)(\lambda_u(t)-\mu_u)]/\tau\\
  &+ \sum_{j \in \mathcal{V}} \sum_{k=0}^{q-1} \binom{n}{k} \weight_{ju}^{q-k} \mathbb E[{n_v^{(s)}}^m(t)\lambda_j(t)\lambda_u^{k}(t)]\\
  &+ \sum_{l=0}^{m-1} \sum_{k=0}^{q} \binom{m}{l} \binom{n}{k} \weight_{vu}^{q-k} \mathbb E[{n_v^{(s)}}^{l}(t) \lambda_v(t)\lambda_u^{k}(t)].
 \end{split}
\end{align}

\subsection{Application: computation of the global user intensity and the number of events}
The differential \Eq{eq:diff_eq_Ng} can be solved for specific values of $m$, $n$.\!\!

\inlinetitle{Expectation of the cascade intensity}{.}~For $m=0$ and $q=1$, we obtain the differential equation for the expectation of the independent cascade intensity:
%
\begin{align}
 \begin{split}\label{eq:diff_eq_g}
   \!\!\!\!\frac{d}{dt} \mathbb E[\nu_u^{(c)}(t)] &= -( \mathbb E[\nu_u^{(c)}(t)]- \mu_u^{(c)})/\tau
   + \sum_{j \in \mathcal{V}} \weight_{ju} \mathbb E[\lambda_j(t)f_j(c \vbar t)]\\
   &=-( \mathbb E[\nu_u^{(c)}(t)]- \mu_u^{(c)})/\tau+ \sum_{j \in \mathcal{V}} \weight_{ju} \mathbb E[\lambda_j^{(c)}(t)].
 \end{split}
\end{align}
%
In this form, the first term corresponds to the exponential decay that accounts for the recency of past events, while the second term is the contribution from every neighboring activity at time $t$ for cascade $c$.

Summing \Eq{eq:diff_eq_g} over $c$ (or equivalently taking $(m,n)=(0,1)$ in \Eq{eq:diff_eq_Nlambda}), we obtain the differential equation for the expectation of user intensity $\mathbb E[\lambda_u(t)]$:
%
\begin{align}\label{eq:diff_eq_lambda}
 \begin{split}
  \frac{d}{dt} \mathbb E[\lambda_u(t)] &= -(\mathbb E[\lambda_u(t)] - \mu_u)/\tau + \sum_{v \in \mathcal{V}} \weight_{vu} \mathbb E[\lambda_v(t)].
 \end{split}
\end{align}
%
\Eq{eq:diff_eq_lambda} can be expressed in vectorial form for all users $u$:
%
\begin{align}
 \begin{split}
  \frac{d}{dt} \mathbb E[\boldsymbol \lambda(t)] &= -(\mathbb E[\boldsymbol \lambda(t)] - \boldsymbol \mu)/\tau + \mathbf{\Weight}^\top \mathbb E[\boldsymbol \lambda(t)].
 \end{split}
\end{align}
%
This equation is analogous to the one derived in \cite{deLearningForecastingOpinion2016,farajtabarCOEVOLVEJointPoint2017} and can be analytically solved for the \MIC model, if we consider the initial condition $\mathbb E[\boldsymbol \lambda(0)] = \boldsymbol \mu$:
%
\begin{align}\label{eq:th_lambda}
 \begin{split}
  \mathbb E[\boldsymbol \lambda(t)] &= \left[\boldsymbol B + (\mathbf{\Id} - \boldsymbol B) e^{- \boldsymbol B^{-1} t/\tau}\right]\boldsymbol \mu,
 \end{split}
\end{align}
%
where $\boldsymbol B = (\mathbf{\Id} - \mathbf{\Weight}^\top\tau)^{-1}$. %
The expected intensity converges to the stationary value $\boldsymbol \lambda_{\infty} = \boldsymbol B \boldsymbol \mu$ if it holds for the spectral radius: $\rho(\mathbf{\Weight}^\top) < 1/\tau$. This condition can be interpreted as the balance between the amplitude of event social influence and its temporal decay. Then, after a negative exponential increase, the expected intensity tends to the stationary value $\boldsymbol B \boldsymbol \mu$.



\inlinetitle{Expected number of events}{.}~Next, the definition of the expectation of the number of events can be recovered in \Eq{eq:diff_eq_Ng} for $m=1$, $q=0$: $\frac{d \mathbb E[n_v^{(s)}(t)]}{dt} = \mathbb E[\lambda_v^{(s)}(t)]$. The expectation of the number of events can then be expressed as:
%
\begin{align}
 \begin{split}
  \mathbb{E}[\boldsymbol n(t)] &= \left[\boldsymbol B t + (\boldsymbol{I} - \boldsymbol{B}) \boldsymbol B \tau\left(\boldsymbol I - e^{- \boldsymbol B^{-1} t/\tau}\right)\right]\boldsymbol \mu,
 \end{split}
\end{align}
%
with the initial condition $\mathbb E[\boldsymbol N(0)] = 0$. Therefore, the expected number of events tends to a linear regime of slope $\boldsymbol B \boldsymbol \mu$.
Given the non-independence between the intensity $\lambda_u$ and the cascade mixing function $f_u$, the analytical expression of the expected cascade-related intensity is not straightforward and goes beyond our scope. Instead, we use the following \emph{stationary state} approximation:
\begin{align}\label{eq:approx_lambda}
 \mathbb E[\lambda_u^{(c)}(t)] \approx \mathbb E[\lambda_u(t)] \frac{\exp(\beta (\boldsymbol B\boldsymbol \mu \mathbf{\Sigma})_{u,c})}{\sum_{s\in \mathcal C}\exp(\beta (\boldsymbol B\boldsymbol \mu \mathbf{\Sigma})_{u,s})},
\end{align}
where recall that $\mathbf{\Sigma}$ is the cascade interaction matrix.

