\begin{lemma}
	\label{cycle-difference-lemma} Any cycle in $\cal C$ is at least 1 unit longer than any cycle not in $\cal C$.
\end{lemma}
\begin{proof}
	Consider any cycle $D$ that is not in $\cal C$.  Lemma~\ref{cycle-lemma} implies that $D$ has an edge that does not intersect the $y$-axis. Orient the edges of $D$ to make it a directed cycle. Since the number of points to the left of the $y$-axis is the same as the number of points to its right, $D$ has two directed edges $(p_{a}, p_{b})$ and $(p_c,p_d)$ such that $a,b\le -1$ and $c,d\ge 1$. By replacing these edges with $p_ap_c$ and $p_bp_d$ we obtain an (undirected) spanning cycle $D'$ such that \[|D'|-|D|=(|p_ap_c|+|p_bp_d|)-(|p_ap_b|+|p_cp_d|)\ge 2|p_1p'_{-1}|= 2(2-\epsilon)>1.\]Since the length of any cycle $C$ in $\cal C$ is at least $|D'|$, we get $|C|>|D|+1$.  
\end{proof}


\begin{lemma}
	\label{cycle-epsilon-lemma}
	Let $0\le \varepsilon \le 1/16k$ be a real number. Suppose that every point of $P$ is perturbed by a distance of at most $\varepsilon$. Then the order of the points along any longest cycle of the new point set is the same as the order of the points along some cycle in $\cal C$.
\end{lemma}
\begin{proof}[Proof Sketch]
    The proof is similar to that of  Lemma~\ref{epsilon-lemma} and uses Lemma~\ref{cycle-difference-lemma}. {\color{mycolor}The parameter $\varepsilon$ is small enough such that the total change in the length of any spanning cycle on $P$ is less than 1/2. Together with Lemma~\ref{cycle-difference-lemma}, this implies that any longest cycle on the perturbed points corresponds to a cycle in $\cal C$.}
\end{proof}

To obtain $P'$ we only need to 
%identify 
{\color{mycolor}describe} 
the following $y$-coordinates:
\[y_1\gg y_{-1}\gg y'_2\gg y_{-2}\gg y'_3\gg \cdots\gg y'_{k}\gg y_{-k}.\] 
The $y$-coordinates of the remaining points would then follow as
outlined 
in the previous section (more details are given after Lemma~\ref{cycle-delta-epsilon-lemma}). 
We set $y_1=\frac{1}{16k}$ and $y_{-k}=0$. We use the following lemma (which can be proven similarly to Lemma~\ref{delta-lemma}) to assign the $y$-coordinates. 

\begin{lemma}
	\label{cycle-delta-lemma}
	There exists a real number $\delta$, $\epsilon\le \delta< y_1$, such that if $0\le y_i \le\delta$ for $i\neq 1$ and $0\le y'_i \le\delta$ for $i\neq -1$,
    %and $\epsilon \leq \delta$, 
  then every longest cycle of $P'$ connects $p_1$ to $p_{-1}$ and $p'_{-1}$.
\end{lemma}
\begin{proof}
Lemma~\ref{cycle-epsilon-lemma} implies that any longest cycle $C'$ on $P'$ corresponds to a cycle $C$ in $\cal C$. Due to small $y$-coordinates, we have $|C'|=|C|+\Delta(C')$ for some small value $\Delta(C')\geq 0$ which depends on the new $y$-coordinates. Lemma~\ref{cycle-lemma} implies that $C'$ connects $p_1$ to two points to the left of the $y$-axis. Similar to Lemma~\ref{delta-lemma}, for $j\in\{1,\dots,k\}$ define $\ell_{j}$ as the Euclidean distance between $p_1$ and the point $(-j,0)$, and define $\Delta_{j}$ as the difference of their $x$-coordinates. Analogously, for $j\in\{1,\dots,k{-}1\}$ define $\ell'_{j}$ and $\Delta'_{j}$ for $p_1$ and the point $(0,-j+\epsilon)$. Every edge that connects $p_1$ to a point to the left of the $y$-axis has the following contributions to $|C|$, $|C'|$ and $\Delta(C')$.

\begin{itemize}
