\mypara{Two-parts protocol}

\begin{tcolorbox}[colback=gray!5!white,colframe=black!75!black,top=2pt,bottom=2pt]
\larger \textbf{ Grassroots Consensus Protocol} \smaller
\vspace{3pt} 
\begin{enumerate}
 \item \textbf{Receipt:} Upon receipt of a new well-formed block $b$, $[b]\subseteq B\cup \{b\}$, add $b$ to $B$, and if the resulting blocklace $B$ is quiescent, change state to \textbf{low}.

\item \textbf{Low:} Upon state being low, let $r=d(B)$ and apply any of (a)-(d) below that is satisfied:
\begin{enumerate}
        \item If $r\mod 3 =1$ and round $r$ consists of  a single non-empty block $b$ non-conflicting in $B$ then issue an empty block (which is a vote for $b$).
        \item  If $r\mod 3 =2$ and round $r$ consists of a $\sigma$-supermajority among $P$ of votes for a block $b$ non-conflicting in $B$,  then issue an empty block (which ratifies $b$).
        \item If $r\mod 3 =0$, $B$ is quiescent, and  $\emph{payload} \ne \bot$ then issue a block with $\emph{payload}$ and set  $\emph{payload}:= \bot$.
        \item  If $B$ includes conflicting blocks then issue an empty block (referred to as  \emph{conflict reporting}) and change state to \textbf{high}.
\end{enumerate}

 \item  \textbf{High:} Upon  state being high,  $r$ being the most-recent round that observes the most recent $p$-block in $B$ and includes a $\sigma$-supermajority, if any of (a)-(d) below are satisfied then issue a block pointing to the tips of $B_r$ with \emph{payload} and set $\emph{payload}:=\bot$: 
\begin{enumerate}
    \item $r\mod 3 =1$ and round $r$ includes  a leader block, or
    \item  $r\mod 3 =2$ and round $r$ includes a $\sigma$-supermajority among $P$, each of which approves the leader of round $r-1$ if there is one,  or
    \item  $r\mod 3 =0$ and round $r$ includes a $\sigma$-supermajority among $P$, each of which ratifies the leader of round $r-2$ if there is one, or
    \item $\Delta$ has passed since $r$ included a $\sigma$-supermajority among $P$.
\end{enumerate}
\end{enumerate}
\end{tcolorbox}


