        &\mathcal{BI}^{+} = \mathcal{BI} \cup (\bm{\tilde{s}}_{t}, \bm{x}_{t}, \mathcal{K}_{t}, U^{\ast}_{t}, \mathcal{I}_{t}, \mathcal{B}_{t}), \\
