    \label{expect_p}
        \mathbf{E}[P_{i}|x_{i}] &= \alpha_{i} u_{i}(\tilde{s}_{i};\theta) + \mu({w_{i}}) + \mathbf{E}\left[\hat{\alpha}_{i}|x_{i}\right] \left( \sum_{j = 1, j \neq i}^{N}{{u}_{j}(\mathbf{E}\left[\tilde{s}_{j}|x_{i}\right];\mathbf{E}\left[\hat{\theta}_{j}|x_{i}\right])} \right) 
        - \mathbf{E}\left[\hat{\alpha}_{i}|x_{i}\right]\left( \underset{\bm{s}}{\max}\sum_{j = 1, j \neq i}^{N}{{u}_{j}(s_{j};\mathbf{E}\left[\hat{\theta}_{j}|x_{i}\right])}\right) \notag \\ 
