        \captionsetup{aboveskip=0pt, belowskip=12pt}
        \caption{Entries of $M$ that are equal to one are represented by orange circles, while zeros are depicted with green circles.}
        \label{fig:wanda_mask_selection_appendix}
    \end{subfigure}
    \begin{subfigure}{0.49\linewidth}
        \includegraphics[width=0.9\linewidth]{resources/pdf/in_off_block_communication.pdf}
        \captionsetup{width=.9\linewidth}
        \captionsetup{aboveskip=0pt, belowskip=12pt}
