% ---------------------------------------------------
\section{Continuous weak formulation and space--time method}
Let the forcing term~$F \in L^2(\QT) \cap H^1(0, T; H^{-1}(\Omega))$, the real-valued potential~$V \in L^{\infty}(\Omega)$, and the initial condition~$\Psi_0 \in H_0^1(\Omega)$.
The continuous weak formulation of~\eqref{eq:1} reads: find~$\Psi \in C^0([0,T]; H_0^1(\Omega))$ with~$\dpt \Psi \in C^{0}([0, T]; H^{-1}(\Omega))$ such that~$\Psi(\cdot, 0) = \Psi_0$ in~$H_0^1(\Omega)$ and
%
\begin{equation}
\label{eq:2}
\begin{split}
        \int_0^T \Big(\mi \langle \dpt \Psi(\cdot,t),W(\cdot,t) \rangle & - \frac{1}{2} (\nabla_{\bx} \Psi(\cdot,t), \nabla_{\bx} W(\cdot,t))_{\Omega} + (V \Psi(\cdot,t), W(\cdot,t))_{\Omega} \Big) \dd t 
        \\ & = \int_{0}^T (F(\cdot,t), W(\cdot,t))_{\Omega} \, \dd t  \qquad  \quad \text{for all~} W \in L^2(0, T; H^1_{0}(\Omega)),
\end{split}
\end{equation}
%
where~$\nablax$ is the spatial gradient operator, and~$\langle \cdot, \cdot \rangle$ denotes the duality between~$H^{-1}(\Omega)$ and~$H_0^1(\Omega)$.
According to~\cite[Thm.~10.1 and Rem.~10.2 in Ch.~3]{Lions-MagenesVol1:1972}, there exists a unique solution to the continuous weak formulation~\eqref{eq:2}.

We define the energy functional
%
\begin{equation} \label{eq:3}
    \mathcal{E}_{\Psi}(t) := -\frac{1}{2} \int_\Omega |\nabla_{\bx} \Psi(\bx,t)|^2 \, \dd \bx + \int_\Omega V(\bx) | \Psi(\bx,t)|^2  \, \dd \bx,
\end{equation}
%
and the mass functional
%
\begin{equation} \label{eq:4}
    \mathcal{M}_{\Psi}(t) := \int_\Omega |{\Psi}(\bx,t)|^2  \, \dd \bx.
\end{equation}
%
%%
\begin{remark}[Conservation of invariants] \label{rem:21}
Assuming that~$F \in H^1(0, T; L^2(\Omega))$ and~$\partial \Omega$ is sufficiently smooth, the solution~${\Psi}$ to~\eqref{eq:2} belongs to the space~$L^2(0, T; H_0^1(\Omega) \cap H^2(\Omega)) \cap H^1(0, T; L^2(\Omega))$; see~\cite[Thm.~12.1 in Ch.~5]{Lions-MagenesVol2:1972}. Then, we can choose~$W$ in the weak formulation~\eqref{eq:2} as~$W(\bx,s) = \partial_s {\Psi}(\bx,s) \mathds{1}_{[0,t]}(s)$, where~$\mathds{1}_{[0,t]}$ is the characteristic function on~$[0,t]$, and take the real part of the resulting equation to obtain
%
\begin{align*}
    \calE_{\Psi}(t) & = \calE_{\Psi}(0) + 2 \Re \int_0^t F(\bx,s) \partial_s \conj{{\Psi}}(\bx,s)\,  \dd \bx \, \dd s \quad \text{~for all~} t \in [0,T].
\end{align*}
%
Similarly, choosing~$W$ in~\eqref{eq:2} as $W(\bx,s) = {\Psi}(\bx,s) \mathds{1}_{[0,t]}(s)$, taking the imaginary part of the resulting equation, and using the identity
%
\begin{equation} \label{eq:5}
    \Re\, (\dpt {\Psi}(\cdot,t), {\Psi}(\cdot,t))_\Omega = \frac{1}{2} \int_\Omega | {\Psi}(\bx,t) |^2 \dd \bx - \frac{1}{2} \int_\Omega | {\Psi}_0(\bx) |^2 \dd \bx
\end{equation}
%
leads to
%
\begin{align*}
    \calM_{\Psi}(t) & = \calM_{\Psi}(0) + 2 \Im \int_0^t F(\bx,s)  \conj{{\Psi}}(\bx,s)\,  \dd \bx \, \dd s\quad \text{~for all~} t \in [0,T].
\end{align*}
%
As a consequence, for~$F \equiv 0$, the energy~\eqref{eq:3} and the mass~\eqref{eq:4} functionals are conserved, i.e., 
%
\begin{equation*}
    \frac{\dd}{\dd t} \calE_{\Psi}(t) = 0 \quad \text{ and } \quad \frac{\dd}{\dd t} \calM_{\Psi}(t) = 0.
\end{equation*}
It is desired to reproduce this property at the discrete level.
%
\eremk
\end{remark}
%%

\subsection{Definition of the space--time method} \label{sec:21}
Given~$N \in \N$, we define a uniform mesh $\{ t_j = jh_t \, : \, j = 0, \ldots, N \}$ for the time interval~$(0, T)$, with meshsize~$h_t = T/N$.  Moreover, for~$j = 1, \ldots, N$, we define~$I_j := (\tjmo, \tj)$.
We consider the space of maximal regularity splines of degree $p \geq 1$ and regularity $p - 1$ with values in the field $\mathbb{K}$, defined by
%
\begin{equation*}
    S_{h_t}^p(0,T;\mathbb{K}) := \{ \wht \in C^{p-1}([0,T]) \ : \ \wht {}_{|_{I_j}} \in \P_p(I_j; \mathbb{K}), \, j = 1,\ldots N\},
\end{equation*}
%
where~$\P_p(I_j; \mathbb{K})$ is the space of $\mathbb{K}$-valued polynomials of degree~$p$ defined on~$I_j$. This space satisfies $\dim_{\mathbb{K}}(S_{h_t}^p(0,T;\mathbb{K})) = N + p$. We also define the following subspaces with null initial and final conditions, respectively
%
\begin{equation} \label{eq:6}
\begin{aligned}
    S_{h_t,0,\bullet}^p(0,T;\mathbb{K}) & = \big\{ \wht \in S_{h_t}^p(0,T;\mathbb{K}) : \wht (0) = 0\big\}, 
    \\ 
    S_{h_t,\bullet,0}^p(0,T;\mathbb{K}) & = \big\{ \wht \in S_{h_t}^p(0,T;\mathbb{K}): \wht(T) = 0\big\}.
\end{aligned}
\end{equation}
%
Let also~$\Shx(\Omega)$  be a discrete conforming subspace of~$H_0^1(\Omega)$, and~$\Pi_{\hx} {\Psi}_0 \in \Shx(\Omega)$ be a discrete approximation of~${\Psi}_0$. The proposed method, which is a discrete counterpart of the continuous weak formulation~\eqref{eq:2}, reads:
%%
\begin{tcolorbox}[
    colframe=black!50!white,
    colback=blue!5!white,
    boxrule=0.5mm,
    sharp corners,
    boxsep=0.5mm,
    top=0.5mm,
    bottom=0.5mm,
    right=0.25mm,
    left=0.1mm
]
    \begingroup
    \setlength{\abovedisplayskip}{0pt}
    \setlength{\belowdisplayskip}{0pt}
    \begin{equation} \label{eq:7}
    \begin{aligned}
    &\hspace{-1.75cm}\text{find}~\Uhp \in  \Pi_{\hx} \Psi_0 + S_{h_t,0,\bullet}^p(0,T;\C) \otimes \Shx(\Omega)~\text{such that} \vspace{0.1cm}
    \\ & \mi (\dpt \Uhp, \Whpmo)_{\QT} - \frac{1}{2} (\nablax \Uhp, \nablax \Whpmo)_{\QT} + (V \Uhp, \Whpmo)_{\QT} = (F, \Whpmo)_{\QT}
    \vspace{0.1cm}
    \\ & \hspace{-1.8cm}\text{~for all~} \Whpmo \in \Sht{p-1}{p-2}(0,T;\C) \otimes \Shx(\Omega).
    \end{aligned}
    \end{equation}
    \endgroup
\end{tcolorbox}
%%
As mentioned before, method~\eqref{eq:7} is related to the one introduced by Karakashian and Makridakis in~\cite{KarakashianMakridakis1999}, where continuous piecewise polynomials of degree~$p$  (resp. piecewise polynomials of degree~$p - 1$) in time are used for the trial (resp. test) space. The method in \cite{KarakashianMakridakis1999} conserves the energy~\eqref{eq:3} and the mass~\eqref{eq:4} functionals at all discrete times. In Proposition~\ref{prop:22}, we show that method~\eqref{eq:7} conserves the energy and the mass at the final time~$T$.
%%
\begin{proposition}[Conservation properties of~\eqref{eq:7}]
\label{prop:22}
Let~$F \equiv 0$ and~$\Uhp$ be a solution to method~\eqref{eq:7}. Then, it holds
%
\begin{equation*}
    \calM_{\Uhp}(T) = \calM_{\Uhp}(0) \qquad \text{ and } \qquad \calE_{\Uhp}(T) = \calE_{\Uhp}(0).
\end{equation*}
%
\end{proposition}
%%
\begin{proof}
For the conservation of the mass, we choose~$\Whpmo = \Pi_{h_t}^{p-1} \Uhp$ in~\eqref{eq:7}, where~$\Pi_{h_t}^{p-1}$ is the $L^2(0, T)$ projection into~$S_{h_t}^{p-1}(0,T;\C)$. Using the orthogonality properties of~$\Pi_{h_t}^{p-1}$, we obtain
%
\begin{align*}
        0 & = \mi (\dpt \Uhp, \Pi_{h_t}^{p-1} \Uhp)_{\QT} - \frac{1}{2} (\nablax \Uhp, \nablax \Pi_{h_t}^{p-1} \Uhp)_{\QT} + (V \Uhp, \Pi_{h_t}^{p-1} \Uhp)_{\QT}
        \\ &  = \mi (\dpt \Uhp, \Uhp)_{\QT} - \frac{1}{2} \|\nablax \Pi_{h_t}^{p-1} \Uhp\|^2_{L^2(\QT)} + (V \Pi_{h_t}^{p-1} \Uhp, \Pi_{h_t}^{p-1} \Uhp)_{\QT}.
\end{align*}
%
Taking the imaginary part of the above equation and using identity~\eqref{eq:5} 
yields the conservation of mass. The conservation of the energy readily follows by taking~$\Whpmo = \dpt \Uhp$ in~\eqref{eq:7} and proceeding as for the continuous case (see Remark~\ref{rem:21}).
\end{proof}

