\section{Stability analysis} \label{sec:3}
In this section, we study the stability properties of the space--time method~\eqref{eq:7}. To do so, we first consider the corresponding discretization of the ODEs derived from the Fourier expansion of the  continuous solution to~\eqref{eq:2}. Then, the stability analysis for the space--time method~\eqref{eq:7} follows in an analogous way; see Remark~\ref{rem:32} below for more details.

Henceforth, we assume that the spatial domain~$\Omega$ is convex, $F \in H^1(0,T;L^2(\Omega))$, and~$\Psi_0 \in H^2(\Omega) \cap H_0^1(\Omega)$ 
to guarantee that the solution~$\Psi$ to \eqref{eq:2} belongs to~$L^2(0,T;H_0^1(\Omega)) \cap H^1(0,T;L^2(\Omega))$.

We also define the following Sobolev spaces:
%
\begin{equation*}
\begin{split}
    H_{0, \bullet}^1(0, T) & := \{v \in H^1(0, T) \, : \, v(0) = 0\}, 
    \\ H_{\bullet, 0}^1 (0, T) & := \{v \in H^1(0, T) \, : \, v(T) = 0 \}. 
    \end{split}
\end{equation*}
%

\subsection{Variational formulation of the associated initial value problem}

Consider the eigenvalue problem
%
\begin{equation*}
    \begin{cases}   
        \frac{1}{2} \Delta \Phi (\bx) + V(\bx) \Phi (\bx) = \mu \Phi(\bx) & \bx \in \Omega,
        \\ \Phi(\bx) = 0 & \bx \in \partial \Omega.
    \end{cases}
\end{equation*}
%
Due to the assumption~$V \in L^\infty(\Omega)$, according to~\cite[Rem.~30 in Ch.~8]{Brezis2010}, there exists a Hilbert basis of $L^2(\Omega)$ composed of eigenfunctions~$\{\Phi_j(\bx)\}_{j \ge 1}$ associated with real eigenvalues~$\{ \mu_j \}_{j \ge 1}$. Therefore, any solution to~\eqref{eq:2} admits the representation
%
\begin{equation*}
    \Psi(\bx,t) = \sum_{j=1}^\infty \psi_j(t) \Phi_j(\bx),
\end{equation*}
%
for some coefficients~$\{\psi_j\}_{j \geq 1} \subset H^1(0,T)$ satisfying
%
\begin{equation*} 
    \begin{cases}
        \mi (\dpt \psi_j, w)_{J_T} + \mu_j ( \psi_j, w)_{J_T} = (f_j, w)_{J_T} \quad \text{for all~} w \in L^2(0,T), \\
        \psi_j(0) = \Psi_0^j,
    \end{cases}
\end{equation*}
%$
where $f_j(t) := (F(\cdot,t), \psi_j)_\Omega$ and $\Psi_0^j := (\Psi_0, \psi_j)_\Omega$. 

Consequently, without loss of generality, we consider the following initial value problem (IVP): given~$f \in L^2(0,T)$, $\mu \in \R$, and~$\psi_0 \in \C$, find $\psi \in H^1(0,T)$ such that
%
\begin{equation} \label{eq:9}
    \begin{cases}
        \mi \dpt \psi(t) + \mu \psi(t) = f(t) & t \in (0,T), \\
        \psi(0) = \psi_0.
    \end{cases}
\end{equation}
%
To study the stability of the space--time method~\eqref{eq:7}, we focus on the corresponding discrete variational formulation associated with the IVP~\eqref{eq:9}, and analyze its stability with respect to the real parameter~$\mu$.

Similarly as in Section \ref{sec:21}, for a given~$N \in \N$, we define a uniform mesh $\{ t_j = jh\ : \ j = 0, \ldots, N \}$ for the time interval~$(0, T)$, with meshsize~$h = T/N$. The numerical discretization of the IVP~\eqref{eq:9}
reads:
%%
\begin{tcolorbox}[
    colframe=black!50!white,
    colback=blue!5!white,
    boxrule=0.5mm,
    sharp corners,
    boxsep=0.5mm,
    top=0.5mm,
    bottom=0.5mm,
    right=0.25mm,
    left=0.1mm
]
    \begingroup
    \setlength{\abovedisplayskip}{0pt}
    \setlength{\belowdisplayskip}{0pt}
    \begin{equation} \label{eq:10}
    \begin{aligned}
    &\hspace{-1.75cm}\text{find}~\psi_h^p \in  \psi_0 + S_{h,0,\bullet}^p(0,T;\C)~\text{such that} \vspace{0.1cm}
    \\ & \mi (\dpt \psi_h^p, w_h^{p-1})_{J_T} + \mu (\psi_h^p, w_h^{p-1})_{J_T} = (f, w_h^{p-1})_{J_T} \quad \text{~for all~} w_h^{p-1} \in S_h^p(0,T;\C).
    \end{aligned}
    \end{equation}
    \endgroup
\end{tcolorbox}
%%
%%
\begin{remark} \label{rem:31}
Since $\dpt : S_{h,\bullet,0}^p(0,T;\C) \to S_h^{p-1}(0,T;\C)$ is an isomorphism, integration by parts and the definition of the spaces~$S^p_{h, \bullet, 0}(0, T; \C)$ and~$S^p_{h, 0, \bullet}(0, T; \C)$ can be used to show that the discrete formulation \eqref{eq:10} is equivalent to: find~$\psi_h^p \in  \psi_0 + S_{h,0,\bullet}^p(0,T;\C)$ such that
%
\begin{equation*} \label{eq:11}
        \mi (\dpt \psi_h^p, \dpt w_h^p)_{J_T} - \mu (\dpt \psi_h^p, w_h^p)_{J_T} = (f, \dpt w_h^p)_{J_T} +\mu \psi_0 w_h^p(0) \quad\quad \text{for all}~w_h^p \in S_{h,\bullet,0}^p(0,T;\C).
\end{equation*}
%
\eremk
\end{remark}
%%
%%
\begin{remark}[Stability of the space--time method~\eqref{eq:7}]
\label{rem:32}
The theoretical results in this section can be easily adapted to the fully discrete setting in~\eqref{eq:7}. The reasoning is the following:
\begin{itemize}
%%
\item Given a basis for the discrete space~$\Shx(\Omega)$, the conforming space discretization of the Hamiltonian operator~$(\frac12 \Delta_{\bx} + V)$ leads to the the generalized eigenvalue problem: find pairs~$(\mu_{h_{\bx}}, \Phi_{h_{\bx}}) \in \C \times \Shx(\Omega)$ such that
%
\begin{equation*}
    \mathbf{A}_{h_{\bx}} \boldsymbol{\Phi}_{h_{\bx}} = \mu_{h_{\bx}} \M_{h_{\bx}} \boldsymbol{\Phi}_{h_{\bx}},
\end{equation*}
%
where~$\mathbf{A}_{h_{\bx}}$ and~$\bM_{h_{\bx}}$ are the matrices representing, respectively, the Hamiltonian operator and the~$L^2(\Omega)$ inner product, and~$\boldsymbol{\Phi}_{h_{\bx}}$ is the vector representation of~$\Phi_{h_{\bx}}$ in the given basis.
%%
\item Let $N_{\bx} := \dim_{\R} S_{h_{\bx}}(\Omega)$. Since~$\mathbf{A}_{h_{\bx}} \in \R^{N_{\bx} \times N_{\bx}}$ and~$\bM_{h_{\bx}} \in \R^{N_{\bx} \times N_{\bx}}$ are real symmetric matrices, and~$\bM_{h_{\bx}}$ is positive definite, the eigenvalues~$\mu_{h_{\bx}}$ are real, and the corresponding discrete eigenfunctions~$\{\Phi_{j,h_{\bx}}\}_{j=1}^{N_{\bx}}$ form a basis of~$\Shx(\Omega)$ orthogonal with respect to the~$L^2(\Omega)$ inner product. 
%%
\item Consequently, the discrete solution to~\eqref{eq:7} can be written as
%
\begin{equation*}
    \Uhp = \sum_{j=1}^{N_{\bx}} \psi_{j, h_t}(t) \Phi_{j, h_{\bx}}(\bx),
\end{equation*}
%
for some coefficients~$\psi_{j, h_t} \in \Sht{p}{p-1}(0, T)$.
The space--time method~\eqref{eq:7} then reduces to solving a set of independent problems similar to those in~\eqref{eq:10}.
\end{itemize}
\eremk
\end{remark}
%%
Before focusing on stability, we first investigate the uniqueness of the solution to~\eqref{eq:10}. Due to the limitations of the matrix approach described in Section~\ref{sec:33} below, it is currently not possible to show the solvability of the linear system stemming from~\eqref{eq:10}. Consequently, a variational argument seems to be required. In Section~\ref{sec:32} below, we identify a range of values for~$\mu$ that guarantee uniqueness, and we introduce a fundamental assumption for the general case.

% ------------------------------------------------------
%               UNIQUENESS
% ------------------------------------------------------
\subsection{Uniqueness of the solution to \texorpdfstring{\eqref{eq:10}}{(9)}} \label{sec:32}

At the \textit{continuous} level, the uniqueness of the solution to the variational formulation of  \eqref{eq:9} holds, as shown in the following result.
%%
\begin{proposition} \label{prop:32}
Given~$f \in L^2(0, T)$ and~$\psi_0 \in \C$, the following variational problem has a unique solution: find~$\psi \in \psi_0 + H^1_{0,\bullet}(0,T)$ such that
%
\begin{equation} \label{eq:12}
        \mi (\dpt \psi, w)_{J_T} + \mu (\psi, w)_{J_T} = (f, w)_{J_T} \quad \text{for all~} w \in L^2(0,T).
\end{equation}
%
\end{proposition}
%%%
\begin{proof}
We can show that
%
\begin{equation*}
\psi(t) = e^{-\mi \mu t} \psi_0 + e^{-\mi \mu t} \int_0^t e^{\mi \mu s} f(s) \dd s
\end{equation*}
%
solves~\eqref{eq:9}, and due to the regularity assumption on~$f$, it is also a solution to~\eqref{eq:12}.

To show uniqueness, suppose that $\psi \in H^1_{0,\bullet}(0,T)$ satisfies the homogeneous problem
%
\begin{equation} \label{eq:13}
        \mi (\dpt \psi, w)_{J_T} + \mu (\psi, w)_{J_T} = 0 \quad \text{for all~} w \in L^2(0,T).
\end{equation}
%
We test~\eqref{eq:13} with~$w(t) = e^{-t/T} \dpt \psi(t)$. It can be easily seen that
%
\begin{equation} \label{eq:14}
    (\dpt \psi, e^{-\bullet/T} \dpt \psi)_{J_T} = \int_0^T \partial_s \psi(s) \partial_s \overline{\psi}(s) e^{-s/T} \dd s = \int_0^T |\partial_s \psi(s)|^2 e^{-s/T} \dd s.
\end{equation}
%
Using the identity $\text{Re}(\psi \dpt \overline{\psi}) = \frac{1}{2} \dpt |\psi|^2$ and integration by parts, we also obtain
%
\begin{equation} \label{eq:15}
    \text{Re}(\psi, e^{-\bullet/T} \dpt \psi)_{J_T} = \int_0^T \text{Re}(\psi(s) \partial_s \overline{\psi}(s)) e^{-s/T} \dd s = \frac{1}{2T} \int_0^T |\psi(s)|^2 e^{-s/T} \dd s + \frac{1}{2e} |\psi(T)|^2.
\end{equation}
%
Inserting \eqref{eq:14} and \eqref{eq:15} in \eqref{eq:13}, we conclude  
%
\begin{equation*}
    0 = \text{Re}(\mi (\dpt \psi, w)_{J_T} + \mu (\psi,w)_{J_T}) = \int_0^T |\partial_s \psi(s)|^2 e^{-s/T} \dd s +  \frac{\mu}{2T} \int_0^T |\psi(s)|^2 e^{-s/T} \dd s + \frac{\mu}{2e} |\psi(T)|^2,
\end{equation*}
%
from which we deduce $\psi \equiv 0$.
\end{proof}
%%
Unfortunately, the argument used in Proposition~\ref{prop:32} does not extend to the \emph{discrete} level, as the test function~$e^{-t/T} \dpt \psi_h^p(t)$ does not belong to the discrete space. One could adapt the scheme~\eqref{eq:10} by incorporating exponential functions into the test space (or, equivalently, modifying the
sesquilinear form) in the spirit of the method in~\cite{FerrariPerugia2025}. 
However, this approach lies beyond the scope of the present paper, as we are primarily interested in the conservation properties reported in Proposition~\ref{prop:22}, which would not be satisfied by the modified formulation.

In the next proposition, we prove the uniqueness of the solution to the discrete variational formulation~\eqref{eq:10} for a range of values of~$\mu$. 
%%
\begin{proposition} \label{prop:33}
If $|\mu| < \pi/T$, then problem \eqref{eq:10} has a unique solution.
\end{proposition}
%%
\begin{proof}
Let $\psi_h^p \in S_{h,0,\bullet}^p(0,T,\C)$ be a solution to~\eqref{eq:10} with zero data, i.e., it satisfies (see Remark \ref{rem:31})
%
\begin{equation} \label{eq:16} 
        \mi (\dpt \psi_h^p, \dpt w_h^p)_{J_T} - \mu (\dpt \psi_h^p, w_h^p)_{J_T} = 0 \quad \text{for all~} w_h^p \in S_{h,\bullet,0}^p(0,T,\C).
\end{equation}
%
Choosing the test function $w_h^p = \psi_h^p-\psi_h^p(T)$ in \eqref{eq:16}, we obtain
%
\begin{equation} \label{eq:17}
    0=\mi \| \dpt \psi_h^p \|^2_{L^2(0,T)} - \mu (\dpt \psi_h^p, \psi_h^p - \psi_h^p(T))_{J_T} = \mi \| \dpt \psi_h^p \|^2_{L^2(0,T)} - \mu (\dpt \psi_h^p, \psi_h^p)_{J_T}  + \mu | \psi_h^p(T)|^2.
\end{equation}
%
We split~\eqref{eq:17} in its real and imaginary parts. Taking the real part of~\eqref{eq:17} and using the identity~$\text{Re}(\psi_h^p \dpt \overline{\psi}_h^p) = \frac{1}{2} \dpt |\psi_h^p|^2$, we get
%
\begin{equation*}
    | \psi_h^p(T) |^2 = \Re (\dpt \psi_h^p, \psi_h^p)_{J_T} = \frac{1}{2} |\psi_h^p(T)|^2, 
    \quad \text{whence~} \, \psi_h^p(T)=0.
\end{equation*}
%
Taking the imaginary part of \eqref{eq:17} gives
%
\begin{equation*}
    \| \dpt \psi_h^p \|^2_{L^2(0,T)} = \mu \text{Im}(\dpt \psi_h^p, \psi_h^p)_{J_T}. 
\end{equation*}
%
Then, using the Cauchy--Schwarz inequality, and the Poincar\'e inequality in one dimension with the sharp constant~$T/\pi$ (which holds for functions vanishing at the endpoints), we obtain
%
\begin{equation*}
    \| \dpt \psi_h^p \|^2_{L^2(0,T)} \le |\mu| \| \dpt \psi_h^p \|_{L^2(0,T)} \| \psi_h^p\|_{L^2(0,T)} \le |\mu| \frac{T}{\pi} \| \dpt \psi_h^p \|^2_{L^2(0,T)}.
\end{equation*}
%
If~$|\mu| < T/\pi$, this implies that~$\| \partial_t \psi_h^p\|_{L^2(0,T)}=0$, and 
 thus~$\psi_h^p \equiv 0$.
\end{proof}
%%
Proposition~\ref{prop:33} is far from being sharp in practice. Indeed, we have not encountered any situations where uniqueness fails at the discrete level. We therefore make the following fundamental assumption in the rest of this section.
%%
\begin{assumption} \label{assu:34}
For all $p \in \mathbb{N}$ with~$p \geq 1$, $h > 0$, and $\mu \in \R$, the variational formulation~\eqref{eq:10} admits a unique solution.
\end{assumption}
%%
\begin{remark}
Assumption \ref{assu:34} holds for $p=1$. 
Indeed, in this case, the system matrix stemming from~\eqref{eq:10} is a lower triangular matrix with entries all equal to~$-\left(8\mi/h +\mu/2\right)$ on the diagonal.  
Its invertibility for all~$h>0$ and~$\mu \in \R$ readily follows. For~$p>1$, the larger support of B-splines does not provide sufficient insight to establish the invertibility of the system matrix through a linear algebra argument.
\eremk
\end{remark}
%%

\subsection{Toeplitz structure of the system matrix and weakly well-conditioning} \label{sec:33}

In this section, under the crucial Assumption \ref{assu:34} of uniqueness of the solution to the discrete problem, we show unconditional stability of the scheme~\eqref{eq:10} via a matricial approach, in the same spirit as
in~\cite{FerrariFraschini2025, FerrariFraschiniLoliPerugia2024}. We first define the matrices involved in the discrete formulation.

Let consider the B-splines~$\{ \phi_j^p\}_{j=0}^{N+p-1}$ of degree~$p$ with maximal regularity~$C^{p-1}$ defined according to the Cox-De Boor recursion formula~\cite[\S1]{deBoor1972}. In particular, the basis is ordered such that, for the spaces defined in \eqref{eq:6}, the following representations hold:
%
\begin{equation*}
    S_{h,0,\bullet}^{p}(0,T,\C) = \text{span}_{\C}\{\phi_j^p : j = 1,\ldots, N+p-1\}, \quad S_{h,\bullet,0}^{p}(0,T,\C) = \text{span}_{\C}\{\phi_j^p : j = 0,\ldots, N+p-2\}. 
\end{equation*}
%
Hence, the matrices involved in the discrete variational formulation~\eqref{eq:10} are defined as
%
\begin{equation} \label{eq:18}
	\B^p_h[\ell,j] := (\dpt \phi_j^p, \dpt \phi^p_{\ell-1})_{J_T}, \quad \bC^p_h[\ell,j] := (\dpt \phi_j^p, \phi^p_{\ell-1})_{J_T},
\end{equation}
%
for $\ell, j = 1,\ldots,N+p-1$. The system matrix associated with formulation \eqref{eq:10} then reads (see Remark~\ref{rem:31})
%
\begin{equation} \label{eq:19}
    \mathbf{K}_h^p(\mu) := \mi \B_h^p - \mu \bC_h^p.
\end{equation}
%
The aim of this section is to study the behavior of the condition number of the family of matrices $\{\K_h^p(\mu)\}$ with respect to $h$, $p$, and $\mu$. In particular, we show that, for all $p \in \N$ and $\mu \in \R$, the condition number of~$\K_h^p(\mu)$, as a function of~$h$, does not grow exponentially but rather as an algebraic power of~$1/h$. This is the type of unconditional stability that we aim for, which contrasts with conditional stability, where a particular relation between~$h$, $p$, and $\mu$ is required so that the condition number grows as an algebraic power of~$1/h$, and it grows exponentially otherwise.

The subsequent analysis is based on four main steps, which are common also to the analyses carried out in~\cite{FerrariFraschini2025} and \cite{FerrariFraschiniLoliPerugia2024}. The outline is as follows:
\begin{enumerate}
    \item We show that the entries of the matrices~$ h\B_h^p $ and $ \bC_h^p $, defined in \eqref{eq:18}, do not depend on $h$, and that they are Toeplitz matrices with specific symmetries, except for a fixed number of entries (depending only on $ p $) in the top-left and bottom-right corners. We refer to such matrices as \textit{nearly Toeplitz}. As a consequence, the system matrix $\mathbf{K}_h^p(\mu)$ is nearly Toeplitz and exhibits the same structure, and up to a rescaling, its entries only depend on the quantity~$ \mu h$. 

    \item  We recall the definition in~\cite{AmodioBrugnano1996} of \textit{weakly well-conditioning} for a family of matrices, and state a sufficient condition for the weakly well-conditioning of families of Toeplitz matrices~\cite[Thm.~3]{AmodioBrugnano1996}, along with its generalization to nearly Toeplitz matrices~\cite[Thm.~4.5]{FerrariFraschini2025}. 
    This sufficient condition involves characterizing the zeros of the \textit{symbol polynomial} associated with the family.

    \item Given the symmetries of $h\B_h^p$ and $\bC_h^p$ exploited in the first step, we obtain that, if the symbol polynomial associated with the family $\{\K_h^p(\mu)\}$ has exactly two zeros of unitary modulus, then $\{\K_h^p(\mu)\}$ is weakly well-conditioned.

    \item Finally, we compute the symbol polynomial associated with the family $ \{ \K_h^p(\mu) \}$ and show that it has exactly two zeros of unitary modulus for all $ \mu \in \R$ and $ p \in \N$.
\end{enumerate}
%%

\paragraph{Step 1. Nearly Toeplitz structure of the matrices $h\B_h^p$ and $\bC_h^p$} 
\label{step:1}
\phantom{of the opera} \\
%%
The next results have been proven in~\cite[Prop.~3.2]{FerrariFraschini2025} and~\cite[Prop.~2.3]{FerrariFraschiniLoliPerugia2024} (see also  \cite[\S 4.1]{GaroniManniPelosiSerraCapizzanoSpeleers2014}).
%%
\begin{proposition} \label{prop:37}
Let~$p \ge 1$ and let the matrices~$\B_h^p$ and~$\bC_h^p$ be defined in~\eqref{eq:23}. Then, the following properties hold true:
%%
\begin{enumerate}[label=\arabic*), ]
%%
\item \label{P1} The entries of the matrices~$h\B_h^p$ and~$\bC_h^p$ are independent of the mesh parameter~$h$.
%%
\item The matrices~$\B_h^p$ and~$\bC_h^p$ are persymmetric, i.e., they are symmetric about their northeast-to-southwest diagonal (anti-diagonal).
%%
\item \label{P3} The matrices $\B_h^1$ and $\bC_h^1$ are lower triangular Toeplitz band matrices with three nonzero diagonals. For $p > 1$, the matrices $\B_h^p$ and $\bC_h^p$, except for $2(2p^2 - 3)$ entries located at the top-left and bottom-right corners, exhibit a Toeplitz band structure with $p+1$ bands below the main diagonal and $p-1$ above. Moreover, in the purely Toeplitz band part, $\B_h^p$ and $\bC_h^p$ exhibit symmetry and skew-symmetry, respectively, relative to the first lower co-diagonal. In the top-left corner, the non-zero entries that do not follow the Toeplitz structure are the following:
%
\begin{equation*} 
    \vphantom{
    \begin{matrix}
    \overbrace{XYZ}^{\mbox{$R$}}\\ \\ \\ \\ \\ \\ \\ \\
    \underbrace{pqr}_{\mbox{$S$}} \\
    \end{matrix}}
    \begin{matrix}
        \vphantom{a}
        \coolleftbrace{p+1}{* \\ \vdots \\ * \\ * \vspace{0.5cm}} \vspace{0.1cm}\\ 
        \coolleftbrace{p-2}{* \\ \vdots \\ *}
    \end{matrix}
    \begin{pmatrix}
        \coolover{p-1}{*     & \ldots &     * \hspace{0.1cm}}& \coolover{p-1}{* & \phantom{***} & \phantom{*}  } 
        \\        \vdots &        & \vdots               &         \vdots & \ddots           & 
        \\        *      & \ldots & *                    & *              &  \ldots          &  *           
        \\         *     & \ldots &     *                &              * &  \ldots          &  *           &  
        \\        *      & \ldots & *                    &                &                  &              
        \\         *     & \ldots &     *                &                &                  &                            &
        \\               & \hspace{-0.2cm}\ddots & \vdots               &                &                   
        \\               &        &  \hspace{-0.3cm}*  \, \,\, *    &                &                   
    \end{pmatrix}.
\end{equation*}
%
A similar (persymmetric) structure holds for the bottom-right corner.
\end{enumerate}
%%
\end{proposition}
%%
Due to the scaling property~\ref{P1} in Proposition \ref{prop:37}, it is reasonable to introduce the families of matrices
%
\begin{equation} \label{eq:20}
    \{\B_n^p\}_n \quad \text{and} \quad \{\bC_n^p\}_n,
\end{equation}
%
with $\B_n^p := h\B_h^p$, $\bC_n^p := \bC_h^p$, and $n = T/h + p - 1$. Here and in the following sections, the subscript~$n$ denotes the size of the involved matrix. We also define the following scaled version of the system matrix in \eqref{eq:19}:
%
\begin{equation} \label{eq:21}
    \K_n^p(\rho) := \mi \B_n^p - \rho \bC_n^p,
\end{equation}
%
where we have set~$\rho = \mu h$. Thus, the relation~$\mathbf{K}_n^p(\rho) = h^{-1} \mathbf{K}_h^p(\mu)$ holds. We say that a family of matrices is composed of \emph{nearly Toeplitz} matrices if each matrix in the family is a perturbation of a Toeplitz matrix, where the perturbation matrix has a number of nonzero entries that is independent of $n$ and located only in the top-left and/or bottom-right corners. From Proposition \ref{prop:37}, the families $ \{\B_n^p\}_n $ and $ \{\bC_n^p\}_n $ consist of nearly Toeplitz matrices. Consequently, the family $ \{\K_n^p(\rho)\}_n $ also consists of nearly Toeplitz matrices.


\paragraph{Step 2. Weakly well-conditioning of nearly Toeplitz matrices.} \label{step:2} 
\phantom{12}\\ 
A family of nonsingular matrices $ \{\A_n\}_n $ with $ \A_n \in \C^{n \times n} $ is said to be \textit{well conditioned} if the condition numbers $ \kappa(\A_n) $ are uniformly bounded with respect to~$ n $. It is said to be~\textit{weakly well-conditioned} if~$ \kappa(\A_n) $ grows as a power of~$ n $. Clearly, these definitions do not depend on the chosen matrix norm.

Given coefficients $\{a_i\}_{i=-m}^k \subset \C$, we consider the family of Toeplitz band matrices $\{ \A_n \}_{n}$, with structure
%
\begin{equation} \label{eq:22}
\A_n =  
\setcounter{MaxMatrixCols}{20}
    \begin{pmatrix} 
            a_0 & \ldots & a_k & &  \\ 
            \vdots & \ddots & & \ddots \\
            a_{-m} & & \ddots & &  a_k \\
            & \ddots & & \ddots & \vdots \\
            &  & a_{-m} & \ldots & a_0 \\
    \end{pmatrix}_{n \times n}.
\end{equation}
%
We associate to the family $\{\A_n\}_n$, the \textit{symbol polynomial} $q^{\A} \in \P_{m+k}(\C)$ defined as
%
\begin{equation} \label{eq:23}
    q^{\A}(z) := \sum_{i=-m}^k a_i z^{m+i}.
\end{equation}
%
In \cite[Thm.~3]{AmodioBrugnano1996}, a sufficient condition for the weakly well-conditioning of a family of Toeplitz band matrices has been established, which involves locating the zeros of its symbol polynomial. We say that a polynomial 
is of type~$(s,u,\ell)$ if it has $s$ zeros with modulus smaller than $1$, $u$ zeros with unit modulus, and $\ell$ zeros with modulus larger than $1$.
%%
\begin{theorem}[{see~\cite[Thm.~3]{AmodioBrugnano1996}}] \label{th:38}
Let $\{\A_n\}_{n}$ represent a family of nonsingular Toeplitz band matrices as in \eqref{eq:22}, and let~$q^{\A}$ in \eqref{eq:23} be its symbol polynomial. Then, the family $\{\A_n\}_{n}$
\begin{itemize}
%%
\item[a)] is well conditioned if $q^{\A}$ is of type $(m,0,k)$;
%%
\item[b)] is weakly well-conditioned if $q^{\A}$ is of type $(m_1,m_2,k)$ or $(m,k_1,k_2)$, where $m_1+m_2=m$ and $k_1+k_2=k$.
\end{itemize}
%%
\end{theorem}
%%
Since the family of matrices $ \{\K_n^p(\rho)\}_n $ defined in \eqref{eq:21} consists of nearly Toeplitz matrices rather than Toeplitz matrices, we cannot directly apply Theorem \ref{th:38}. Instead, we use an auxiliary result derived in \cite{FerrariFraschini2025}.
%%
\begin{theorem}[{see~\cite[Thm.~4.5]{FerrariFraschini2025}}] \label{th:39}
Let $ \{\A_n\}_n $ be a family of nonsingular Toeplitz band matrices as in \eqref{eq:22}. Consider a family $ \{\widehat{\A}_n\}_n $ consisting of nonsingular nearly Toeplitz matrices that are perturbations of $ \{\A_n\}_n $, where the perturbations of each $ \widehat{\A}_n $ are only in the top-left and bottom-right blocks of size $(m+k) \times (m+k)$, with entries that are independent of $n$, i.e., the perturbation blocks are of the form
%
\begin{equation} \label{eq:24}
    \vphantom{
    \begin{matrix}
            \overbrace{XYZ}^{\mbox{$R$}} \\ \\ \\ \\ \\
            \underbrace{pqr}_{\mbox{$S$}} \\
        \end{matrix}}
    \begin{matrix}
        \coolleftbrace{m}{* \\ \vspace{0.15cm} \\ * } \vspace{0.1cm}\\ 
        \coolleftbrace{k}{* \\ \vspace{0.15cm} \\ *}
    \end{matrix}%
    \hspace{-0.15cm}
    \begin{pmatrix}
        \coolover{k}{*     & \ldots &     * \hspace{0.2cm}}& \coolover{m}{\squareasterisk & \phantom{**}  & \phantom{**}} 
        \\        \vdots &        & \vdots               &         \vdots & \ddots           & 
        \\         *     & \ldots &     *                &              * &  \ldots          &  \squareasterisk           
        \\         \squareasterisk     & \ldots &     *                &                &                  &                            
        \\               & \ddots & \vdots               &                &                  & 
        \\               &        & \squareasterisk                    &                &                  &  
        \end{pmatrix}, \quad\quad
         \vphantom{
    \begin{matrix}
            \overbrace{XYZ}^{\mbox{$R$}}\\ \\ \\ \\ \\ \\ \\ \\
            \underbrace{pqr}_{\mbox{$S$}} \\
        \end{matrix}}%
    \begin{pmatrix}
         &        &                &        \squareasterisk  &            & 
        \\              &  &                     &   \vdots            &  \ddots          &             
        \\              &                &                  & *     & \ldots &     \squareasterisk                             
        \\             \squareasterisk  & \ldots & *   &       *     &    \ldots            &                 *  
        \\               &  \ddots & \vdots                    &   \vdots             &              &  \vdots
        \\ \coolunder{k}{ \phantom{**}  & \phantom{**} &     \squareasterisk } & \coolunder{m}{* & \ldots & *} 
        \end{pmatrix}
        \hspace{-0.15cm}
    \begin{matrix}
        \coolrightbrace{* \\ \vspace{0.15cm} \\ * }{m} \vspace{0.1cm}\\ 
        \coolrightbrace{* \\ \vspace{0.15cm} \\ * }{k} \vspace{0.1cm}
    \end{matrix}%
\end{equation}
%
where the matrix on the left represents the top-left perturbation block, and the matrix on the right represents the bottom-right perturbation block. Furthermore, assume that the matrices $ \widehat{\A}_n $ have nonzero entries in the two outer codiagonals (the~$k^{\thh}$ and the~$(-m)^{\thh}$), i.e., the entries in the square boxes of the two perturbed blocks in \eqref{eq:24}. Under these conditions, the families $ \{\A_n\}_n $ and $ \{\widehat{\A}_n\}_n $ exhibit the same conditioning behavior.
\end{theorem}
%%
Theorem \ref{th:39} is applicable to $ \{\K_n^p(\rho)\}_n $, and to the family consisting of the extensions of the purely Toeplitz band parts of $ \K_n^p(\rho) $ to $ n \times n $ matrices, provided that we show the entries of the two outer codiagonals (the $(-p-1)^{\text{th}}$ and the $(p-1)^{\text{th}}$) of $\K_n^p(\rho)$ are nonzero for all $\rho>0$ and $p \in \N$. This fact is an immediate consequence of 
definition~\eqref{eq:21}, and of~\cite[Prop.~3.6]{FerrariFraschiniLoliPerugia2024}, which shows that, for all $ p \in \mathbb{N} $, the entries of these codiagonals in both $ \bC_n^p $ and $ \B_n^p $ are nonzero.
%%
\paragraph{Step 3. Reciprocity of the symbol polynomial \texorpdfstring{$q^{\K^p(\rho)}$}{1}} \label{step:3} \phantom{123}\\
By virtue of Theorem~\ref{th:39}, to study the stability of problem \eqref{eq:10}, it suffices to study the conditioning of the family of extensions of the purely Toeplitz band parts of~$ \K_n^p(\rho) $. Without ambiguity, we associate the symbol polynomial $ q^{\K^p(\rho)} $ of this family with the family of nearly Toeplitz matrices $ \{\K_n^p(\rho)\}_n $. We proceed similarly for $ \{\B_n^p\}_n $ and $ \{\bC_n^p\}_n $, denoting their symbol polynomials by~$ q^{\B^p} $ and $ q^{\bC^p} $, respectively. From property~\ref{P3} in Proposition \ref{prop:37}, the polynomials $ q^{\B^p} $ and $ q^{\bC^p} $ have degree $2p$, and their coefficients depend only on~$p$. By linearity of the symbol polynomials, we deduce
%
\begin{equation} \label{eq:25}
    q^{\K^p(\rho)}(z) = q^{\B^p}(z) + \rho q^{\bC^p}(z).
\end{equation}
%
In the next proposition, we show that $q^{\K^p(\rho)}$ is a \textit{reciprocal} polynomial, meaning that if $\xi \in \mathbb{C}$ is a root of $q^{\K^p(\rho)}$, then $\xi^{-1}$ is also a root. Using this information, we then prove that, if~$q^{\K^p(\rho)}$ has two zeros with unitary modulus, then the family $\{ \K_n^p(\rho) \}_n$ is weakly well-conditioned.
%%
\begin{proposition} \label{prop:39}
The symbol polynomial $q^{\mathbf{K}^p(\rho)}$ of the family $\{ \K_n^p(\rho) \}_n$ defined in \eqref{eq:21} is a reciprocal polynomial. As a consequence, if the polynomial $q^{\K^p(\rho)}$ has two zeros of unit modulus, and if Assumption \ref{assu:34} is satisfied, then the family $\{ \K_n^p(\rho) \}_n$ is weakly well-conditioned.
\end{proposition}
%%
\begin{proof}
From the symmetry and antisymmetry of the matrices $\B_n^p$ and $\bC_n^p$ (see property~\ref{P3} in Proposition~\ref{prop:37}), the polynomials $q^{\B^p}$ and $q^{\bC^p}$ can be expressed as
%
\begin{align*}
    q^{\B^p}(z) & = b_0 + b_1 z + \ldots + b_p z^p + \ldots + b_1 z^{2p-1} + b_0 z^{2p} = z^p \sum_{j=0}^p b_j \left( z^{-(p+j)} + z^{p+j} \right),
    \\ q^{\bC^p}(z) & = c_0 + c_1 z + \ldots + c_{p-1} z^{p-1} - c_{p-1} z^{p+1} - \ldots - c_1 z^{2p-1} - c_0 z^{2p}= z^p \sum_{j=0}^p c_j \left( z^{-(p+j)} - z^{p+j} \right),
\end{align*}
%
for some coefficients $\{b_j\}, \{c_j\} \subset \R$ with $b_0 \neq 0$ and $c_0 \neq 0$ (see also Section \ref{step:2}). In particular, from these expressions, both $q^{\B^p}$ and $q^{\bC^p}$ are reciprocal polynomials, and from \eqref{eq:25}, it follows that $q^{\K^p(\rho)}$ is also a reciprocal polynomial for all $\rho \in \R$. As a consequence, $q^{\K^p(\rho)}$ is a polynomial of type $(\ell, 2p - 2\ell, \ell)$ for some $\ell = 0, \dots, p$. In the setting of Theorem \ref{th:38}, for the matrices $\K^p_n(\rho)$, it holds that~$k = p - 1$ and~$m = p + 1$. Therefore, we can guarantee weakly well-conditioning (see also Theorem \ref{th:39}) if $\ell = p - 1$, resulting in exactly $2p - 2\ell = 2$ zeros of unit modulus for $q^{\K^p(\rho)}$.
\end{proof}
%%
In the next section, we explicitly compute the restriction of $q^{\K^p(\rho)}$ to the boundary of the unit circle and show that, for all $\rho \in \R$, it has two zeros of unit modulus.

%%%
\paragraph{Step 4. Number of zeros of unitary modulus of the symbol polynomial~$q^{\K^p(\rho)}$} \label{step:4} \phantom{}\\
The aim of this section is to derive an explicit expression for $q^{\K^p(\rho)}(e^{\mi \theta})$ with~$\theta \in [-\pi,\pi]$ and subsequently show that, for all $p \in \mathbb{N}$ and $\rho \in \R$, there exist exactly two values of $\theta$, both with multiplicity one, such that $q^{\K^p(\rho)}(e^{\mi \theta}) = 0$. These simple zeros, expressed in polar coordinates, correspond bijectively to the simple complex zeros of $q^{\K^p(\rho)}$, as we establish in the following lemma.
%%
\begin{lemma} \label{lem:310}
Let $f : \mathbb{C} \to \mathbb{C}$ be a complex function. Then, $z = e^{\mi \theta}$ with~$\theta \in [-\pi,\pi]$, is a simple zero of $f$ if and only if $\theta$ is a simple zero of the function $F(\theta) := f(e^{\mi \theta})$.
\end{lemma}
%%
\begin{proof}
From the chain rule, we have
%
\begin{equation*}
    F'(\theta) = \frac{\text{d}}{\text{d}\theta} f(e^{\mi \theta}) = \mi e^{\mi \theta} f'(e^{\mi \theta}).
\end{equation*}
%
Therefore, $F'(\theta) \neq 0$ if and only if $f'(e^{\mi \theta}) \neq 0$, which shows that $z = e^{\mi \theta}$ is a simple zero of $f$ if and only if $\theta$ is a simple zero of $F$.
\end{proof}
%%
In the next proposition, we recall the explicit expressions for the symbol polynomials $q^{\B^p}$ and $q^{\bC^p}$ established in \cite[Lemma 7]{GaroniManniPelosiSerraCapizzanoSpeleers2014} and \cite[Prop.~3.7]{FerrariFraschiniLoliPerugia2024}.
%%
\begin{proposition} \label{prop:311}
For~$p \ge 1$ and~$\theta \in [-\pi,\pi]$, define the functions ~$B_p, C_p : [-\pi,\pi] \to \R$ as
%
\begin{equation*}
    B_p(\theta) := -(2-2\cos \theta)^{p+1} \sum_{j \in \Z} \frac{1}{(\theta + 2j\pi)^{2p}}, \quad C_p(\theta) := -(2-2\cos \theta)^{p+1} \sum_{j \in \Z} \frac{1}{(\theta + 2j\pi)^{2p+1}}.
\end{equation*}
%
Then, the symbol polynomials $q^{\B^p}$ and $q^{\bC^p}$ associated with the families in \eqref{eq:20}, are given by
%
\begin{equation*}
     q^{\mathbf{B}^p}(e^{\mi \theta}) = - e^{\mi p \theta}  B_p(\theta), \quad\quad q^{\mathbf{C}^p}(e^{\mi \theta}) = - e^{\mi p \theta}\mi C_p(\theta).
\end{equation*}
%
\end{proposition}
%%
As an important consequence, combining Proposition \ref{prop:311} and \eqref{eq:25}, we obtain the following explicit expression for the symbol polynomial of the family $\{\K_n^p(\rho)\}_n$:
%
\begin{equation*} 
     q^{\mathbf{K}^p(\rho)}(e^{\mi \theta})  =  \mi e^{\mi p \theta}( - B_p(\theta) + \rho C_p(\theta)), \quad \rho \in \R, \ \theta \in [-\pi,\pi], \text{~and~} p \in \N.
\end{equation*}
%
In view of Proposition \ref{prop:39}, we need to verify that, for all~$\rho \in \R$, $q^{\K^p(\rho)}(e^{\mi \theta})$ has exactly two simple zeros (as a function of~$\theta$). To this aim, we define the auxiliary function
%
\begin{equation*}
    K_p : [-\pi,\pi] \times \R \to \R, \quad K_p(\theta,\rho) := -B_p(\theta) + \rho C_p(\theta).
\end{equation*}
%
Observe that $K_p(\theta,\rho) = 0$ if and only if $q^{K^p(\rho)}(e^{\mi \theta})=0$.
%%
\begin{proposition} \label{prop:312}
For~$\rho>0$ and~$p \in \mathbb{N}$, the function $K_p(\theta,\rho)$ has exactly 2 simple zeros %in 
$\theta \in [-\pi,\pi]$.
\end{proposition}
%%
\begin{proof}
We begin by recalling some useful limit properties of the functions $ B_p$ and $C_p$. The corresponding proofs can be found in~\cite[Lemma 3.8]{FerrariFraschiniLoliPerugia2024} and~\cite[Cor.~5.4]{FerrariFraschini2025}:
%
\begin{equation} \label{eq:27}
\begin{aligned} 
     \lim_{\theta \to 0} B_p(\theta) = \lim_{\theta \to 0}  C_p(\theta) & = 0 , \quad  C_p(-\pi)=C_p(\pi)=0, \quad B_p(\pi)=B_p(-\pi)<0,
    \\  & \lim_{\theta \to 0} B_p'(\theta) = 0, \quad \lim_{\theta \to 0} C_p'(\theta) = -1.
\end{aligned}
\end{equation}
%
We deduce that 
$\theta=0$ is a simple zero of~$K_p(\theta,\rho)$, as
%
\begin{equation*}
    \lim_{\theta \to 0} K_p(\theta,\rho) = 0, \quad \lim_{\theta \to 0} \partial_\theta K_p(\theta,\rho) = -\rho.
\end{equation*}
%
It remains to show that $K_p(\theta,\rho)=0$ has exactly one solution in $\theta \in [-\pi,0) \cup (0,\pi]$, and that such a zero is simple. For~$\theta \in (-\pi,0) \cup (0,\pi)$, we define the auxiliary function
%
\begin{equation*}
    L_p(\theta,\rho) := \frac{K_p(\theta,\rho)}{C_p(\theta)} = -\frac{B_p(\theta)}{C_p(\theta)} + \rho
\end{equation*}
%
The following limits are a direct consequence of~\eqref{eq:27}:
%
\begin{equation*}
    \lim_{\theta \to 0} L_p(\theta, \rho) = \rho, \qquad \lim_{\theta \to -\pi^+} L_p(\theta, \rho) = +\infty, \qquad \lim_{\theta \to \pi^-} L_p(\theta, \rho) = -\infty.
\end{equation*}
%
Hence, the function $L_p(\theta, \rho)$ admits a continuous extension at $\theta = 0$. 

We now aim at proving that~$L_p(\theta, \rho)$ is strictly decreasing on~$(-\pi, \pi)$. From this, we immediately deduce that the equation $L_p(\theta, \rho) = 0$ admits exactly one solution in $(-\pi, \pi)$, and that this zero is simple. Consequently, the same conclusion holds for $K_p(\theta, \rho)$. We now proceed to show the monotonicity of $L_p(\theta, \rho)$. Note that  $\partial_\theta L_p(\theta,\rho) = \partial_\theta (L_p(\theta,\rho)-\rho)$, and~$L_p(\theta,\rho)-\rho = -B_p(\theta)/C_p(\theta)$ is an odd function in~$\theta$ that is independent of~$\rho$. Therefore, it is enough to study~$L_p(\theta,\rho)$ only for~$\theta \in (0,\pi)$.

For $k \in \mathbb{N}$ and $k \ge 2$, define the auxiliary functions $\widehat{U}_k: (0,\pi) \to \R$ as 
%
\begin{equation*}
    \widehat{U}_k(\theta) := \sum_{j \in \Z} \frac{1}{(\theta+2j\pi)^k},
\end{equation*}
%
and note that, for $\theta \in (0,\pi)$, it holds 
%
\begin{align*}
    \partial_\theta L_p(\theta,\rho) & = -\partial_\theta  \left(\frac{\widehat{U}_{2p}(\theta)}{\widehat{U}_{2p+1}(\theta)}\right) = \frac{-\widehat{U}'_{2p}(\theta)\widehat{U}_{2p+1}(\theta) + \widehat{U}_{2p}(\theta) \widehat{U}_{2p+1}'(\theta)}{(\widehat{U}_{2p}(\theta))^2}.
\end{align*}
%
Using the identity $\widehat{U}_k'(\theta) = -k \widehat{U}_{k+1}'(\theta)$, we further obtain 
%
\begin{align*}
    \partial_\theta L_p(\theta,\rho) =  \frac{2p(\widehat{U}_{2p+1}(\theta))^2 - (2p+1)\widehat{U}_{2p}(\theta) \widehat{U}_{2p+2}(\theta)}{(\widehat{U}_{2p}(\theta))^2}.
\end{align*}
%
It remains to show that, for all $\theta \in (0,\pi)$,
%
\begin{equation} \label{eq:28}
    2p(\widehat{U}_{2p+1}(\theta))^2 - (2p+1) \widehat{U}_{2p}(\theta) \widehat{U}_{2p+2}(\theta) < 0.   
\end{equation}
%
It is shown in \cite[Lemma A.1]{FerrariFraschiniLoliPerugia2024} that $\widehat{U}_{2p+1}(\theta) < \theta \widehat{U}_{2p+2}(\theta)$\footnote{In the notation of \cite{FerrariFraschiniLoliPerugia2024}, $\widehat{C}_p(\theta) = -\widehat{U}_{2p+1}(\theta)$ and $\widehat{B}_p(\theta) = -\widehat{U}_{2p}(\theta)$} and since $\widehat{U}_{2p+2}(\theta)>0$, then \eqref{eq:28} holds true provided that
%
\begin{equation*}
    2p (\theta^2 \widehat{U}_{2p+2}(\theta) - \widehat{U}_{2p}(\theta)) -  \widehat{U}_{2p}(\theta) < 0.   
\end{equation*}
%
This latter follows from $\widehat{U}_{2p}(\theta)>0$ and~\cite[Lemma 1]{EkstromFurciGaroniManniSerraCapizzanoSpeleers2018}, where it is shown $\theta^2 \widehat{U}_{2p+2}(\theta) < \widehat{U}_{2p}(\theta)$\footnote{In the notation of \cite{EkstromFurciGaroniManniSerraCapizzanoSpeleers2018}, $e_p(\theta) = \widehat{U}_{2p}(\theta)/\widehat{U}_{2p+2}(\theta)$}.
\end{proof}
%%
Combining Propositions \ref{prop:39} and \ref{prop:312}, we obtain the main result of the paper.
%%
\begin{theorem} \label{th:313}
Let Assumption \ref{assu:34} be satisfied. Then, for all~$p \in \N$ and~$\rho \in \R$, the family of matrices~$\{\K_n^p(\rho)\}_n$ defined in~\eqref{eq:21} is weakly well-conditioned. In other words, the variational formulation in \eqref{eq:10} is
unconditionally stable.
\end{theorem}
%%

In Figure~\ref{fig:0}, we present the condition numbers of the system matrices~$\{\K_n^p(\rho)\}_n$ 
with fixed size~$n=1000$, for~$p \in \{1, 2, 3, 4, 5, 6\}$, as the parameter~$\rho$ varies over the range~$[1, 100]$. As predicted by Theorem~\ref{th:313}, the condition numbers exhibit only mild dependence on~$\rho = \mu h$ and no CFL-type restrictions are observed or required to ensure stability.

