\section{First-order-in-time isogeometric method for the wave equation} \label{sec:4}

There is a natural connection between the variational formulation~\eqref{eq:10} and the first-order-in-time formulation  in~\cite[Eq. (6)]{FerrariFraschiniLoliPerugia2024} for the wave equation. In this section, we recall the ODE counterpart of the latter formulation, and exploit its connection with~\eqref{eq:10} to derive an alternative proof of its unconditional stability, which follows directly from Theorem~\ref{th:313}. We remark that the original proof of stability in~\cite{FerrariFraschiniLoliPerugia2024} is more involved and relies on a numerical verification, which has only been computed for spline spaces of degree up to~$p = 17$. Such a limitation is overcome in Theorem~\ref{th:42}, thus showing  that the method in~\cite{FerrariFraschiniLoliPerugia2024} is unconditionally stable for all~$p \in \N$.

Let $\mu_s \in \mathbb{R}$ denote the parameter associated with the IVP~\eqref{eq:9}, and let~$\mu_w > 0$ denote the corresponding parameter for the wave equation in its first-order-in-time formulation. Given $f \in L^2(0,T)$,
we consider the following IVP: find $u, v \in H^1(0,T)$ such that

%
\begin{equation} \label{eq:29}
    \begin{cases}
    \dpt v(t) - u(t) = 0 & t \in (0,T), \\
    \dpt u(t) + \mu_w v(t) = f(t) & t \in (0,T), \\
    u(0) = 0, \quad v(0) = 0.
    \end{cases}
\end{equation}
%
The discrete variational formulation %for
of~\eqref{eq:29} proposed in~\cite{FerrariFraschiniLoliPerugia2024} reads:
%%
\begin{tcolorbox}[
    colframe=black!50!white,
    colback=blue!5!white,
    boxrule=0.5mm,
    sharp corners,
    boxsep=0.5mm,
    top=0.5mm,
    bottom=0.5mm,
    right=0.25mm,
    left=0.1mm
]
    \begingroup
    \setlength{\abovedisplayskip}{0pt}
    \setlength{\belowdisplayskip}{0pt}
    \, find~$u_h^p \in S_{h,0,\bullet}^p(0,T;\R)$ and $v_h^p \in S_{h,0,\bullet}^p(0,T;\R)$ such that \vspace{0.1cm}
    %
\begin{equation} \label{eq:30}
	\begin{cases}
		(\dpt u_h^p, \dpt \chi_h^p)_{J_T} + (\dpt v_h^p, \chi_h^p)_{J_T} = 0 & \text{for all~} \chi_h^p \in S_{h,\bullet,0}^p(0,T;\R),
		\\ (\partial_t v_h^p, \partial_t \lambda_h^p)_{J_T} - \mu_w (\partial_t u_h^p, \lambda_h^p)_{J_T} = (f,\partial_t \lambda_h^p)_{J_T} & \text{for all~} \lambda_h^p \in S_{h,\bullet,0}^p(0,T;\R).
	\end{cases}
\end{equation}
%
    \endgroup
\end{tcolorbox}
%%
In the next result, we highlight the connection between the variational formulations~\eqref{eq:10} and~\eqref{eq:30}.
%%
\begin{proposition} \label{prop:41}
Let $f = f_r + \mi f_i$ with $f_r$ and~$f_i$ functions with real values. Then,
%
\begin{equation*}
    \psi_h^p = u_h^p~+ \mi v_h^p \in~S_h^p(0,T;\C)
\end{equation*}
%
is a solution to problem~\eqref{eq:10} with $\Psi_0=0$ if and only if the real-valued functions $u_h^p \in +S^p_{h,0,\bullet}(0,T;\R)$ and $v_h^p \in S_{h,0,\bullet}^p(0,T;\R)$ satisfy
%
\begin{equation} \label{eq:31}
\begin{cases}
    (\dpt u_h^p, \chi_h^{p-1})_{J_T} + \mu_s (v_h^p, \chi_h^{p-1})_{J_T} = (f_i, \chi_h^{p-1})_{J_T} & \text{for all}~\chi_h^{p-1} \in S_h^{p-1}(0,T;\R),
    \\ (\dpt v_h^p, \lambda_h^{p-1})_{J_T} - \mu_s (u_h^p, \lambda_h^{p-1})_{J_T} = - (f_r, \lambda_h^{p-1})_{J_T} & \text{for all}~\lambda_h^{p-1} \in S_h^{p-1}(0,T;\R),
\end{cases}
\end{equation}
%
or, equivalently,
%
\begin{equation} \label{eq:32}
\begin{cases}
    (\dpt u_h^p, \dpt \chi_h^p)_{J_T} - \mu_s (\dpt v_h^p, \chi_h^p)_{J_T} = (f_i, \dpt \chi_h^p)_{J_T} & \text{for all}~\chi_h^p \in S_{h,\bullet,0}^p(0,T;\R),
    \\ (\dpt v_h^p, \dpt \lambda_h^p)_{J_T} + \mu_s (\dpt u_h^p, \lambda_h^p)_{J_T} = - (f_r, \dpt \lambda_h^p)_{J_T} & \text{for all}~\lambda_h^p \in S_{h,\bullet,0}^p(0,T;\R).
\end{cases}
\end{equation}
%
\end{proposition}
\begin{proof}
Setting $\psi_h^p = u_h^p + \mi v_h^p$, then problem \eqref{eq:10} is equivalent to: find $u_h^p \in S^p_{h,0,\bullet}(0,T;\R)$ and $v_h^p \in  S_{h,0,\bullet}^p(0,T;\R)$ such that
%
\begin{equation*}
    \mi (\dpt u_h^p, w_h^{p-1})_{J_T} - (\dpt v_h^p, w_h^{p-1})_{J_T}  
    + \mu_s (u_h^p,  w_h^{p-1})_{J_T} + \mi \mu_s (v_h^p, w_h^{p-1})_{J_T} = (f_r, w_h^{p-1})_{J_T} + \mi (f_i, w_h^{p-1})_{J_T}
\end{equation*}
%
for all $w_h^{p-1} \in S_h^{p-1}(0,T;\R)$. Then, \eqref{eq:31} follows by taking the imaginary and real parts of this equation. 
\end{proof}
%%
With the data $\mu_s=-1$, $\mu_w=1$, $f_r = -f$, and~$f_i=0$ problem \eqref{eq:32} coincides with the variational formulation \eqref{eq:30}. Therefore, we expect the two methods to exhibit similar stability properties. In fact, both methods 
turn out to be unconditionally stable. Here, we show that the stability of method~\eqref{eq:30} is a consequence of Theorem \ref{th:313}.
%%
\begin{theorem} \label{th:42}
Assume that, for all $p \in \N$ with $p \ge 1$, $h>0$, and $\mu_w > 0$ the variational formulation~\eqref{eq:30} admits a unique solution. Then, \eqref{eq:30} is unconditionally stable.
\end{theorem}
%%
\begin{proof}
Recalling the definitions of $\B_h^p$ and $\bC_h^p$ from~\eqref{eq:18}, we observe that the system matrices associated with formulations \eqref{eq:32} and \eqref{eq:30} are, respectively,
%
\begin{equation} \label{eq:33}
\begin{pmatrix}
    \B_h^p & -\mu_s \bC_h^p \\
    \mu_s \bC_h^p & \B_h^p 
\end{pmatrix} 
\quad\quad\text{and}\quad\quad 
\begin{pmatrix}
    \B_h^p &  \bC_h^p \\
    -\mu_w \bC_h^p & \B_h^p 
\end{pmatrix}.
\end{equation}
%
In~\cite[Prop.~3.10]{FerrariFraschiniLoliPerugia2024}, it was shown that the matrices~$\{\B_h^p\}_{h}$ are invertible. Therefore, the Schur complements
%
\begin{equation*} 
     \B_h^p + \mu_s^2 \bC_h^p (\B_h^p)^{-1} \bC_h^p \quad \text{and} \quad \B_h^p + \mu_w \bC_h^p (\B_h^p)^{-1} \bC_h^p,
\end{equation*}
%
associated with the matrices in \eqref{eq:33} are both well defined. Theorem \ref{th:313} guarantees the stability of the variational formulation~\eqref{eq:10}, and, consequently, that of~\eqref{eq:32}. Moreover, Lemma \ref{lem:a1} implies that the corresponding family of Schur complements is weakly well-conditioned for all $\mu_s \in \R$. This follows from the fact that $\| \bC_h^p\|$ depends only on $p$ (see property~\ref{P1} in Proposition~\ref{prop:37}), and that the family~$\{\B_h^p\}_h$ is weakly well-conditioned (see~\cite[Prop.~3.10]{FerrariFraschiniLoliPerugia2024}). By choosing~$\mu_s = \sqrt{\mu_w}$, the Schur complements for both matrices in~\eqref{eq:33} coincide. Hence, the weakly well-conditioning of these Schur complements implies the stability of formulation~\eqref{eq:30} for all $p \in \mathbb{N}$.
\end{proof}
%%

\section{Numerical results} \label{sec:5}
In this section, we present an efficient implementation strategy for the discretization of the space--time method~\eqref{eq:7} (Section~\ref{sec:51}). Subsequently, using an isogeometric discretization also in space, 
we validate the theoretical stability results established in this work and demonstrate the quasi-optimal $h$-convergence and conservation properties of the proposed method (Section~\ref{sec:52})\footnote{All numerical test are performed with Matlab R2024a. The codes used for the numerical tests are available in the GitHub repository \cite{FerrariCodes2025}.}.

%%%
\subsection{Solver} \label{sec:51}
To express the matrix form of the discrete variational formulation of~\eqref{eq:10}, we  denote by~$\bC^p_{h_t}$ and~$\B^p_{h_t}$ the temporal matrices introduced in~\eqref{eq:18}. Likewise, let~$\bM_{h_{\bx}}$ and~$\A_{h_{\bx}}$ denote the spatial mass matrix and the matrix representing the discretization of the Hamiltonian operator, respectively. The resulting global linear system takes the form
%
\begin{equation} \label{eq:35}
    (\mi \B_{h_t}^p \otimes \M_{h_{\bx}} + \bC_{h_t}^p \otimes \A_{h_{\bx}}) \boldsymbol{\Psi}^p_{\bh} = \mathbf{F}_{\bh}^p
\end{equation}
%
where~$\otimes$ denotes the Kronecker product. The vector $\boldsymbol{\Psi}_{\bh}^p$ collects the coefficients of the discrete unknown $\Psi_{\bh}^p$ with respect to the chosen basis of
$S_{h_t,0,\bullet}^p(0,T) \otimes S_{h_{\bx}}(\Omega)$ ordered appropriately. Similarly, $\mathbf{F}^p_{\bh}$ represents the vector form of the term on the right-hand side of~\eqref{eq:7}.

We now present an efficient algorithm for solving the linear system \eqref{eq:35}. This procedure is essentially a variant of the \emph{Bartels–Stewart method} \cite{BartelsStewart1972}, which relies on the complex Schur decomposition of the matrix $\mi (\B_{h_t}^p)^{-1} \bC_{h_t}^p$. Specifically, the involved decomposition reads
%
\begin{equation*}
    (\mathbf{Q}_{h_t}^p)^H (\mi \B_{h_t}^p)^{-1} \bC_{h_t}^p \mathbf{Q}_{h_t}^p = \mathbf{R}_{h_t}^p,
\end{equation*}
%
where~$\mathbf{Q}_{h_t}^p$ is a unitary matrix, the superscript~$H$ denotes the conjugate transpose, and~$\mathbf{R}_{h_t}^p$ is an upper triangular matrix.

The main steps of the algorithm are summarized in Algorithm~\ref{alg:1} (see also \cite{FerrariFraschiniLoliPerugia2024, LangerZank2021, Tani2017} for similar algorithms).

\begin{algorithm}[ht!]
\caption{Efficient implementation for solving the system \eqref{eq:35}} \label{alg:1}
\begin{algorithmic}[1]
    %%  
    \State \textbf{Compute} the complex Schur decomposition $(\mathbf{Q}_{h_t}^p,\mathbf{R}_{h_t}^p)$ of $(\mi \B_{h_t}^p)^{-1} \bC_{h_t}^p$, and compute $(\mathbf{R}_{h_t}^p)^{-1}$
    \vspace{0.1cm}
    %%
    \State \textbf{Solve} for $\boldsymbol{Y}_{\hspace{-0.09cm}\bh}^p$ the system $\left({\B}^{p}_{h_t} \otimes \mathbf{I}_{h_{\bx}} \right) \boldsymbol{Y}_{\hspace{-0.09cm} \bh}^p = \mathbf{F}_{\bh}^p$
    \vspace{0.1cm}
    %%
    \State \textbf{Update} $\boldsymbol{Y}_{\hspace{-0.09cm} \bh}^p \leftarrow \left((\mathbf{Q}_{h_t}^p)^H \otimes \mathbf{I}_{h_{\bx}}\right) \boldsymbol{Y}_{\hspace{-0.09cm} \bh}^p$
    \vspace{0.1cm}
    %%
    \State \textbf{Solve} for $\boldsymbol{Z}_{\hspace{-0.04cm} \bh}^p$ the system $\left(\mathbf{R}^p_{h_t} \otimes \A_{h_{\bx}} + (\mathbf{R}^p_{h_t})^{-1} \otimes \M_{h_{\bx}}\right) \boldsymbol{Z}_{\bh}^p =\boldsymbol{Y}_{\bh}^p$
    \vspace{0.1cm}
    %%
    \State \textbf{Compute} the final solution~$\boldsymbol{\Psi}_{\bh}^p = -(\mathbf{Q}_{h_t}^p \otimes \mathbf{I}_{h_{\bx}}) \boldsymbol{Z}_{\bh}^p$
\end{algorithmic}
\end{algorithm}
%

In particular, \textit{step} 2 only requires solving a set of completely independent small linear systems with the same matrix~$\B_{h_t}^p$, \textit{steps} 3 and 5 involve just matrix-vector products, and the matrix of the linear system in \textit{step} 4 has a block upper triangular structure.


\subsection{Numerical experiments} \label{sec:52}
We now consider some numerical experiments on the $(1+1)$-dimensional cylinder $Q_T = \Omega \times (0,1)$ with $\Omega = (-3,3)$. The exact solution is chosen from the following well-known family (see, e.g., \cite[\S2.3]{Griffiths1995}):
%
\begin{equation} \label{eq:36}
    \Psi^{(n)}(x,t) = \frac{1}{\sqrt{2^n n!}} \left( \frac{\omega}{\pi} \right)^{1/4}
    H_n\left( \sqrt{\omega} x \right) \exp\left( -\frac{1}{2} (\omega x^2 + (2n+1)i \omega t) \right), \quad n \in \mathbb{N},
\end{equation}
%
where $H_n(\cdot)$ is the $n$th physicist's Hermite polynomial, as defined in \cite[Table 18.3.1]{OlverFrankLozeirClark2010}. These functions are exact solutions of the Schrödinger equation with potential $V(x) = -\omega^2 x^2/2$, modeling a quantum harmonic oscillator with angular frequency $\omega > 0$. The source term is $F(\bx,t) = 0$, and the initial condition is given by $\Psi_0(x) = \Psi^{(n)}(x,0)$. In our tests, we fix $\omega = 10$ and~$n = 2$.

For the space–time Galerkin discretization \eqref{eq:7}, we employ maximal regularity splines over uniform meshes for both the spatial and temporal domains. The discrete spaces~$S_{h_{\bx}}$ and~$S_{h_t}^{p_t}(0,T)$ use the same polynomial degree~$p_{\bx} = p_t = p$, but we allow for different mesh sizes~$h_{\bx}$ and $h_t$. The initial condition is approximated by $\Pi_{\bx} \Psi_0$, which denotes the~$L^2(\Omega)$ projection of~$\Psi_0$ onto~$S_{h_{\bx}}$.

We compute the relative 
errors in the following norms:
%
\begin{equation} \label{eq:38a}
\begin{aligned}
     \| \Psi \|_{H^1(Q_T)} := \| \partial_t \Psi \|_{L^2(Q_T)} + \| \nabla_{\bx} \Psi \|_{L^2(Q_T)} \quad\quad \| \Psi \|_{L^2(Q_T)} := \left(\int_0^T \int_\Omega |\Psi(\bx,t)|^2 \, \dd \bx \, \dd t\right)^{\frac{1}{2}}.
    \end{aligned}
\end{equation}

\paragraph{Stability.}
To verify the unconditional stability of the method (i.e., absence of a CFL-type restriction such as~$h_t \le C h_{\bx}^2$, we fix~$h_t = 0.0625$ and progressively decrease~$h_{\bx}$. Figure~\ref{fig:1} shows the relative $L^2(Q_T)$ and $H^1(Q_T)$ errors for different polynomial degrees. The results confirm that the method remains stable and free of spurious oscillations even for highly refined spatial meshes.

