\section{Auxiliary result}

%%
\begin{lemma} \label{lem:a1}
Consider an invertible $2 \times 2$ block matrix 
%
\begin{equation*}
\mathbf{M} =
    \begin{pmatrix}
        \B & -\bC \\
        \bC & \B
    \end{pmatrix}
\end{equation*}
%
with $\B, \bC \in \R^{n \times n}$. Suppose also that~$\B$ is invertible, and define the Schur complement~$\bS =~\B~+~\bC~\mathbf{B}^{-1} \bC$. Then, it holds
%
\begin{equation*}
    \kappa (\bS)  \le \left(1 + \frac{\| \bC \|^2}{\| \B\|^2} \kappa(\B)\right) \kappa(\bM).
\end{equation*}
%
where $\| \cdot \|$ denotes either the $\| \cdot \|_\infty$- or the $\| \cdot \|_1$-norm, and the condition number is computed with respect to the same norm.
\end{lemma}

\begin{proof}
First, we compute 
%
\begin{equation} \label{eq:38}
    \| \bS \| \le \| \B \| + \| \B^{-1} \| \| \bC \|^2.
\end{equation}
%
Then, using the inversion formula (see, e.g., \cite[\S 0.8.5]{HornJohnson2013}), we get 
%
\begin{equation*}
\bM^{-1} = 
\begin{pmatrix}
    \B^{-1} - \B^{-1} \bC \bS^{-1} \bC \B^{-1} & \B^{-1} \bC \bS^{-1} \\
    -\bS^{-1} \bC \B & \bS^{-1}
\end{pmatrix}.
\end{equation*}
%
Being a subpart of the full matrix, we deduce $\| \bS^{-1} \| \le \| \bM^{-1} \|$. Similarly, we also know that~$\| \B \| \le \| \bM\|$. Combining these two estimates with~\eqref{eq:38}, we conclude
%
\begin{align*}
    \kappa (\bS) = \| \bS \| \| \bS^{-1} \| \le (\| \B \| + \| \B^{-1} \| \| \bC \|^2) \| \bM^{-1} \| & \le \left(\| \B \| + \| \bC \|^2 \frac{\kappa(\B)}{\| \B \|}\right) \frac{\kappa(\bM)}{\| \bM \|} 
    \\ & \le \left(1 + \frac{\| \bC \|^2}{\| \B\|^2} \kappa(\B)\right) \kappa(\bM),
\end{align*}
which completes the proof.
%
\end{proof}
