\observationCases*
\begin{proof}

    Consider $g(a):=|5a+3|+|3a+5|-\frac{5}{2}\sqrt{a^2+1}$.
    We use a case distinction to show $g(a)>0$. First, note that $g(-\frac{5}{3})>0$ and $g(-\frac{3}{5})>0$.

    \begin{itemize}
        \item 
    For $a<-\frac{5}{3}$, $g$ is given by $g(a)=-5a-3-3a-5-\frac{5}{2}\sqrt{a^2+1}$. For the first derivative of $g$, it holds that \[\frac{dg}{da} = -8-\frac{5a}{2\sqrt{a^2+1}} \leq -8 + \left|\frac{5a}{2\sqrt{a^2+1}}\right| \leq -8+\frac{5}{2}<0.\] Since $g(-\frac{5}{3})>0$, it follows that $g(a)>0$ for $a < -\frac{5}{3}$.

    \item 
    For $a>-\frac{3}{5}$, $g$ is given by $g(a)=5a+3+3a+5-\frac{5}{2}\sqrt{a^2+1}$. For the first derivative of $g$, it holds that \[\frac{dg}{da} = 8-\frac{5a}{2\sqrt{a^2+1}} \geq 8 - \left|\frac{5a}{2\sqrt{a^2+1}}\right| \geq 8-\frac{5}{2}>0.\] Since $g(-\frac{3}{5})>0$, it follows that $g(a)>0$ for $a < -\frac{3}{5}$.

    \item 
    Finally, for $-\frac{5}{3}\leq a\leq -\frac{3}{5}$, $g$ is given by $g(a)=-5a-3+3a+5-\frac{5}{2}\sqrt{a^2+1}$. For the second derivative of $g$, it holds that \[\frac{d^2g}{da^2} = -\frac{5}{2(a^2+1)^\frac{3}{2}}<0.\] Since $g$ is concave and both $g(-\frac{5}{3})>0$ and $g(-\frac{3}{5})>0$, it follows that $g(a)>0$ for $-\frac{5}{3}\leq a\leq -\frac{3}{5}$.

    \end{itemize}

\end{proof}

